window.EVENTS_A=[{"id":"A-001","branch":"A","stage":1,"day":1,"shichen":"辰时","checkpoint":"及笄","scene":"今日你十五，及笄。爹天不亮就起来了，在铺子里踱来踱去：「我闺女及笄，柜上今日歇业半日！」","options":[{"text":"劝爹照常开门","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"爹想了想：「也是，生意人的体面在柜上。」笄礼办得热闹又不误生意。","source":"商人家以营业为本，见《东京梦华录》记州桥夜市。"},{"text":"由着爹歇业","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"歇业半日，老主顾扑了空。娘说：「你爹一高兴，连账都不认了。」","source":"商户歇业须择日，见《东京梦华录》记店铺常例。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"及笄"},{"id":"A-001-未","branch":"A","stage":1,"day":1,"shichen":"未时","checkpoint":"笄礼","scene":"午后笄礼，娘为你加笄。珠花翠簪压上鬓边，你听见娘小声说：「我家丫头，是大姑娘了。」","options":[{"text":"谢爹娘养育","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"爹别过脸去抹眼睛，嘴里嘟囔：「头上那根簪子，是账上支的。」","source":"及笄之礼，见《仪礼》士昏礼之义。"},{"text":"只顾看镜中的自己","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"娘点你额头：「好看也得谢人哪。」","source":"笄礼谢亲，见《仪礼》。"}],"difficulty":1,"npc":["娘","爹"],"foreshadow":null},{"id":"A-001-戌","branch":"A","stage":1,"day":1,"shichen":"戌时","checkpoint":"第一笔账","scene":"夜里爹把一本蓝布账簿交给你：「及笄了，柜上的账，分你一半。先把这个月的流水誊一遍。」","options":[{"text":"连夜誊完","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"誊到三更，你发现一笔错账——爹看了直点头：「眼里有水，是块管账的料。」","source":"商家账簿日清月结，见《东京梦华录》记铺户经营。"},{"text":"说明日再誊","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"爹也不催，只说：「账是越拖越乱的。」","source":"账贵日清，见《梦粱录》记铺户。"}],"difficulty":1,"npc":["爹"],"foreshadow":"蓝布账簿"},{"id":"A-002","branch":"A","stage":1,"day":2,"shichen":"辰时","checkpoint":"媒婆上门","scene":"一早赵媒婆摇着团扇进门：「恭喜娘子及笄！东城的王家、西城的孙家，都托我来探口风。」","options":[{"text":"躲在屏风后听","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"娘在前头应付，你在屏后听得清清楚楚——原来议亲是这般光景。","source":"议亲媒妁往来，见《东京梦华录》记娶妇。"},{"text":"冲出去说不嫁","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"赵媒婆吓了一跳，娘赔笑半天才圆回来。","source":"闺秀不见外客，见《仪礼》。"}],"difficulty":1,"npc":["赵媒婆","娘"],"foreshadow":"议亲"},{"id":"A-002-未","branch":"A","stage":1,"day":2,"shichen":"未时","checkpoint":"娘的态度","scene":"午后娘与你盘算：「王家是读书人，孙家是开生药铺的。咱家是商户，娘说句掏心窝的——门当户对最省心。」","options":[{"text":"问两家的底细","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"娘把两家的家底、人口、铺面都数给你听，你心里有了谱。","source":"议亲先访家底，见《东京梦华录》记娶妇。"},{"text":"说我自己拿主意","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"娘叹气：「主意可以拿，底细得先摸清。贸贸然的主意，叫任性。」","source":"婚配由家长主，见《仪礼》。"}],"difficulty":2,"npc":["娘"],"foreshadow":"两家底细"},{"id":"A-002-戌","branch":"A","stage":1,"day":2,"shichen":"戌时","checkpoint":"夜市盘账","scene":"夜里你去州桥夜市收账。灯笼底下，你一家家对数：果子摊、香糖果子、间道糖荔枝……一文都不能错。","options":[{"text":"逐摊核清","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"回到家，爹翻着你记的数：「清清爽爽。这摊夜市，有你的眼睛了。」","source":"州桥夜市百货俱集，见《东京梦华录》卷二。"},{"text":"让伙计代核","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"伙计回来报数，少了两摊的数。爹皱眉：「账这东西，得自己长眼。」","source":"商户收银须亲核，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"夜市账"},{"id":"A-003","branch":"A","stage":1,"day":3,"shichen":"辰时","checkpoint":"识秤","scene":"一早爹教你识秤：「秤杆上十六两是一斤，一斤十六两，一两都不能亏人——亏人就是亏自己。」","options":[{"text":"记下斤两之数","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"爹把秤递给你：「称一称这包珠子。」你称得纹丝不差。","source":"宋制十六两为一斤，见《宋会要辑稿》权衡之制。"},{"text":"说伙计会秤就行","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"爹道：「你不会，伙计糊弄你你都不知道。」","source":"主家须通权衡，见《梦粱录》。"}],"difficulty":1,"npc":["爹"],"foreshadow":null},{"id":"A-003-未","branch":"A","stage":1,"day":3,"shichen":"未时","checkpoint":"认铜钱","scene":"午后娘教你认钱：「这是折二钱，这是小平钱，铁钱铜钱成色不一样。柜上收错一文，一天白忙。」","options":[{"text":"练了一下午辨钱","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"闭眼摸钱你都能说出成色，娘笑道：「这双手，天生是管柜的。」","source":"宋代钱制繁杂，折二小平并用，见《宋会要辑稿》钱币。"},{"text":"觉得麻烦","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘把钱匣一合：「嫌麻烦？钱比人老实，你糊弄它，它就糊弄你。」","source":"商户收钱辨伪为日课，见《东京梦华录》。"}],"difficulty":2,"npc":["娘"],"foreshadow":null},{"id":"A-003-戌","branch":"A","stage":1,"day":3,"shichen":"戌时","checkpoint":"丫鬟传话","scene":"夜里丫鬟杏儿一边铺床一边说：「赵媒婆跟灶上的嫂子说，孙家公子上回在夜市见过你算账，说你眼睛亮。」","options":[{"text":"笑斥她别传闲话","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"杏儿吐吐舌头。你心里却把「眼睛亮」三个字记下了。","source":"闺阁戒仆妇传舌，见《仪礼》治家之义。"},{"text":"追问孙家公子啥样","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"杏儿压低声音：「听说人不高，会做生意。」你怔了怔。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["丫鬟杏儿"],"foreshadow":"孙家公子","flavor":true},{"id":"A-004","branch":"A","stage":1,"day":4,"shichen":"辰时","checkpoint":"相国寺上香","scene":"初八，娘带你去相国寺上香。庙里香火鼎盛，娘在大殿许愿：「愿我闺女嫁个好人家。」","options":[{"text":"默默陪娘磕头","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你磕了三个头，心里想的是：好人家，也得我自己看得上。","source":"相国寺为都中首刹，见《东京梦华录》卷三。"},{"text":"说求佛不如求己","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"娘瞪你一眼：「在菩萨面前浑说！」","source":"敬佛之礼，见《梦粱录》记佛事。"}],"difficulty":1,"npc":["娘"],"foreshadow":null},{"id":"A-004-未","branch":"A","stage":1,"day":4,"shichen":"未时","checkpoint":"庙会看摊","scene":"相国寺庙会万姓交易。你在首饰摊前站住了——不是想买，是在心里算这摊一日的流水。","options":[{"text":"算出摊主日进几何","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"摊主看你算得飞快，笑道：「小娘子是行里人吧？」","source":"相国寺庙会万姓交易，见《东京梦华录》卷三。"},{"text":"买了一支珠花","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"珠花是好看，可你回头一算——买贵了三百文。","source":"庙会货价浮动大，见《东京梦华录》。"}],"difficulty":2,"npc":["摊主"],"foreshadow":"庙会算账"},{"id":"A-004-戌","branch":"A","stage":1,"day":4,"shichen":"戌时","checkpoint":"夜记市账","scene":"回家后你把白日庙会所见记了一页：什么货好卖，什么摊围的人多，什么价能成交。爹看了爱不释手。","options":[{"text":"爹说这是商经","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"爹把这页纸夹进蓝布账簿：「我闺女的眼睛，比账房先生还毒。」","source":"商户记市情为常课，见《东京梦华录》记诸行市。"},{"text":"只当随笔","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"爹拿去看了，回头添进他的生意经里——你这笔，立了功。","source":"市情记录，见《梦粱录》。"}],"difficulty":1,"npc":["爹"],"foreshadow":"市情随笔","flavor":true},{"id":"A-005","branch":"A","stage":1,"day":5,"shichen":"辰时","checkpoint":"女红课","scene":"晨妆毕，娘把针线笸箩推来：「账要会算，针线也不能荒。今日绣个并蒂莲。」","options":[{"text":"静下心绣完","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"并蒂莲绣得活灵活现，娘说：「这手艺，婆家看了也欢喜。」","source":"闺秀以女红为必修课，见《仪礼》妇功。"},{"text":"说绣活交给绣娘","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘道：「自己的嫁衣难道也叫人绣？」你不吭声了。","source":"嫁衣亲制，见《梦粱录》记嫁娶。"}],"difficulty":1,"npc":["娘"],"foreshadow":"并蒂莲"},{"id":"A-005-未","branch":"A","stage":1,"day":5,"shichen":"未时","checkpoint":"学待客","scene":"午后铺子里来了大宗买卖的客商，爹带你见：「看爹怎么谈价——先看人，再看货，最后才看钱。」","options":[{"text":"记下谈价次序","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"一笔生意谈成，爹说：「这笔利钱，记你头上——你看着学来的。」","source":"商旅议价之序，见《东京梦华录》记诸行交易。"},{"text":"只顾看货","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"客商走后爹说：「货人人会看，人不是人人会看。」","source":"相人之术，见《梦粱录》。"}],"difficulty":2,"npc":["爹","客商"],"foreshadow":"看人看货"},{"id":"A-005-戌","branch":"A","stage":1,"day":5,"shichen":"戌时","checkpoint":"灯下打珠算","scene":"夜里爹教你打算盘：「三下五除二，九归口诀。账房娘子，手上得有真功夫。」","options":[{"text":"练到指法生风","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"打到三更，九归口诀背得滚瓜烂熟，指尖都热了。","source":"珠算为商家必备，归除口诀见宋人算书。"},{"text":"打两下就手酸","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"爹不催：「慢慢来。算盘认人，你天天摸它，它就听你话。」","source":"习算贵恒，见《梦粱录》记铺户日课。"}],"difficulty":1,"npc":["爹"],"foreshadow":"珠算"},{"id":"A-006","branch":"A","stage":1,"day":6,"shichen":"辰时","checkpoint":"查库","scene":"一早爹带你去库房盘点：彩帛、线绦、珠子、脂粉。他说：「账上的数，要跟架子上的货对上才算数。」","options":[{"text":"逐架对数","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"对出一匹少了的素罗——前日伙计发货记错了。爹夸你：「好眼睛。」","source":"商户盘库账货相符，见《东京梦华录》记铺户经营。"},{"text":"抽查几架了事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"偏巧漏查的那架少了货。爹道：「盘点没有抽查，只有全查。」","source":"盘库之规，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"少罗案"},{"id":"A-006-未","branch":"A","stage":1,"day":6,"shichen":"未时","checkpoint":"伙计较劲","scene":"午后发货的伙计得知是你对出错账，臊眉耷眼来见你：「小娘子，那笔是我记岔了，求你别告诉掌柜罚我月钱。」","options":[{"text":"罚轻些让他补学","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你罚他抄写货目十遍。他感激不尽，往后发货再没错过。","source":"驭下恩威并施，见《仪礼》家治之义。"},{"text":"按例罚月钱","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"罚是按例，可伙计们自此见了你都绕着走。","source":"驭下过峻则离，见《宋刑统》家令之义。"}],"difficulty":2,"npc":["伙计"],"foreshadow":"立威"},{"id":"A-006-戌","branch":"A","stage":1,"day":6,"shichen":"戌时","checkpoint":"娘的话","scene":"夜里娘听说白日的事，道：「罚伙计那事，你做得对。记住，管账先管人，管人先暖心。」","options":[{"text":"记在心里","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"娘又说：「将来你嫁了人，铺子里这些事，就是你管家的本事。」","source":"商家之女以账理家，见《梦粱录》记铺户。"},{"text":"说我不想嫁","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"娘把灯挑亮了些：「傻话。女人家的本事，总得有处使。」","source":"婚嫁为女子正途，见《仪礼》婚义。"}],"difficulty":1,"npc":["娘"],"foreshadow":null},{"id":"A-007","branch":"A","stage":1,"day":7,"shichen":"辰时","checkpoint":"庚帖初来","scene":"一早赵媒婆送来孙家的庚帖。娘收下，回头同你说：「问名纳吉，六礼一步错不得。」","options":[{"text":"问庚帖上写什么","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"娘展开给你看：三代名讳、生辰八字，一项项指给你。","source":"问名庚帖之式，见《仪礼》士昏礼。"},{"text":"抢过来看","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘按住庚帖：「姑娘家自己拆庚帖，叫人笑话。」","source":"庚帖由家长收受，见《宋会要辑稿》婚礼仪注。"}],"difficulty":2,"npc":["娘","赵媒婆"],"foreshadow":"孙家庚帖"},{"id":"A-007-未","branch":"A","stage":1,"day":7,"shichen":"未时","checkpoint":"探孙家底","scene":"午后你向对街卖炊饼的嫂子打听孙家。嫂子嘴快：「生药铺孙家？家业殷实，就是——门第上，跟咱一样，商户。」","options":[{"text":"问孙家公子为人","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"嫂子道：「那后生倒本分，会看药材成色，不赌不飘。」你记下了。","source":"议亲访人家风，见《东京梦华录》记娶妇。"},{"text":"问聘财多少","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"嫂子笑：「娘子这话问早了——先问人，再问财。」","source":"议亲先德后财，见《宋会要辑稿》婚礼议德。"}],"difficulty":2,"npc":["炊饼嫂"],"foreshadow":"孙家底细"},{"id":"A-007-戌","branch":"A","stage":1,"day":7,"shichen":"戌时","checkpoint":"灯下想","scene":"夜里你翻着蓝布账簿想心事。商户配商户，娘说是省心。可你心里有一点点说不清的滋味。","options":[{"text":"把滋味写进账簿背面","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"写完自己看了笑——账簿背面记心事，满汴京怕只有你一个。","source":"闺中自记，见《琅嬛记》。"},{"text":"合上账簿睡觉","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"睡不着。帐子顶上的月光，亮得像柜上的银铤。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"账簿心事"},{"id":"A-008","branch":"A","stage":1,"day":8,"shichen":"辰时","checkpoint":"上巳备节","scene":"上巳将近，家里备兰汤、做禊饮。娘说商户家的姑娘也能上巳出游——只要你守规矩。","options":[{"text":"帮着备禊饮","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"兰汤煮得清香满院，娘满意：「明日带你出门见见世面。」","source":"上巳祓禊之俗，见《梦粱录》记三月。"},{"text":"问能不能去夜市","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘道：「白日祓禊是正事，夜市是咱家饭碗，啥时候不能看？」","source":"节庆之序，见《武林旧事》。"}],"difficulty":1,"npc":["娘"],"foreshadow":"上巳出游"},{"id":"A-008-未","branch":"A","stage":1,"day":8,"shichen":"未时","checkpoint":"学唱买卖","scene":"午后爹教你「唱卖」的调子：「卖货要有卖声，一声叫卖半条街都听见。」你学了两声，自己先笑了。","options":[{"text":"放开嗓子学","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"爹大笑：「有我当年的调门！不过娘子家不用真卖，懂得就行。」","source":"京师叫卖场曲，见《东京梦华录》记京瓦伎艺。"},{"text":"不好意思开口","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"爹道：「害羞？你收账时那股子利索劲儿呢？」","source":"商声之课，见《梦粱录》。"}],"difficulty":1,"npc":["爹"],"foreshadow":null},{"id":"A-008-戌","branch":"A","stage":1,"day":8,"shichen":"戌时","checkpoint":"夜算节账","scene":"夜里你算上巳这日全城的花销：兰草、禊饮、游船、点心……汴京人一天要花掉多少钱？","options":[{"text":"算出数目吓一跳","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你咋舌：「这一天，顶咱铺子仨月流水。」爹说：「所以叫东京梦华。」","source":"上巳游赏之费，见《武林旧事》记都人游湖。"},{"text":"算不清干脆不算","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"爹笑道：「算不清就对了——汴京的钱，是活水。」","source":"都中商贸之盛，见《东京梦华录》序。"}],"difficulty":2,"npc":["爹"],"foreshadow":null},{"id":"A-009","branch":"A","stage":1,"day":9,"shichen":"辰时","checkpoint":"士族提亲","scene":"一早出了桩新鲜事：城南有位致仕的官员，托官媒来为次子求亲。商户女配官家子，娘惊得直念佛。","options":[{"text":"请娘细问因由","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"官媒说是那公子在相国寺见过你算账，「极是爽利」。你想起庙会那日。","source":"官商通婚亦有之，见《东京梦华录》记娶妇不问阀阅。"},{"text":"欢喜得坐不住","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"娘按住你：「高门婚事，先沉住气，让人看笑话。」","source":"议亲贵从容，见《仪礼》。"}],"difficulty":2,"npc":["官媒","娘"],"foreshadow":"高门提亲"},{"id":"A-009-未","branch":"A","stage":1,"day":9,"shichen":"未时","checkpoint":"爹的盘算","scene":"午后爹把你叫去，眉头拧着：「官家是高枝，可高枝上的饭不好吃。他家的体面，未必容得下商户媳妇的算盘。」","options":[{"text":"说女儿明白","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"爹点头：「你不贪高枝，爹就放心了。咱商户人家的闺女，腰杆是账房里练出来的。」","source":"门第之见，见《宋会要辑稿》婚礼。"},{"text":"说嫁过去再说","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"爹叹道：「嫁过去就晚了。鞋合不合脚，要进门之前知道。」","source":"婚配宜审，见《仪礼》婚义。"}],"difficulty":3,"npc":["爹"],"foreshadow":"高门之虑"},{"id":"A-009-戌","branch":"A","stage":1,"day":9,"shichen":"戌时","checkpoint":"夜比两家","scene":"夜里你把孙家和官家在心里摆了摆：一个是门当户对的药材香，一个是高门深宅的规矩重。","options":[{"text":"两家的账都算算","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"算完了你自己笑了——嫁人终究不是做买卖，可人也不是货。","source":"闺中权衡，见《琅嬛记》。"},{"text":"想得头疼","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"头疼也得想。这一笔账，是你一辈子最大的一笔。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":2,"npc":null,"foreshadow":"两家之择"},{"id":"A-010","branch":"A","stage":1,"day":10,"shichen":"辰时","checkpoint":"及笄十日","scene":"晨起你翻账簿——及笄整整十日了。这十日，媒婆来了三回，你学了算账、识秤、辨钱、唱卖。","options":[{"text":"在账簿记一笔小结","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你写：「及笄十日，所学日多。」这页账，记的是你自己。","source":"闺中自记，见《琅嬛记》。"},{"text":"跟爹娘讨了件新衣","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"爹大手一挥：「支！」——记公账，他签名，你画押。","source":"商家支取之规，见《梦粱录》。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"里程碑·及笄十日","flavor":true},{"id":"A-010-未","branch":"A","stage":1,"day":10,"shichen":"未时","checkpoint":"晌午待客","scene":"晌午一位老主顾来扯绸缎给闺女做嫁衣。娘让你接待——这是你头一回独自当柜。","options":[{"text":"量体问期报价有条","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"客人满意：「小娘子当柜，比掌柜还细致。」娘在帘后直点头。","source":"商户女眷当柜售货，见《东京梦华录》记铺户。"},{"text":"慌得喊娘出来","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"娘出来了，客人笑道：「雏儿总要上架的，别怕。」","source":"当柜之学，见《梦粱录》。"}],"difficulty":2,"npc":["娘","老主顾"],"foreshadow":"头回当柜"},{"id":"A-010-戌","branch":"A","stage":1,"day":10,"shichen":"戌时","checkpoint":"灯下首日账","scene":"夜里你把白日那笔嫁衣料子账记上蓝布账簿，末了画押。爹看了道：「今日起，你柜上有名了。」","options":[{"text":"郑重画押","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你画的花押端端正正。这一笔，是你挣下的。","source":"商户账簿画押为凭，见《宋会要辑稿》商税之制。"},{"text":"请爹代画","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"爹把笔推回来：「你经手的账，画你的押。这是规矩。」","source":"账责自负，见《梦粱录》。"}],"difficulty":1,"npc":["爹"],"foreshadow":"柜上有名"},{"id":"A-011","branch":"A","stage":1,"day":11,"shichen":"辰时","checkpoint":"高门相看","scene":"官媒来回话：那家大人想「相看」。娘替你应了，回头嘱你：「高门相看，不看你多美，看你稳不稳。」","options":[{"text":"如常应对不怯","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"相看那日你行止有度。官媒回话：「是个有章程的姑娘。」","source":"相媳妇重仪态，见《东京梦华录》记娶妇。"},{"text":"特意盛装","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"官媒私下说：「妆太盛了，不像过日子的。」娘听了直咂嘴。","source":"相看宜端重，见《宋会要辑稿》婚礼仪注。"}],"difficulty":3,"npc":["官媒","娘"],"foreshadow":"高门相看"},{"id":"A-011-未","branch":"A","stage":1,"day":11,"shichen":"未时","checkpoint":"相看之后","scene":"相看过了一日，官媒再来，话却变了味：「他家老夫人说，姑娘是好姑娘，就是……商贾气重了些。」","options":[{"text":"沉住气听完","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你没恼。心里却亮堂了：原来在高门眼里，你的本事叫「商贾气」。","source":"门第之见，见《宋会要辑稿》婚礼。"},{"text":"当场冷了脸","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"官媒讪讪去了。娘道：「气归气，面子上不能输。」","source":"妇人贵有容，见《仪礼》。"}],"difficulty":3,"npc":["官媒"],"foreshadow":"商贾气"},{"id":"A-011-戌","branch":"A","stage":1,"day":11,"shichen":"戌时","checkpoint":"爹的气话","scene":"夜里爹把茶盏一顿：「商贾气？没有商贾，他官老爷吃什么穿什么！闺女，这门亲——爹不稀罕。」","options":[{"text":"说不稀罕才对","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你和爹击了个掌。娘在旁笑骂：「爷儿俩一个脾气。」","source":"商贾自尊，见《东京梦华录》记百业之盛。"},{"text":"劝爹别得罪人","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"爹道：「不得罪，也不攀附。咱家的闺女，不靠人脸色过活。」","source":"商人之节，见《梦粱录》。"}],"difficulty":2,"npc":["爹","娘"],"foreshadow":"拒高门","flavor":true},{"id":"A-012","branch":"A","stage":1,"day":12,"shichen":"辰时","checkpoint":"回绝官媒","scene":"一早娘回绝了官媒。官媒临走撂了句话：「商户人家，倒会拿乔。」","options":[{"text":"娘回得不软不硬","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"娘道：「不是拿乔，是攀不起。您多费心。」四两拨千斤。","source":"辞婚之辞，见《仪礼》辞受之礼。"},{"text":"你在旁帮腔","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"官媒脸色更难看了。娘回头道：「大人说话，姑娘家别插嘴。」","source":"闺秀不预外事，见《仪礼》。"}],"difficulty":2,"npc":["娘","官媒"],"foreshadow":"官媒记恨"},{"id":"A-012-未","branch":"A","stage":1,"day":12,"shichen":"未时","checkpoint":"市井口碑","scene":"午后你去夜市收账，几个摊主围过来：「听说你家回了官家的亲？」商户街上，这事儿半天就传遍了。","options":[{"text":"只说缘分未到","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"摊主们都夸你家有骨气。炊饼嫂道：「咱商户的女儿，不差这一口高枝饭。」","source":"市井重气节，见《东京梦华录》记民俗。"},{"text":"细说那家不是","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"话一出口就收不回了。明日这话传到那家耳朵里，又添三分颜色。","source":"言语招尤，见《宋会要辑稿》戒讼。"}],"difficulty":2,"npc":["摊主们"],"foreshadow":"市井口碑"},{"id":"A-012-戌","branch":"A","stage":1,"day":12,"shichen":"戌时","checkpoint":"娘的嫁妆话","scene":"夜里娘打开箱子给你看一对银铤：「这是你姥姥给我的。娘今日把话放这——你的嫁妆，一寸都不会短，谁也别想说咱高攀。」","options":[{"text":"抱住娘","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":2},"feedback":"娘拍着你的背：「咱商户人家的嫁妆，一文一文都是干净钱。」","source":"奁产为妇之底气，见《宋刑统》户婚律记妻财。"},{"text":"说嫁妆不重要","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"娘道：「说这话是因为你没缺过。嫁妆是女人在夫家的腰杆。」","source":"奁产之重，见《宋会要辑稿》记奁产。"}],"difficulty":1,"npc":["娘"],"foreshadow":"嫁妆话","flavor":true},{"id":"A-013","branch":"A","stage":1,"day":13,"shichen":"辰时","checkpoint":"孙家回话","scene":"一早赵媒婆喜气洋洋上门：孙家听说你回了官家的亲，越发敬重，庚帖之外又添了礼——一匣上好的沉檀。","options":[{"text":"依礼收下","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"沉檀的香气沉而不浮。娘说：「这家人，懂礼数。」","source":"议亲赠答，见《东京梦华录》记娶妇。"},{"text":"推辞不受","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"赵媒婆为难：「这头一份礼就推，往后怎么走往？」","source":"受礼之节，见《仪礼》。"}],"difficulty":1,"npc":["赵媒婆","娘"],"foreshadow":"沉檀之赠"},{"id":"A-013-未","branch":"A","stage":1,"day":13,"shichen":"未时","checkpoint":"识香","scene":"午后你开匣验香。你平日只识货价，今日头一回细闻：沉水深静，檀香清暖——原来香里有人品。","options":[{"text":"辨出沉檀之别","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你闭眼分出了两种香。爹笑：「鼻子也开蒙了，往后香药生意你也能管。」","source":"香药之辨，见《东京梦华录》记香药铺席。"},{"text":"只觉得好闻","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"好闻也是第一步。你把这匣子香供在了妆台上。","source":"香事之始，见《梦粱录》记烧香。"}],"difficulty":1,"npc":["爹"],"foreshadow":"识香"},{"id":"A-013-戌","branch":"A","stage":1,"day":13,"shichen":"戌时","checkpoint":"香里的心事","scene":"夜里沉檀的香气在屋里浮着。你想：送香的人，知不知道这两种香是什么味道？","options":[{"text":"猜他是懂的","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"懂香的人，心不会浮。这个念头让你睡了个好觉。","source":"以香观人，见《琅嬛记》。"},{"text":"笑自己想多了","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"笑归笑，那缕香，你是闻着它睡着的。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"闻香识人","flavor":true},{"id":"A-014","branch":"A","stage":1,"day":14,"shichen":"辰时","checkpoint":"学进货","scene":"一早爹带你去大相国寺后街的批发市场：「看货先看样，问价问三家，付钱付定钱。」","options":[{"text":"三家问完才定","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"同一匹罗，三家价差出二成。你定了中间那家——货最好，人也最实诚。","source":"商旅进货问三家，见《东京梦华录》记诸行市。"},{"text":"看中就定了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"回头一问，买贵了一成半。爹道：「这一成半，是学费。」","source":"买贵之训，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"进货三家"},{"id":"A-014-未","branch":"A","stage":1,"day":14,"shichen":"未时","checkpoint":"香药铺前","scene":"进货回来路过孙家的生药铺。铺前有个年轻人在验货，侧脸专注，手指翻着药材——你多看了一眼。","options":[{"text":"目不斜视走过","correct":true,"tags":["名声"],"dims":{"名声":1,"情缘":1},"feedback":"走过了才听见他在说：「这批沉水香，成色是上等。」声音很好听。","source":"市井男女各不相扰，见《仪礼》男女之别。"},{"text":"放慢了脚步","correct":false,"tags":["情缘","名声"],"dims":{"情缘":1,"名声":1},"feedback":"杏儿拽你袖子：「娘子！」你回神，耳根热了。","source":"闺秀出行之仪，见《仪礼》。"}],"difficulty":2,"npc":["杏儿","孙家公子"],"foreshadow":"药铺初见"},{"id":"A-014-戌","branch":"A","stage":1,"day":14,"shichen":"戌时","checkpoint":"灯下验货","scene":"夜里你帮爹验今日进的货。验到一半走了神——白日那个验药材的年轻人，手法跟你爹一样熟稔。","options":[{"text":"回神继续验","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"爹看你验得又快又准，满意点头。你走神的事，谁也没瞧出来。","source":"验货之课，见《东京梦华录》。"},{"text":"跟娘提了半句","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"娘睨你一眼：「孙家的公子？」你慌忙说不是，脸先红了。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":null},{"id":"A-015","branch":"A","stage":1,"day":15,"shichen":"辰时","checkpoint":"半月盘点","scene":"及笄半月。爹让你独立盘点一回全店的账目：进、销、存、欠，四条线。","options":[{"text":"四条线全对清","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"爹翻着你的盘点册，半天说了句：「比账房刘先生还细。」","source":"商户盘点四线，见《东京梦华录》记铺户经营。"},{"text":"错了一处被爹点出","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"错在一笔赊账的日期。爹道：「赊账看日子，日子错了钱就没了。」","source":"赊账之戒，见《梦粱录》。"}],"difficulty":3,"npc":["爹"],"foreshadow":"独立盘点"},{"id":"A-015-未","branch":"A","stage":1,"day":15,"shichen":"未时","checkpoint":"赊账风波","scene":"午后一位绸缎商来赊货，说的数目不小。爹不在，柜上你做主。","options":[{"text":"查他旧账再定","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"旧账还清过两次，信誉好。你赊给他了——爹回来夸你有章法。","source":"赊货先查信用，见《东京梦华录》记商业惯例。"},{"text":"不敢做主回绝","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"那商人不快：「小娘子做不了主，叫掌柜的来。」一笔生意眼看要黄。","source":"当柜贵有担待，见《梦粱录》。"}],"difficulty":3,"npc":["绸缎商"],"foreshadow":"赊账"},{"id":"A-015-戌","branch":"A","stage":1,"day":15,"shichen":"戌时","checkpoint":"夜话信用","scene":"夜里爹同你说：「今日你赊得对。记住，做生意做的不是货，是信用。信用在，生意就在。」","options":[{"text":"记入账簿扉页","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"「信用」二字写在蓝布账簿头一页。这本账簿，越来越像你的命。","source":"商家以信用为本，见《东京梦华录》序。"},{"text":"点头记下了","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"记下是记下了，可写下来，才是一辈子的东西。","source":"家学之传，见《琅嬛记》。"}],"difficulty":1,"npc":["爹"],"foreshadow":"信用","flavor":true},{"id":"A-016","branch":"A","stage":1,"day":16,"shichen":"辰时","checkpoint":"夜市初忙","scene":"一早爹说今晚州桥夜市有大集，柜上备货要加倍。你帮着点货，从辰时忙到日头偏西。","options":[{"text":"点货配货不停手","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"货备得足，爹说：「今晚的流水，看你的了。」","source":"州桥夜市至三更尽，见《东京梦华录》卷二。"},{"text":"偷空歇了两回","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"歇是歇了，可备货少了两样，晚上缺货少卖了钱。","source":"夜市备货贵足，见《梦粱录》。"}],"difficulty":1,"npc":["爹"],"foreshadow":"夜市大集"},{"id":"A-016-未","branch":"A","stage":1,"day":16,"shichen":"未时","checkpoint":"夜市当柜","scene":"夜市开张，灯如白昼。你在摊后收钱找钱，人潮一波接一波，铜钱串子在你指间哗哗响。","options":[{"text":"钱货两清无一错","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"一晚下来分文不差。爹收摊时说：「我闺女这双手，是聚宝盆。」","source":"夜市交易之盛，见《东京梦华录》卷二。"},{"text":"找错了一回钱","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"客人不依不饶，爹替你赔了不是。回家爹只说了一句：「心浮了。」","source":"收付之慎，见《梦粱录》。"}],"difficulty":2,"npc":["爹","客人"],"foreshadow":null},{"id":"A-016-戌","branch":"A","stage":1,"day":16,"shichen":"戌时","checkpoint":"收摊送药","scene":"收摊时，对街孙家生药铺的伙计送来一包润喉的胖大海：「我们公子说，夜市喊卖费嗓子，送娘子一包。」","options":[{"text":"收下让伙计带谢","correct":true,"tags":["情缘","名声"],"dims":{"情缘":1,"名声":1},"feedback":"一包胖大海，不值钱，可这份心细，值。你让伙计带了一包你家的果回谢。","source":"邻里馈遗之礼，见《东京梦华录》记市人情。"},{"text":"坚辞不受","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"伙计抱着胖大海回去了。爹听闻道：「邻里的好意，推来推去就生分了。」","source":"馈遗宜受宜报，见《仪礼》。"}],"difficulty":1,"npc":["孙家伙计"],"foreshadow":"胖大海"},{"id":"A-017","branch":"A","stage":1,"day":17,"shichen":"辰时","checkpoint":"学定价","scene":"一早爹教你定价：「进价一成五的利，是行规；熟客让半分，生客不欺。价定死了，心就定了。」","options":[{"text":"记下定价规矩","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你按规矩给新货定了价签，爹看了一圈，一个没改。","source":"行规定价，见《东京梦华录》记行会。"},{"text":"问能不能看人下菜","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"爹脸一沉：「看人下菜碟，是做死买卖。这话以后不许说。」","source":"商德不欺，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"定价规矩"},{"id":"A-017-未","branch":"A","stage":1,"day":17,"shichen":"未时","checkpoint":"生客讲价","scene":"午后一位外地客人讲价讲得厉害，说要一半价。柜上就你一人。","options":[{"text":"让半分守行规","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"客人见你利落，反倒不讲了：「小娘子是明白人。」按行规成交。","source":"议价之度，见《东京梦华录》记交易。"},{"text":"被磨得松了口","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"价是松了，客人出门就跟人说这家好磨——明日来的全是要磨价的。","source":"破价之患，见《梦粱录》。"}],"difficulty":3,"npc":["外地客人"],"foreshadow":"行规"},{"id":"A-017-戌","branch":"A","stage":1,"day":17,"shichen":"戌时","checkpoint":"夜泡胖大海","scene":"夜里你泡了孙家送的胖大海。水慢慢涨开，像一朵褐色的花。你想起他那句「成色是上等」。","options":[{"text":"把这份心记下了","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"水是好水，心是好心。你喝完，把壳收在了妆匣角落。","source":"闺中情思，见《琅嬛记》。"},{"text":"只当寻常邻里","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"寻常邻里不送这个。你心里明白，只是不说。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"胖大海","flavor":true},{"id":"A-018","branch":"A","stage":1,"day":18,"shichen":"辰时","checkpoint":"两家通问","scene":"一早孙家正式遣赵媒婆来通问：两家世为街邻，如今结两姓之好。爹娘都点了头。","options":[{"text":"依礼静听","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"娘回头看你一眼，你垂下眼——这门亲，八成了。","source":"通问为纳采之先，见《仪礼》士昏礼疏。"},{"text":"心跳得厉害","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"心跳得再厉害，面上也不显。这是商户娘子当柜练出来的本事。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["赵媒婆","爹","娘"],"foreshadow":"孙家通问"},{"id":"A-018-未","branch":"A","stage":1,"day":18,"shichen":"未时","checkpoint":"合庚帖","scene":"午后两家庚帖送去合。傍晚回话：「天作之合，大吉。」娘把庚帖供在神龛上，烧了三炷香。","options":[{"text":"随娘上香","correct":true,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"香烟缭绕里你想：大吉不大吉，终究要人过日子过出来。","source":"纳吉卜吉之礼，见《仪礼》士昏礼。"},{"text":"心里默念自己拿主意","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"主意你早就拿了一半——那一包胖大海，你还没还呢。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":["娘"],"foreshadow":"婚事初定"},{"id":"A-018-戌","branch":"A","stage":1,"day":18,"shichen":"戌时","checkpoint":"夜市官宣","scene":"夜里夜市收摊，炊饼嫂带头起哄：「小娘子要嫁孙家啦！」半条街的摊主都来道喜。","options":[{"text":"大方受喜","correct":true,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":1},"feedback":"你红着脸一一谢过。这条街的人情，比账簿厚。","source":"市井人情，见《东京梦华录》记民俗。"},{"text":"躲回铺里","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"摊主们笑：「新嫁娘脸皮薄！」——躲得了今日，躲不了出阁那天。","source":"闺秀之羞，见《琅嬛记》。"}],"difficulty":1,"npc":["摊主们"],"foreshadow":null},{"id":"A-019","branch":"A","stage":1,"day":19,"shichen":"辰时","checkpoint":"婆母首礼","scene":"一早孙家遣人送来礼物：两匹上好的吴绫，指名给未来娘子。娘回赠了亲手做的鞋袜。","options":[{"text":"帮娘打点回礼","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"回礼配得妥妥帖帖。娘道：「一来一往，亲家的路就走熟了。」","source":"两家馈答，见《东京梦华录》记娶妇。"},{"text":"只摸了摸吴绫","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"绫是好绫。娘敲你手背：「先看回礼备齐没有！」","source":"礼尚往来，见《仪礼》。"}],"difficulty":1,"npc":["娘"],"foreshadow":"两家走动"},{"id":"A-019-未","branch":"A","stage":1,"day":19,"shichen":"未时","checkpoint":"学做鞋","scene":"午后娘教你做鞋：「嫁过去头一样活计，是给公婆做鞋。针脚就是你的脸面。」","options":[{"text":"一针一线跟着学","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"鞋底纳得密密实实，娘说：「这双手打算盘快，纳鞋底也稳。」","source":"新妇制履为礼，见《梦粱录》记嫁娶。"},{"text":"扎了三回手","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"指头扎出血珠，娘给你裹上：「慢些来，针认手，手认心。」","source":"女红之课，见《仪礼》妇功。"}],"difficulty":1,"npc":["娘"],"foreshadow":"制履"},{"id":"A-019-戌","branch":"A","stage":1,"day":19,"shichen":"戌时","checkpoint":"夜市的对视","scene":"夜里夜市收摊，你抱着钱匣往回走，正撞上孙家公子也来收摊。灯影里，你俩隔着半条街，都站住了。","options":[{"text":"颔首一礼先走","correct":true,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":2},"feedback":"他也回了一礼。走出去老远，你觉出那道目光还在灯影里。","source":"男女之防，见《仪礼》。"},{"text":"低头快步走开","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"走得太急，钱匣里的铜钱响了一路——像在替你心跳。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":2,"npc":["孙家公子"],"foreshadow":"灯影对视"},{"id":"A-020","branch":"A","stage":1,"day":20,"shichen":"辰时","checkpoint":"流言又起","scene":"一早有闲话传来：那家被回绝的官家在外说，「商户女配商户子，臭棋配臭篓」。","options":[{"text":"只当耳旁风","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"爹听了拍桌大笑：「臭棋？咱这盘棋活得好好地，他管得着吗！」","source":"清议不侵自足之家，见《宋会要辑稿》。"},{"text":"气得回嘴","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"回嘴的话传回去，又变了三变。娘道：「最好的回嘴，是日子过得比他好。」","source":"口舌之戒，见《仪礼》。"}],"difficulty":2,"npc":["爹","娘"],"foreshadow":"高门记恨"},{"id":"A-020-未","branch":"A","stage":1,"day":20,"shichen":"未时","checkpoint":"娘教奁账","scene":"午后娘教你立奁单：「田产铺面我们商户人家没有官家的多，但咱有活水——这间铺子的一半，给你做嫁妆。」","options":[{"text":"问铺股怎么算","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"娘细讲：股本、分红、账期。你明白了——你的奁产是会下蛋的。","source":"商户以铺股为奁，见《梦粱录》记嫁娶奁具。"},{"text":"说给银子就行","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘摇头：「银子会花完，铺子会生钱。娘给你的，是一辈子的活水。」","source":"奁产生息，见《宋刑统》户婚律。"}],"difficulty":2,"npc":["娘"],"foreshadow":"铺股为奁"},{"id":"A-020-戌","branch":"A","stage":1,"day":20,"shichen":"戌时","checkpoint":"灯下奁单","scene":"夜里你把自己的奁单列了一页：铺股若干、银铤、首饰、四季衣裳。写完你忽然不怕嫁了。","options":[{"text":"把单子收进妆匣","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"单子压进妆匣底。纸是轻的，底气是重的。","source":"奁单随身，见《东京梦华录》记嫁娶。"},{"text":"给爹娘看了看","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"爹娘看了对视一笑：「这孩子，心里开始有谱了。」","source":"奁单之议，见《梦粱录》。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"奁单","flavor":true},{"id":"A-021","branch":"A","stage":1,"day":21,"shichen":"辰时","checkpoint":"纳采","scene":"吉日，孙家遣使纳采。一对活雁用红绸系着，外加药材四色——商户的纳采，连礼都透着本行。","options":[{"text":"依礼回避","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"使者回去说：「李家娘子的规矩，一丝不差。」","source":"纳采用雁，见《仪礼》士昏礼。"},{"text":"隔帘看雁","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"雁扑棱一声，你笑了。帘外的使者也听见了笑声——听说孙家公子也笑了。","source":"纳采之俗，见《东京梦华录》记娶妇。"}],"difficulty":1,"npc":["孙家使者","娘"],"foreshadow":"纳采成"},{"id":"A-021-未","branch":"A","stage":1,"day":21,"shichen":"未时","checkpoint":"学药材","scene":"午后爹说：「往后两家并一家，药材的成色你也得懂。」他摊开孙家礼单，教你认沉檀龙麝。","options":[{"text":"认真记下药性","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"半日认了二十味药材。爹说：「这门手艺，够你在婆家立住脚。」","source":"药材辨识，见《东京梦华录》记香药铺席。"},{"text":"嫌药味苦","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"爹道：「药材苦，日子甜。往后你就懂了。」","source":"妇学之事，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"识药材"},{"id":"A-021-戌","branch":"A","stage":1,"day":21,"shichen":"戌时","checkpoint":"名分初定","scene":"夜里你睡不着，想：过了今日，你就是孙家未过门的媳妇了。这个名分像新衣，有点硬，有点亮。","options":[{"text":"把心情记进账簿","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"你在账簿背面写：「今日纳采。」四个字，一笔一画都郑重。","source":"闺中自记，见《琅嬛记》。"},{"text":"数他送的东西","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"胖大海、沉檀、吴绫……数完了，夜也深了。","source":"闺中情思，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"A-022","branch":"A","stage":1,"day":22,"shichen":"辰时","checkpoint":"行会道喜","scene":"一早行会头目周伯带着几个行老来道喜，还提了行规：「成了亲家，两家的行会份子照旧，谁也不占谁。」","options":[{"text":"听爹和周伯论规矩","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"行规清清楚楚，亲家明明白白——商户的婚事，连喜都带着章法。","source":"行会规矩，见《东京梦华录》记行老。"},{"text":"觉得没意思","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘道：「没意思？这世道，规矩就是体面。」","source":"行规之重，见《宋会要辑稿》。"}],"difficulty":1,"npc":["周伯","爹"],"foreshadow":"行会"},{"id":"A-022-未","branch":"A","stage":1,"day":22,"shichen":"未时","checkpoint":"合伙之议","scene":"午后爹和你商量：「等你过了门，咱家和孙家联一笔药材胭脂的生意——女人家的嫁妆，也能做生意。」","options":[{"text":"兴致勃勃问细节","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"爹笑道：「嫁衣还没上身，生意经先通了。」","source":"商户联姻联营，见《东京梦华录》记诸行。"},{"text":"说先嫁人再说","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"爹也不急：「也好。先把人嫁明白，再把账算明白。」","source":"缓急之序，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"联营之议"},{"id":"A-022-戌","branch":"A","stage":1,"day":22,"shichen":"戌时","checkpoint":"灯下算联营","scene":"夜里你睡不着，索性拨算盘：药材胭脂联营，本钱、利钱、账期……算着算着，算盘声里都是盼头。","options":[{"text":"算出一页章程","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"一页联营章程写成了。爹明日看了，眼睛瞪得像铜钱。","source":"商户筹算，见《东京梦华录》记铺户经营。"},{"text":"算一半就困了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"困是困了，可那本蓝布账簿里，又多了半页你的主意。","source":"闺中筹算，见《琅嬛记》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"联营章程"},{"id":"A-023","branch":"A","stage":1,"day":23,"shichen":"辰时","checkpoint":"端午将近","scene":"端午将近，全城裹粽子、系百索。爹说：「今年你裹的粽子，要送孙家一份——头一回，不能失礼。」","options":[{"text":"裹了四角端正的","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你裹的角黍个个端正。娘挑了最好的十只，装进描金盒。","source":"端午裹粽馈亲，见《东京梦华录》记端午。"},{"text":"裹得歪歪扭扭","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘叹气：「手是打算盘的手，不是裹粽的手。多练。」","source":"妇功之课，见《仪礼》。"}],"difficulty":1,"npc":["娘"],"foreshadow":"端午"},{"id":"A-023-未","branch":"A","stage":1,"day":23,"shichen":"未时","checkpoint":"孙家回粽","scene":"午后孙家回赠角黍，附了一小包艾草香囊，说是「公子亲手配的，驱蚊安神」。","options":[{"text":"佩在衣襟上","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"香囊贴着心口，艾草的清气一阵阵的。你知道这香是谁配的。","source":"端午佩香囊，见《梦粱录》记端午。"},{"text":"收进妆匣","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"收是收了，可那缕艾香从妆匣里往外钻，拦不住。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["娘"],"foreshadow":"艾草香囊"},{"id":"A-023-戌","branch":"A","stage":1,"day":23,"shichen":"戌时","checkpoint":"灯下拆香囊","scene":"夜里你把香囊凑到灯前细看：艾绒里还掺了一味安息香——他连你夜里打算盘费神都想到了。","options":[{"text":"把这份细记在心里","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你心里那本账，「他」这一页，又添了一笔。","source":"闺中情思，见《琅嬛记》。"},{"text":"心想这是礼数","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"是礼数，可礼数里掺了心意。你分得清。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":null},{"id":"A-024","branch":"A","stage":1,"day":24,"shichen":"辰时","checkpoint":"看嫁衣料","scene":"一早娘开库选嫁衣料。商户家的嫁衣不讲绫罗讲实惠，娘说：「料子要好，更要喜庆。」","options":[{"text":"挑了石榴红杭绸","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"娘拍板：「石榴红，多子多福，配你！」","source":"嫁衣色尚红，见《周氏墓》出土嫁衣。"},{"text":"想要月白的","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"娘把月白料子抽走：「嫁衣要红！月白是平常的。」","source":"吉服用色之制，见《宋会要辑稿》服制。"}],"difficulty":1,"npc":["娘"],"foreshadow":"嫁衣料"},{"id":"A-024-未","branch":"A","stage":1,"day":24,"shichen":"未时","checkpoint":"打首饰","scene":"午后银楼师傅上门。娘的嫁妆里有一对银铤，化了打成你的头面：龙凤钗、梳背、花钿。","options":[{"text":"选了龙凤呈祥","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"师傅赞：「好眼光，这花样百年不过时。」","source":"婚嫁首饰之制，见《东京梦华录》记嫁娶。"},{"text":"选了时下最俏的","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"师傅委婉道：「俏是俏，三年就过时。嫁妆头面，要传家的。」","source":"首饰贵传家，见《梦粱录》。"}],"difficulty":1,"npc":["银楼师傅","娘"],"foreshadow":"头面"},{"id":"A-024-戌","branch":"A","stage":1,"day":24,"shichen":"戌时","checkpoint":"爹娘夜话","scene":"夜里你听见爹娘在算嫁妆账。爹说：「铺股、银铤、头面、四季衣裳……再压箱一千贯。」娘说：「值。」","options":[{"text":"在门外听红了眼","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"你没进去。这一千贯，是爹娘半辈子的灯油钱。","source":"父母之爱，见《仪礼》亲亲之义。"},{"text":"推门说太多了","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"爹摆手：「闺女的嫁妆，没有嫌多的。回去睡你的。」","source":"厚嫁之俗，见《宋会要辑稿》记奁产。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"嫁妆","flavor":true},{"id":"A-025","branch":"A","stage":1,"day":25,"shichen":"辰时","checkpoint":"回望一月","scene":"晨起你翻蓝布账簿——及笄一月，从学算账到名分初定。这一个月，比过去一年都长。","options":[{"text":"在账簿记一页总结","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你写：「及笄一月，名定孙家。」写完笑了——账簿快成你的日记了。","source":"闺中自记，见《琅嬛记》。"},{"text":"对镜笑了笑","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"镜子里的人眼睛亮亮的。孙家公子没看错——是真的亮。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"阶段一毕","flavor":true},{"id":"A-025-未","branch":"A","stage":1,"day":25,"shichen":"未时","checkpoint":"请期将至","scene":"午后赵媒婆来传话：孙家要请期了，婚期想在金秋。娘说：「金秋好，螃蟹肥，桂花香。」","options":[{"text":"在心里数日子","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"还有多少日？你掰着指头数了两遍，都没数清——心乱了。","source":"请期择吉，见《仪礼》士昏礼。"},{"text":"嘴上说还早","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"杏儿在旁笑：「娘子昨夜翻历书翻到几更，当我不知道？」","source":"闺中谐谑，见《琅嬛记》。"}],"difficulty":1,"npc":["赵媒婆","娘"],"foreshadow":"婚期金秋"},{"id":"A-025-戌","branch":"A","stage":1,"day":25,"shichen":"戌时","checkpoint":"爹的赠言","scene":"夜里爹把你叫到柜上，说了两句话：「嫁出去，不算本事。把日子过成一本好账，才是。」","options":[{"text":"郑重记下","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":2},"feedback":"爹又说：「孙家那孩子，爹相看过了——账算得清，人靠得住。值。」","source":"父为女择配，见《仪礼》婚义。"},{"text":"问爹怎么看出来的","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"爹笑：「验药材的手，稳。手稳的人，心不乱。」","source":"观人之法，见《梦粱录》。"}],"difficulty":1,"npc":["爹"],"foreshadow":"阶段一毕","flavor":true},{"id":"A-026","branch":"A","stage":2,"day":26,"shichen":"辰时","checkpoint":"相看之约","scene":"一早赵媒婆来传话：孙家太婆要「相看相看」。娘一口应下，回头道：「商户家的相看，就在柜上相——看你的真本事。」","options":[{"text":"问相看相什么","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"娘道：「相你怎么当柜、怎么待人。别装，装出来的过不了一年。」","source":"相媳妇之俗，见《东京梦华录》记娶妇。"},{"text":"紧张得手心冒汗","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"娘笑：「你收账时对半条街都不怵，一个太婆怕什么？」","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":["赵媒婆","娘"],"foreshadow":"太婆相看"},{"id":"A-026-未","branch":"A","stage":2,"day":26,"shichen":"未时","checkpoint":"柜上备相","scene":"午后你把柜上理了一遍：货要齐，账要清，价签要正。杏儿问：「娘子这是要迎驾？」","options":[{"text":"答迎的是饭碗","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"杏儿不懂，你爹懂。他远远看了一眼，没说话，笑了。","source":"商户以柜面为门面，见《东京梦华录》记铺户。"},{"text":"答迎太婆","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"话没错，可你心里清楚——你理的不是门面，是自己的底气。","source":"妇立以能，见《梦粱录》。"}],"difficulty":1,"npc":["杏儿","爹"],"foreshadow":null},{"id":"A-026-戌","branch":"A","stage":2,"day":26,"shichen":"戌时","checkpoint":"夜备衣饰","scene":"夜里娘替你择明日衣裳：「不红不绿，干干净净。太婆看媳妇，看的是利索。」","options":[{"text":"选了青布襦裙","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"娘点头：「好。咱商户家的姑娘，利利索索就是体面。」","source":"相看服饰宜素洁，见《周氏墓》服饰色样。"},{"text":"想穿那件石榴红","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"娘把红的收起来：「那是嫁衣的色。相看穿红，浮。」","source":"服饰以色分场合，见《宋会要辑稿》服制。"}],"difficulty":1,"npc":["娘"],"foreshadow":null},{"id":"A-027","branch":"A","stage":2,"day":27,"shichen":"辰时","checkpoint":"太婆相看","scene":"一早孙太婆到了，不进内宅，就在柜前坐下：「老身买条绦子。」你明白——相看开始了。","options":[{"text":"如常当柜接待","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"拿绦子、报成色、算账、找钱，一气呵成。太婆的眼睛亮了。","source":"相看考较持家之能，见《东京梦华录》记娶妇。"},{"text":"紧张得算错账","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"错三文钱，你自己查出来补上了。太婆看在眼里，没说话。","source":"当柜之慎，见《梦粱录》。"}],"difficulty":3,"npc":["孙太婆"],"foreshadow":"太婆相看"},{"id":"A-027-未","branch":"A","stage":2,"day":27,"shichen":"未时","checkpoint":"太婆考账","scene":"太婆不走，又要看缎子，末了忽然问：「小娘子，这铺子一月流水几何？利在几成？」","options":[{"text":"答得有数有节","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"你报了流水和利成，又补一句：「行规，不敢尽言。」太婆大笑：「好！是个当家的！」","source":"商家守密之度，见《东京梦华录》记行规。"},{"text":"和盘托出","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"太婆笑着走了。爹听说后皱眉：「家底哪能全抖给外人？」","source":"商密之戒，见《梦粱录》。"}],"difficulty":3,"npc":["孙太婆"],"foreshadow":"太婆满意"},{"id":"A-027-戌","branch":"A","stage":2,"day":27,"shichen":"戌时","checkpoint":"相看回话","scene":"夜里赵媒婆连夜来报：太婆回去说了六个字——「这媳妇，是块料！」相看，过了。","options":[{"text":"与爹娘报喜","correct":true,"tags":["情缘","家世"],"dims":{"情缘":1,"家世":1},"feedback":"爹把柜上的算盘擦了三遍。娘念叨了一宿「老天保佑」。","source":"相看过后婚成，见《东京梦华录》记娶妇。"},{"text":"回房偷着乐","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"乐是真乐。你在账簿背面写：「今日，我是块料。」","source":"闺中自记，见《琅嬛记》。"}],"difficulty":1,"npc":["赵媒婆","爹","娘"],"foreshadow":"亲事铁定","flavor":true},{"id":"A-028","branch":"A","stage":2,"day":28,"shichen":"辰时","checkpoint":"学认亲族","scene":"一早娘摊开孙家亲族图：太婆、公婆、两房叔伯、三个妯娌。商户人家亲族不比官家少，先认人。","options":[{"text":"按图记人记事","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你把各房营生也记了：二房开染坊，三房跑漕运——往后都是生意。","source":"新妇先识夫家亲族，见《仪礼》之义。"},{"text":"说见面就认得","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘考你三房婶子的名讳，你卡住了——嘴硬没用。","source":"识亲为妇职，见《仪礼》。"}],"difficulty":2,"npc":["娘"],"foreshadow":"亲族图"},{"id":"A-028-未","branch":"A","stage":2,"day":28,"shichen":"未时","checkpoint":"妯娌消息","scene":"午后炊饼嫂来串门，说孙家二嫂是出了名的厉害嘴：「她管着孙家内宅的采买，你过门，是要从她手里分权。」","options":[{"text":"问怎么处","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"嫂子道：「敬她三分，让她三分，账上清楚十分。」你记下了。","source":"妯娌相处之道，见《仪礼》妇顺之训。"},{"text":"说井水不犯河水","correct":false,"tags":["自主"],"dims":{"自主":2},"feedback":"嫂子摇头：「一宅两院，锅勺哪有不碰的？」","source":"同居之义，见《仪礼》。"}],"difficulty":2,"npc":["炊饼嫂"],"foreshadow":"二嫂"},{"id":"A-028-戌","branch":"A","stage":2,"day":28,"shichen":"戌时","checkpoint":"灯下预演","scene":"夜里你对着账簿想：过门后，晨省、管家、处妯娌、帮衬生意……你把它们一条条列成章程。","options":[{"text":"列出一页章程","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"章程列完，心里踏实了。商户娘子的嫁妆，一半是这本账。","source":"闺中自记，见《琅嬛记》。"},{"text":"想过就完了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"想是想了，没落笔的章程，过门就忘。","source":"立言之益，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"过门章程"},{"id":"A-029","branch":"A","stage":2,"day":29,"shichen":"辰时","checkpoint":"他送药材","scene":"一早孙家公子亲自来送药材——两家既通好，生意也走动了。这是他头一回到你家柜上。","options":[{"text":"大方验货报价","correct":true,"tags":["名声","情缘"],"dims":{"名声":1,"情缘":1},"feedback":"你验货、过秤、报价，一丝不乱。他拱拱手：「小娘子好手段。」","source":"商户往来交易，见《东京梦华录》记诸行。"},{"text":"躲进后堂","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"爹只得自己出来。事后道：「定了亲还躲，小家子气。」","source":"通家之好，见《仪礼》。"}],"difficulty":2,"npc":["孙家公子","爹"],"foreshadow":"柜上初见"},{"id":"A-029-未","branch":"A","stage":2,"day":29,"shichen":"未时","checkpoint":"验药论香","scene":"验货时你们说起香药。他说沉水香要「闻其尾韵」，你说卖货要「看其成色」——话说到一处去了。","options":[{"text":"与他论了半刻香","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":2},"feedback":"爹在旁看着没言语。回头同娘说：「这俩孩子，说的是一门生意。」","source":"香药之论，见《东京梦华录》记香药铺席。"},{"text":"只谈价钱","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"价是谈完了，可你俩都觉得，有话没说完。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":2,"npc":["孙家公子"],"foreshadow":"论香"},{"id":"A-029-戌","branch":"A","stage":2,"day":29,"shichen":"戌时","checkpoint":"灯下余味","scene":"夜里你回想白日论香——「尾韵」两个字，你说不出那是什么，可你记住了他说这两个字时的样子。","options":[{"text":"记下来","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你在账簿背面写：「闻其尾韵。」四字下面，画了一小道香。","source":"闺中自记，见《琅嬛记》。"},{"text":"笑自己痴","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"痴就痴吧。商户人家的痴，也是实实在在的。","source":"闺中情态，见《琅嬛记》。"}],"difficulty":1,"npc":null,"foreshadow":"尾韵","flavor":true},{"id":"A-030","branch":"A","stage":2,"day":30,"shichen":"辰时","checkpoint":"满月盘点","scene":"及笄满月。晨起你把这月的账理出总册：进销存欠、人情往来、两家生意——商户娘子的满月，是拿账说话的。","options":[{"text":"总册清清楚楚","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"爹翻完总册，郑重放进柜中：「从今日起，柜上的总账归你。」","source":"商户月结之规，见《东京梦华录》记铺户。"},{"text":"几处对不上","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你自查半日，对上了。爹道：「账不怕错，怕不认。」","source":"账责之教，见《梦粱录》。"}],"difficulty":2,"npc":["爹"],"foreshadow":"总账归你"},{"id":"A-030-未","branch":"A","stage":2,"day":30,"shichen":"未时","checkpoint":"满月盘点·二","scene":"未时，孙家公子来铺，不验药，只立在柜前看你打算盘。半晌道：「你打的是『狮子滚绣球』，我娘也会。」","options":[{"text":"请孙夫人来铺坐坐","correct":true,"tags":["情缘","家世","感情"],"dims":{"情缘":2,"家世":1},"feedback":"他眼睛一亮：「她念叨半年了，就想看看把账打活的姑娘。」","source":"宋代商铺往来，以家眷相访为亲近之礼。"},{"text":"回他算盘谁都会","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他也不恼，笑道：「那改日我把我娘的账本背来，比一比。」","source":"商户儿女言谈，见宋代话本。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"孙夫人相访"},{"id":"A-030-戌","branch":"A","stage":2,"day":30,"shichen":"戌时","checkpoint":"满月盘点·三","scene":"夜市收摊，你在蓝布账簿背面写日记：「满月。总账归我。他站在柜前看我打算盘，看了半个时辰。」","options":[{"text":"画了个小算盘","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"画完自己先笑了——商户家的心思，连心事都带铜板声。","source":"宋代女子笺记之习，见宋代闺阁墨迹。"},{"text":"撕了这页重写","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"撕了又写，写的还是他。罢了，认账。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"心事入册","flavor":true},{"id":"A-031","branch":"A","stage":2,"day":31,"shichen":"辰时","checkpoint":"联营初议","scene":"五月初一。爹铺里说：「孙家生药铺想与咱家联营——药香囊配彩帛，端午应节。你去谈的，你拿个章程。」","options":[{"text":"香囊五五分账","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"你列明：帛出我家，药出他家，工钱对出，利五五分。爹道：「公道，才做得长。」","source":"宋代合伙经商分利之例，见《东京梦华录》。"},{"text":"我家多出要六成","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"爹摇头：「联营头一遭就掐尖，往后谁与你合伙？」","source":"经商戒贪，见宋代商书。"}],"difficulty":2,"npc":["爹"],"foreshadow":"联营章程"},{"id":"A-031-未","branch":"A","stage":2,"day":31,"shichen":"未时","checkpoint":"联营初议·二","scene":"未时，你携章程过对街。孙公子验完药材出来迎，看你写的分账条款，看到一半抬头：「字比我好。」","options":[{"text":"条款也比我好？","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"他正色：「条款是公道，字是好看。两码事，我分得很清。」","source":"商户议事之风，见宋代话本。"},{"text":"谦虚说胡乱写的","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"他道：「胡乱写能写成这样，认真写还了得？」你倒接不住了。","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"两相敬重"},{"id":"A-031-戌","branch":"A","stage":2,"day":31,"shichen":"戌时","checkpoint":"联营初议·三","scene":"戌时，两家在州桥夜市合议。孙家出药料方子，你家出彩帛花样，头一批定五百个香囊。","options":[{"text":"当场立契画押","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"夜市灯下立契，两市口围观称好。孙老爷道：「这亲家，错不了。」——说漏了嘴。","source":"宋代契券之制，见《名公书判清明集》。"},{"text":"先小试一百个","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你说稳当。孙老爷笑道：「稳当是好的，端午可不等人。」","source":"商贾应节备货之规。"}],"difficulty":2,"npc":["孙老爷","爹"],"foreshadow":"夜市立契"},{"id":"A-032","branch":"A","stage":2,"day":32,"shichen":"辰时","checkpoint":"香囊开制","scene":"五月初二。香囊开制：帛要裁、药要配、绳要绦。你排工：裁帛三人、配药两人、绦绳两人、总管一人——你。","options":[{"text":"按工派活定日课","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"日课一贴，各人名下清清楚楚。娘道：「你这排工的章法，比你爹强。」","source":"宋代作坊分工，见《东京梦华录》记行铺。"},{"text":"自己上手裁帛","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你裁了一上午，工都看着总管裁帛，没人敢催。娘把你拎回柜前。","source":"主事者当务其大，宋代商谚。"}],"difficulty":2,"npc":["娘"],"foreshadow":"排工日课"},{"id":"A-032-未","branch":"A","stage":2,"day":32,"shichen":"未时","checkpoint":"香囊开制·二","scene":"未时，配药起争执：孙家师傅要加龙脑，价贵；你家师傅要用普通冰片。两边都看你。","options":[{"text":"分两档各做一半","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"你道：「龙脑的做上等，卖三百文；冰片的做常品，卖八十文。」两边都服了。","source":"宋代货品分等定价之例，见《东京梦华录》。"},{"text":"统一用龙脑","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"价高销不动怎么办？你加了一句「卖不掉的我家兜底」，才平了。","source":"同上。"}],"difficulty":3,"npc":["两家师傅"],"foreshadow":"两档定价"},{"id":"A-032-戌","branch":"A","stage":2,"day":32,"shichen":"戌时","checkpoint":"香囊开制·三","scene":"收工点货，头一日成囊八十只。孙公子来送新配的香药末，顺走一只绦错颜色的：「这只歪的，归我。」","options":[{"text":"歪的也记账上","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":2,"才华":1},"feedback":"你提笔：「初二，孙某人取歪囊一只，记『心意账』，不必还。」他看了三遍。","source":"商户儿女雅谑，见宋代话本。"},{"text":"追回来换好的","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他抱紧香囊：「送出去的账，泼出去的水。」跑了。","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"心意账"},{"id":"A-033","branch":"A","stage":2,"day":33,"shichen":"辰时","checkpoint":"端午将至","scene":"五月初三。离端午还有两日，夜市各铺都开始挂艾。你巡摊，见自家香囊摊子位置被挤到角落里。","options":[{"text":"找市吏按契排位","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"你持夜市契券寻市吏，按早立的契排回原位。有理有据，无人不服。","source":"宋代市井摊位之制，见《东京梦华录》。"},{"text":"角落也能卖","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你加了盏灯、挂了串样品，角落也亮堂起来——只是费了三倍力气。","source":"同上。"}],"difficulty":2,"npc":["市吏"],"foreshadow":"按契排位"},{"id":"A-033-未","branch":"A","stage":2,"day":33,"shichen":"未时","checkpoint":"端午将至·二","scene":"未时，那被你回绝的官家遣管家来，开口要订三百只上等香囊，端午送人——价钱出得高，却要赊账。","options":[{"text":"赊账不接现银来","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你道：「小本生意，概不赊欠。官人若现银，今夜赶工也给您做出来。」管家悻悻去了。","source":"宋代官家赊账之患，见《梦粱录》。"},{"text":"高价单先接下","correct":false,"tags":["才华","家世"],"dims":{"家世":1},"feedback":"爹沉脸：「官家的赊账，是要用人情还的。这单沾不得。」连夜退了。","source":"同上。"}],"difficulty":3,"npc":["官家管家","爹"],"foreshadow":"官家纠缠"},{"id":"A-033-戌","branch":"A","stage":2,"day":33,"shichen":"戌时","checkpoint":"端午将至·三","scene":"戌时，孙公子听说官家来订囊的事，匆匆赶来：「他没难为你吧？」","options":[{"text":"难不倒账房娘子","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"他松了口气，又板起脸：「往后这种事，先递个话给我。」你道：「凭什么？」他说不出话。","source":"宋代青年男女关护之态，见话本。"},{"text":"不必你操心","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他噎了半天：「……那我操我自己的心，行不行？」","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"官家后患"},{"id":"A-034","branch":"A","stage":2,"day":34,"shichen":"辰时","checkpoint":"端午前夜","scene":"五月初四。五百只香囊齐活，码在柜上像座小山。你抽检十只：药味正、针脚密、绦绳牢。","options":[{"text":"贴号封箱待市","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你贴上号签封箱：「明日五更开摊，谁先谁后，照号来。」万事俱备。","source":"宋代节货备市之规，见《东京梦华录》。"},{"text":"留两只上等的","correct":false,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你留了两只龙脑的：一只给娘，一只……账上写的是「备用」。杏儿看破不说破。","source":"端午赠香之俗。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"备用香囊"},{"id":"A-034-未","branch":"A","stage":2,"day":34,"shichen":"未时","checkpoint":"端午前夜·二","scene":"未时，孙夫人终于登门。她不看帛不看药，先要你的账本看。翻了三页，指着「心意账」那行笑出了声。","options":[{"text":"坦然请她指教","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":2,"情缘":1},"feedback":"你道：「糊涂账才要藏着，明白账不怕看。」孙夫人合册点头：「这媳妇，是块料。」","source":"宋代议亲相看之俗，见《梦粱录》。"},{"text":"忙把那页撕了","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"孙夫人笑道：「撕了也看见了。字好，心更好。」你耳根通红。","source":"同上。"}],"difficulty":3,"npc":["孙夫人"],"foreshadow":"婆母首肯"},{"id":"A-034-戌","branch":"A","stage":2,"day":34,"shichen":"戌时","checkpoint":"端午前夜·三","scene":"前夜家宴。娘蒸了粽子，爹破例烫了酒，说：「明日端午，是你头一回自己唱主角。」","options":[{"text":"敬爹娘一盏","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"你道：「主角不敢当，账房娘子给二老交租来了。」一家人笑作一团。","source":"宋代节夜家宴之俗。"},{"text":"心里默念别砸","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"念完自己乐了：账都验过三遍了，砸不了。睡个好觉。","source":"同上。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"端午开摊","flavor":true},{"id":"A-035","branch":"A","stage":2,"day":35,"shichen":"辰时","checkpoint":"端午大卖","scene":"端午日五更开摊。州桥夜市的日市也人山人海，你家香囊摊前排起队来——药香应节，帛色打眼。","options":[{"text":"照号发售不乱","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"上等的先售罄，常品也不愁。半日，五百只去其七。","source":"宋代端午市卖之盛，见《东京梦华录》。"},{"text":"看人下菜加价","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你忍了忍没加——节市抬价，砸的是自家招牌。","source":"商贾戒市利，宋代商谚。"}],"difficulty":2,"npc":[],"foreshadow":"香囊售罄"},{"id":"A-035-未","branch":"A","stage":2,"day":35,"shichen":"未时","checkpoint":"端午大卖·二","scene":"未时，那只「备用」的龙脑香囊还揣在你袖里。孙公子在对面摊帮忙，忙里偷闲朝你这边望。","options":[{"text":"趁乱塞给他","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他接了，闻了闻，郑重系在腰间：「这只不歪。」你道：「这只最贵。」他道：「知道。」","source":"端午赠囊定情之俗，见宋代节令记载。"},{"text":"等收摊再说","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"等到收摊，人多嘴杂，到底没送出去。香囊在袖里焐了一天。","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"香囊定情"},{"id":"A-035-戌","branch":"A","stage":2,"day":35,"shichen":"戌时","checkpoint":"端午大卖·三","scene":"收摊盘账：五百只香囊售空，两家分利，各入账四十贯。这是你经手的头一笔联营大账。","options":[{"text":"记下这四十贯","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"蓝布账簿上，你写下：「端午，联营首捷。」这一笔，是你自己挣的世道。","source":"宋代联营分利之记。"},{"text":"留一半作本金","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"你与爹议定：利钱留半作下批本金。爹道：「会滚钱了，好。」","source":"经商积本之道，见宋代商书。"}],"difficulty":1,"npc":["爹"],"foreshadow":"联营首捷","flavor":true},{"id":"A-036","branch":"A","stage":2,"day":36,"shichen":"辰时","checkpoint":"联营扩大","scene":"端午次日，两家合议乘胜扩营：孙老爷出主意做七夕针囊、中秋香帕。你算了算本钱，还够再开一摊。","options":[{"text":"七夕针囊先备","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你道：「端午到七夕整两个月，针囊要做工细，现在开工正好。」两家称善。","source":"宋代应节备货周期，见《东京梦华录》。"},{"text":"连开三摊齐上","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"爹拦了：「贪多嚼不烂。七夕做精了，中秋自然有人找上门。」","source":"经商戒躁，宋代商谚。"}],"difficulty":2,"npc":["爹","孙老爷"],"foreshadow":"七夕针囊"},{"id":"A-036-未","branch":"A","stage":2,"day":36,"shichen":"未时","checkpoint":"联营扩大·二","scene":"未时，孙夫人带着二儿媳——孙家二嫂来铺里。二嫂过门三年，说话拿腔拿调：「弟妹这账房，是现学的不成？」","options":[{"text":"账目请二嫂过目","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"你把总册推过去。二嫂翻了三页没挑出错，讪讪道：「……比我陪嫁的账房强。」","source":"宋代妯娌相处之道，见家训类书。"},{"text":"软语岔开话头","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你岔开了，孙夫人却看在眼里，过后对娘道：「你家闺女，肚里有货，面上有德。」","source":"同上。"}],"difficulty":3,"npc":["孙夫人","二嫂"],"foreshadow":"二嫂掂量"},{"id":"A-036-戌","branch":"A","stage":2,"day":36,"shichen":"戌时","checkpoint":"联营扩大·三","scene":"戌时，杏儿嚼舌根：「姑娘，那孙家二嫂今日来，是替婆家掂量你呢。」","options":[{"text":"掂量就掂量","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你翻着账簿：「我的账摊在明处，她的秤在暗处——明的不怕暗的。」","source":"宋代女子自处之语，见话本。"},{"text":"有点发愁","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"愁了半盏茶，你把愁记进了日记，记完就不愁了——商户家，账目清了心就清。","source":"同上。"}],"difficulty":2,"npc":["杏儿"],"foreshadow":"妯娌暗流"},{"id":"A-037","branch":"A","stage":2,"day":37,"shichen":"辰时","checkpoint":"针囊开工","scene":"五月初七。七夕针囊开工。针囊不比香囊，要绣「穿针乞巧」的花样，绣娘是头一回请进铺。","options":[{"text":"工钱按件计","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你定按件计酬、优等加价。绣娘们劲头十足，三日出的活比别家七日还多。","source":"宋代雇工计酬之例，见《东京梦华录》。"},{"text":"工钱按日计","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"按日计，出活慢。你改成「日底加件奖」，才算顺了。","source":"同上。"}],"difficulty":2,"npc":["绣娘们"],"foreshadow":"绣娘计酬"},{"id":"A-037-未","branch":"A","stage":2,"day":37,"shichen":"未时","checkpoint":"针囊开工·二","scene":"未时，孙公子送来七夕应节的「同心缕」图样，是他照古书描的。最后一页夹着张纸条：「乞巧那日，州桥见？」","options":[{"text":"纸条夹进账簿","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你把它夹进蓝布账簿「心意账」那页——这页快记满了。","source":"七夕乞巧之俗，见《东京梦华录》。"},{"text":"回他「看生意」","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他收到回条，在对面铺子笑得像个傻子。杏儿道：「姑娘坏。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"七夕之约"},{"id":"A-037-戌","branch":"A","stage":2,"day":37,"shichen":"戌时","checkpoint":"针囊开工·三","scene":"戌时核工，针囊花样定了三色：鸳鸯、连理、并蒂。杏儿挤眼：「姑娘，这花样是谁选的呀？」","options":[{"text":"七夕就兴这个","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你理直气壮：「七夕不绣鸳鸯绣什么？绣算盘吗？」杏儿笑倒。","source":"七夕花样之俗。"},{"text":"脸红了没答","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"红就红吧。账房娘子选什么花样，自有她的道理。","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"花样心事","flavor":true},{"id":"A-038","branch":"A","stage":2,"day":38,"shichen":"辰时","checkpoint":"流言四起","scene":"五月初八。街上传闲话：那被你回绝的官家放话，说商户女「水性」，说你家香囊「来路不明」。","options":[{"text":"亮契亮账自清","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你把联营契、药料进账贴在铺前：「来路不明？白纸黑字，诸位自看。」流言不攻自破。","source":"宋代商贾自证之例，见《名公书判清明集》。"},{"text":"忍忍就过去了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘道：「忍是金银铺的路，也是刀扎的根。」你还是亮了账。","source":"宋代商谚。"}],"difficulty":3,"npc":[],"foreshadow":"官家进逼"},{"id":"A-038-未","branch":"A","stage":2,"day":38,"shichen":"未时","checkpoint":"流言四起·二","scene":"未时，孙老爷亲自过街，当街朗声道：「香囊的药，是我孙家配验的！谁说半句闲话，先问我！」","options":[{"text":"谢过孙老爷","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"孙老爷摆手：「自家人，谢什么。」——这「自家人」三个字，半条街都听见了。","source":"宋代商户互保之风，见《东京梦华录》。"},{"text":"请他铺里吃茶","correct":false,"tags":["家世","情缘"],"dims":{"家世":1,"情缘":1},"feedback":"茶吃了半盏，孙老爷叹：「那官家，怕是还没死心。丫头，往后多个心眼。」","source":"同上。"}],"difficulty":2,"npc":["孙老爷"],"foreshadow":"孙家回护"},{"id":"A-038-戌","branch":"A","stage":2,"day":38,"shichen":"戌时","checkpoint":"流言四起·三","scene":"戌时，孙公子在账簿里塞了张新纸条，不约见面了，写的是：「别怕。我在。」","options":[{"text":"回他「不怕」","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"你在下面添了两个字：「不怕。」想了想，又添一个：「你在。」——抄了，认了。","source":"宋代儿女书笺之雅，见闺阁墨迹。"},{"text":"压在账本底下","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"压在账底，就是收进心里。账房娘子的情话，都过账。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"字条往复","flavor":true},{"id":"A-039","branch":"A","stage":2,"day":39,"shichen":"辰时","checkpoint":"针囊上样","scene":"五月初九。头一批针囊绣样出来了：鸳鸯那只针脚最密，是绣娘里的王嫂做的。你验样，针针扎实。","options":[{"text":"优等加价立档","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你立了「绣档」：针脚分三等，价随档走。王嫂成了头一个「上档绣娘」。","source":"宋代绣品等第之制，见《梦粱录》。"},{"text":"通通一个价","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"绣娘们面上不说，手下就松了。你补了等差，才算救回来。","source":"同上。"}],"difficulty":2,"npc":["王嫂","绣娘们"],"foreshadow":"绣档三等"},{"id":"A-039-未","branch":"A","stage":2,"day":39,"shichen":"未时","checkpoint":"针囊上样·二","scene":"未时，樊楼的歌伎遣人来订二十只鸳鸯针囊，说是七夕赠客。这是笔大主顾，也惹眼。","options":[{"text":"照市价接单","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你照市价、照号、照契接了。生意就是生意，来路正的银子，不烫手。","source":"宋代樊楼定制之风，见《东京梦华录》。"},{"text":"怕惹眼推了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"推了。娘道：「可惜。」你道：「眼下官家盯着，宁可少挣。」娘点头：「也对。」","source":"同上。"}],"difficulty":2,"npc":["樊楼来人"],"foreshadow":"樊楼主顾"},{"id":"A-039-戌","branch":"A","stage":2,"day":39,"shichen":"戌时","checkpoint":"针囊上样·三","scene":"戌时盘账，你忽然发现：自从联营后，自家铺子的流水翻了一倍。爹盯着账本看了很久。","options":[{"text":"爹，这是开头","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"爹道：「我守了三十年的铺子，你三十天做翻了番。」他把柜上钥匙，又交出一把。","source":"宋代家业传承之记，见家训类书。"},{"text":"不敢居功","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"你道：「是两家人的功劳。」爹道：「话是你说的，章程是你立的。」钥匙照给。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"柜钥交托","flavor":true},{"id":"A-040","branch":"A","stage":2,"day":40,"shichen":"辰时","checkpoint":"纳征之议","scene":"五月初十。孙夫人托官媒婆上门，正式提「纳征」——下聘。媒婆展开礼单：聘财、彩帛、香药，样样齐全。","options":[{"text":"请爹娘主礼","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"礼数周全，娘悄悄拭泪。爹道：「孙家的礼单里，头一样写的是『敬重』。」","source":"宋代纳征之礼，见《东京梦华录》记婚俗。"},{"text":"躲到里屋去了","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"躲在里屋，耳朵贴在门缝上，一句没落下。账房娘子，哪能不听账。","source":"同上。"}],"difficulty":2,"npc":["官媒婆","娘"],"foreshadow":"纳征下聘"},{"id":"A-040-未","branch":"A","stage":2,"day":40,"shichen":"未时","checkpoint":"纳征之议·二","scene":"未时，聘礼过门。孙公子随礼而来，在院里站着不敢进屋。你隔窗看见他腰上——系着那只不歪的龙脑香囊。","options":[{"text":"隔窗点了点头","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他看见了，立正，朝窗郑重一揖。满院子的人都笑了，他也不躲。","source":"宋代下聘日之俗。"},{"text":"放下了帘子","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"帘子放下了，心没收回来。杏儿道：「姑娘，帘子挡不住眼神。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"聘礼过门"},{"id":"A-040-戌","branch":"A","stage":2,"day":40,"shichen":"戌时","checkpoint":"纳征之议·三","scene":"戌时，娘把聘礼单递给你收着：「往后，你就是半个孙家人了。可娘要你说句实话——你愿意么？」","options":[{"text":"愿意，账都算过","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你道：「人才、家底、心肠，女儿都验过了——比验药还细。愿意。」娘笑着哭了。","source":"宋代婚配重情愿之记，见话本。"},{"text":"低头红了脸","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"低头也是答。娘道：「知道了，知道了。」声音也哽了。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"亲事言定","flavor":true},{"id":"A-041","branch":"A","stage":2,"day":41,"shichen":"辰时","checkpoint":"请期","scene":"五月十一。两家请期——议婚期。官媒婆合了八字，报出三个吉日：七月廿二、八月十六、九月初九。","options":[{"text":"定八月十六","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"你道：「中秋后一日，团圆定团圆，又赶上秋日市旺，铺里周转得开。」两家称善，就此定金秋。","source":"宋代请期之礼，见《东京梦华录》记婚俗。"},{"text":"越早越好七月","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"娘掐你：「日子是越过越长的，急什么！」你揉着胳膊改口八月。","source":"同上。"}],"difficulty":2,"npc":["官媒婆","娘"],"foreshadow":"婚期定八月十六"},{"id":"A-041-未","branch":"A","stage":2,"day":41,"shichen":"未时","checkpoint":"请期·二","scene":"未时，婚期传开。孙公子过街来，远远站定，拱手：「八月十六。」你回：「八月十六。」说完两人都笑了。","options":[{"text":"记进心意账","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"蓝布账簿上你写：「五月十一，请期定。距八月十六，九十七日。」这账，越记越甜。","source":"宋代婚期之记。"},{"text":"掰指头算日子","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"九十七天。你头一回觉得，日子这东西，也可以慢慢过。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"婚期九十七日","flavor":true},{"id":"A-041-戌","branch":"A","stage":2,"day":41,"shichen":"戌时","checkpoint":"请期·三","scene":"戌时，官家闻听你婚期已定，遣管家送来「贺礼」——一锭官银，一句话：「官人说了，城西铺面，随时可谈。」","options":[{"text":"原封退回","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你原箱退回，附一句话：「婚期已定，礼不敢受。」爹道：「退得干净，睡得安稳。」","source":"宋代拒馈之节，见家训类书。"},{"text":"留下应付场面","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘把箱子推回去：「他的银子是钩子，收了就得咬饵。」你第二日一早退了。","source":"同上。"}],"difficulty":3,"npc":["官家管家","爹"],"foreshadow":"官家不死心"},{"id":"A-042","branch":"A","stage":2,"day":42,"shichen":"辰时","checkpoint":"针囊赶工","scene":"五月十二。离七夕还有五十五日，针囊要备足三千只。你重新排工，把绣档三等铺开，上档绣娘已添到七人。","options":[{"text":"三班倒赶工","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你排三班轮作，灯油、茶食、工钱都列了细账。绣娘们说：「跟姑娘干活，累也明白。」","source":"宋代作坊轮作之例，见《东京梦华录》。"},{"text":"再加低价绣娘","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"低价的多、次品也多。你把次品率记上账，改了主意——贵的手工，便宜的学费。","source":"同上。"}],"difficulty":2,"npc":["绣娘们"],"foreshadow":"针囊三千"},{"id":"A-042-未","branch":"A","stage":2,"day":42,"shichen":"未时","checkpoint":"针囊赶工·二","scene":"未时，二嫂又来了，这回带了礼：「弟妹，我那陪嫁的账房，笨是笨了点……能不能搁你这儿学学？」","options":[{"text":"收下教她看账","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"你应下，立了「学徒簿」。二嫂讪讪道谢——往后妯娌间，这人情记下了。","source":"宋代妯娌相携之记，见家训类书。"},{"text":"婉拒说顾不上","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"拒了。孙夫人知道后只说了一句：「一家子，账算得太清就生分了。」你记下了。","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"妯娌破冰"},{"id":"A-042-戌","branch":"A","stage":2,"day":42,"shichen":"戌时","checkpoint":"针囊赶工·三","scene":"戌时收工，杏儿来报：孙公子在对面铺子门口挂了盏新灯笼，灯笼上写着——「八月十六」。","options":[{"text":"隔着街看了很久","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一盏灯笼，四个字，半条街都看见了他的心思。你也看见了自己的——不躲了。","source":"宋代街市灯彩之俗，见《东京梦华录》。"},{"text":"笑他显摆","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"笑完，你让杏儿把自家灯笼也挂高了些。街市上的事，就要亮亮堂堂。","source":"同上。"}],"difficulty":1,"npc":["杏儿","孙公子"],"foreshadow":"灯笼明心","flavor":true},{"id":"A-043","branch":"A","stage":2,"day":43,"shichen":"辰时","checkpoint":"官家发难","scene":"五月十三。市吏忽然来查你家摊子，说「有人告你等挤占官道」。带你去对质的，正是官家管家。","options":[{"text":"持契对质不退","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你持契据理：摊位有契、有界、有年档。市吏验明无误，反训了那管家一顿。","source":"宋代市讼凭契之制，见《名公书判清明集》。"},{"text":"塞钱了事","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"钱塞了，事没完——今日挤占官道，明日又是新罪名。你后撤一步，改日持契说理，才了结。","source":"同上。"}],"difficulty":3,"npc":["市吏","官家管家"],"foreshadow":"契券护身"},{"id":"A-043-未","branch":"A","stage":2,"day":43,"shichen":"未时","checkpoint":"官家发难·二","scene":"未时，孙家父子齐至。孙老爷道：「那官家冲的不是你的摊，是你的婚事。他折不了你的情，就折你的财。」","options":[{"text":"财折不动我的","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你道：「我的财在账上、在手里、在人心里——他折不着。」孙老爷拊掌：「好儿媳！」","source":"宋代商户风骨之记，见话本。"},{"text":"未免有些后怕","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孙公子道：「怕就躲我身后。」你道：「我站惯了柜台，不会躲。」他怔了怔，笑了。","source":"同上。"}],"difficulty":2,"npc":["孙老爷","孙公子"],"foreshadow":"两家同心"},{"id":"A-043-戌","branch":"A","stage":2,"day":43,"shichen":"戌时","checkpoint":"官家发难·三","scene":"戌时，你在日记里写：「今日险些吃了官司。靠一张纸契顶回来了。原来商户人家的腰杆，是契约和账目撑起来的。」","options":[{"text":"又添一行","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你添道：「往后教他看看，商户女配商户子，天经地义，用不着谁抬举。」","source":"宋代商人自尊之语，见宋代笔记。"},{"text":"吹灯睡了","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"睡得很沉。明日针囊照赶，日子照过——这就是回击。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"商户腰杆","flavor":true},{"id":"A-044","branch":"A","stage":2,"day":44,"shichen":"辰时","checkpoint":"乞巧前","scene":"五月十四。离七夕近了，街面上已有小儿女买「磨喝乐」。王嫂领头，把鸳鸯针囊的绣样又精进了三分。","options":[{"text":"给绣娘加节赏","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"节赏一发，绣档士气大涨。娘道：「散财聚人，这手像你外祖。」","source":"宋代节赏之俗，见《东京梦华录》。"},{"text":"节后再一起算","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"节后算也成，只是这几日绣娘们嘴上不说，针脚慢了半分——你补了赏钱。","source":"同上。"}],"difficulty":2,"npc":["王嫂","娘"],"foreshadow":"节赏聚人"},{"id":"A-044-未","branch":"A","stage":2,"day":44,"shichen":"未时","checkpoint":"乞巧前·二","scene":"未时，孙公子送来七夕摊位的图：两家摊子并成一处，中间搭个小小的「乞巧棚」，针囊悬棚而卖。","options":[{"text":"好主意照图搭","correct":true,"tags":["才华","情缘","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你补了一笔：棚下设「穿针处」，买囊的姑娘可当场乞巧。他道：「还是你会做生意。」","source":"宋代七夕乞巧棚之俗，见《东京梦华录》。"},{"text":"问他棚子谁出钱","correct":false,"tags":["情缘","才华"],"dims":{"情缘":1},"feedback":"他道：「我出棚，你出心。」这账……你破例没记。","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"乞巧棚"},{"id":"A-044-戌","branch":"A","stage":2,"day":44,"shichen":"戌时","checkpoint":"乞巧前·三","scene":"戌时，娘翻着黄历忽然道：「七夕那晚，你与他去州桥走走吧。订了亲的人，不算逾礼。」","options":[{"text":"娘也开明","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":1,"情缘":1},"feedback":"娘道：「娘也是商户人家出来的——好日子是自己挣的，好姻缘是自己看的。」","source":"宋代七夕游观之俗，见《梦粱录》。"},{"text":"害羞应了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"应了。杏儿在旁边掰指头：「还有三日！」","source":"同上。"}],"difficulty":1,"npc":["娘","杏儿"],"foreshadow":"七夕夜游","flavor":true},{"id":"A-045","branch":"A","stage":2,"day":45,"shichen":"辰时","checkpoint":"铺股之议","scene":"五月十五。爹召集全家：「闺女要出阁了。我与你娘商议——彩帛铺两成干股，作你的奁产。往后铺里分红，归你私房。」","options":[{"text":"谢爹娘立契","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"你郑重立契收股。商户人家的嫁妆，不只是箱笼——是生息的根。","source":"宋代奁产之制，见《名公书判清明集》记女子奁产。"},{"text":"推辞说不用","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"爹正色：「拿着。嫁出去的女儿手里有产业，在婆家才立得直。」你收下了。","source":"同上。"}],"difficulty":2,"npc":["爹","娘"],"foreshadow":"两成干股"},{"id":"A-045-未","branch":"A","stage":2,"day":45,"shichen":"未时","checkpoint":"铺股之议·二","scene":"未时，你拿着铺股契，头一回以「东家」身份巡自家铺子。伙计们的眼神都不一样了。","options":[{"text":"规矩照旧加赏","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你道：「规矩一条不改，节赏一分不少。」伙计们齐声应诺——新东家，立住了。","source":"宋代商铺接掌之记，见宋代笔记。"},{"text":"当场面询账目","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"查了半日账，查出两处小疏漏。你道：「改了就完，不追旧账。」众人服了。","source":"同上。"}],"difficulty":2,"npc":["伙计们"],"foreshadow":"新东家立威"},{"id":"A-045-戌","branch":"A","stage":2,"day":45,"shichen":"戌时","checkpoint":"铺股之议·三","scene":"戌时，你在账簿上另立一册，封面写三个字：「我的账」。铺股、奁产、私房——头一页，干干净净。","options":[{"text":"写第一笔","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你写：「五月十五，立户。往后盈亏，都是我自己的名字。」","source":"宋代女子私财之记，见《名公书判清明集》。"},{"text":"摩挲良久","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"商户家的女儿，有了自己的户头。这一册，比什么首饰都压手。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"自立户头","flavor":true},{"id":"A-046","branch":"A","stage":2,"day":46,"shichen":"辰时","checkpoint":"七夕前备货","scene":"五月十六。针囊已出一千八，乞巧棚的竹木料子也订下了。你盘库时发现：绦绳的染色染料不够了。","options":[{"text":"自家染坊调新色","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你想起爹的彩帛染缸，调出「牵牛紫」「织女星」两色新绦——七夕独一份。","source":"宋代染彩之技，见《东京梦华录》记染铺。"},{"text":"街市上买现成","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"现成色寻常，针囊成色平平。你连夜改了自染，才追回成色。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"自染新色"},{"id":"A-046-未","branch":"A","stage":2,"day":46,"shichen":"未时","checkpoint":"七夕前备货·二","scene":"未时，二嫂带着她那笨账房来学艺。你教了半日「四柱清册」，那账房总算会了旧管、新收。","options":[{"text":"教完送他字帖","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"你道：「账先学清，字再学正。」二嫂在旁听着，头一回真心道谢。","source":"宋代四柱清册之法，见宋代会计记载。"},{"text":"让他多练三日","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"练了三日，勉强出师。二嫂道：「弟妹教人有耐心，往后我家账也放心交你指点。」","source":"同上。"}],"difficulty":2,"npc":["二嫂","笨账房"],"foreshadow":"妯娌渐亲"},{"id":"A-046-戌","branch":"A","stage":2,"day":46,"shichen":"戌时","checkpoint":"七夕前备货·三","scene":"戌时，孙公子来核七夕的账。核到「心意账」那页，两人都装没看见。核完，他忽然问：「这页……七夕后还记吗？」","options":[{"text":"记一辈子","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"话一出口两人都静了。半晌他道：「那我这边的账，也记一辈子。」","source":"宋代儿女盟誓之记，见话本。"},{"text":"翻页说对账","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"翻了页，谁也没真对账。账房娘子的账，早就不在纸上了。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"心意长账","flavor":true},{"id":"A-047","branch":"A","stage":2,"day":47,"shichen":"辰时","checkpoint":"乞巧棚搭起","scene":"五月十七。乞巧棚在州桥夜市口搭起来了：竹骨帛棚，悬五色针囊，棚下设穿针处。半条街都来围观。","options":[{"text":"试棚穿针演练","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你带杏儿演练开棚流程：迎客、穿针、赠彩、收银——一气呵成。","source":"宋代七夕乞巧棚之俗，见《东京梦华录》。"},{"text":"先看别家动静","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"看了一圈，别家还没动静。孙公子道：「这棚，汴京独一份。」","source":"同上。"}],"difficulty":2,"npc":["杏儿","孙公子"],"foreshadow":"乞巧棚成"},{"id":"A-047-未","branch":"A","stage":2,"day":47,"shichen":"未时","checkpoint":"乞巧棚搭起·二","scene":"未时，官家亲自来了。他摇着扇子绕棚一圈，笑道：「好巧的心思。可惜——商户终究是商户。」","options":[{"text":"商户养汴京繁华","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你朗声道：「官人身上帛、口中茶、炉里香，哪样不是商户供的？」围者喝彩，他拂袖而去。","source":"宋代商人自尊之语，见宋代笔记。"},{"text":"不与他争","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你没接话，转身迎客。孙老爷过后道：「不接是对的——跟那种人争，掉价。」","source":"同上。"}],"difficulty":3,"npc":["官家"],"foreshadow":"官家记恨"},{"id":"A-047-戌","branch":"A","stage":2,"day":47,"shichen":"戌时","checkpoint":"乞巧棚搭起·三","scene":"戌时，两家在棚下合议七夕当日章程。孙夫人忽然道：「七夕那晚，棚交给伙计，你们小两口去州桥上走走。」","options":[{"text":"谢过婆母","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":1,"情缘":1},"feedback":"孙夫人道：「我年轻时也想有人陪我看一回穿针——没赶上。你们替我看了。」","source":"宋代七夕游观之俗，见《梦粱录》。"},{"text":"红着脸应了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"孙公子在旁边咳了一声，耳朵尖红了——原来验药材的手，也会抖。","source":"同上。"}],"difficulty":1,"npc":["孙夫人","孙公子"],"foreshadow":"七夕同游","flavor":true},{"id":"A-048","branch":"A","stage":2,"day":48,"shichen":"辰时","checkpoint":"针囊齐工","scene":"五月十八。三千针囊提前齐工！你验完最后一箱，贴号封库。绣娘们领完工钱节赏，欢天喜地。","options":[{"text":"记下各人等第","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你把绣档名录誊成总册：「往后年年七夕，都是这批人。」王嫂道：「跟着姑娘，有奔头。」","source":"宋代雇工名录之记，见《东京梦华录》。"},{"text":"摆酒谢众人","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"铺前摆了三桌。爹举杯：「这是我闺女挣下的局面。」","source":"宋代谢工之俗。"}],"difficulty":1,"npc":["王嫂","爹"],"foreshadow":"绣档成军","flavor":true},{"id":"A-048-未","branch":"A","stage":2,"day":48,"shichen":"未时","checkpoint":"针囊齐工·二","scene":"未时，樊楼又来人，这回订五十只上等针囊，还要你家新染的「牵牛紫」绦。价钱随你开。","options":[{"text":"照上档价接单","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你开了公道价。来人笑道：「樊楼的姑娘们说了，汴京针囊，就数州桥这家。」","source":"宋代樊楼定制之风，见《东京梦华录》。"},{"text":"借机抬价","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"抬了两成，人家也接了，你心里却不安。娘道：「招牌比银子贵。」你记下了。","source":"宋代商谚。"}],"difficulty":2,"npc":["樊楼来人"],"foreshadow":"樊楼名声"},{"id":"A-048-戌","branch":"A","stage":2,"day":48,"shichen":"戌时","checkpoint":"针囊齐工·三","scene":"戌时盘点：自联营以来，你家流水翻了两番。爹把老账房请来喝酒，老账房对账叹道：「我三十年的账，被个及笄的姑娘比下去了。」","options":[{"text":"敬老师傅一盏","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"你道：「我的账法，底子还是您教的『四柱』。」老师傅捋须大笑：「这话我信！」","source":"宋代师徒之礼，见宋代笔记。"},{"text":"替他添酒","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"酒添三回，老师傅道：「往后汴京的账房行，有你一号。」","source":"同上。"}],"difficulty":1,"npc":["老账房","爹"],"foreshadow":"账房扬名","flavor":true},{"id":"A-049","branch":"A","stage":2,"day":49,"shichen":"辰时","checkpoint":"嫁衣开裁","scene":"五月十九。娘打开箱底，取出攒了十年的妆花缎：「嫁衣，开裁。」你摸着那缎子，忽然有点不敢想八月十六。","options":[{"text":"亲手画衣样","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你画的衣样，袖口绣的是算盘珠与药草纹——商户女的嫁衣，写满她自己的故事。","source":"宋代嫁衣之制，见《东京梦华录》记婚俗。"},{"text":"全听娘的","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"娘道：「娘裁的衣，娘的心；你画的样，你的命。都来一点。」","source":"同上。"}],"difficulty":2,"npc":["娘"],"foreshadow":"嫁衣开裁"},{"id":"A-049-未","branch":"A","stage":2,"day":49,"shichen":"未时","checkpoint":"嫁衣开裁·二","scene":"未时，孙夫人送来聘礼里的一副金钏，说是孙家祖传的：「先给你戴着试手。七夕那晚，戴上它去州桥。」","options":[{"text":"郑重收下","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":1,"情缘":1},"feedback":"金钏压腕，你头一回觉得「孙家人」三个字，有了分量。","source":"宋代传家之礼，见宋代婚俗记载。"},{"text":"推辞太贵重","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"孙夫人把钏套上你手腕：「传的哪是金钏，是管家的心气。收着。」","source":"同上。"}],"difficulty":2,"npc":["孙夫人"],"foreshadow":"金钏传家"},{"id":"A-049-戌","branch":"A","stage":2,"day":49,"shichen":"戌时","checkpoint":"嫁衣开裁·三","scene":"戌时，你在日记里写：「嫁衣开裁了。缎子底下压着的，是娘十年的攒。我忽然明白，嫁女不是泼出去的水，是连根带土移栽的树。」","options":[{"text":"去陪娘坐一会","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"娘什么都没说，只把你的手握着。商户人家的话都在账上，情都在手上。","source":"宋代母女之别情，见闺阁记载。"},{"text":"给娘捶背","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"捶着捶着，娘道：「嫁过去了，也要常回来查账。」你道：「那是自然。」","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"母女之情","flavor":true},{"id":"A-050","branch":"A","stage":2,"day":50,"shichen":"辰时","checkpoint":"回望五十日","scene":"五月二十。及笄第五十日。晨起翻开蓝布账簿，从头一页翻到最新一页：相看、联营、端午、金钏、嫁衣——五十天，像过了半生。","options":[{"text":"写下阶段小结","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你写：「五十日，学会的不只是账——是商户人家的女儿，如何把日子过成自己的。」","source":"宋代女子自省之记，见闺阁墨迹。"},{"text":"合册出门开工","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"回望是夜里的事，白天只管向前。账房娘子，开工。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"半程回望","flavor":true},{"id":"A-050-未","branch":"A","stage":2,"day":50,"shichen":"未时","checkpoint":"回望五十日·二","scene":"未时，官媒婆来报：孙家把婚前的礼数单子都过完了，只余亲迎一项。她笑道：「老婆子说媒三十年，没见过这么顺的。」","options":[{"text":"顺是两家厚道","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"媒婆道：「厚道也得配得起。姑娘，汴京城多少双眼睛，等着看你的花轿呢。」","source":"宋代媒妁之语，见《东京梦华录》记婚俗。"},{"text":"谢她周全","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"谢了媒，封了谢仪。媒婆掂着谢仪笑：「这单媒钱，挣得最体面。」","source":"同上。"}],"difficulty":1,"npc":["官媒婆"],"foreshadow":"只欠亲迎"},{"id":"A-050-戌","branch":"A","stage":2,"day":50,"shichen":"戌时","checkpoint":"回望五十日·三","scene":"戌时，州桥夜市灯火如昼。你立在铺前，看自家香囊摊、乞巧棚、对面生药铺的灯笼——「八月十六」四个字，在夜色里亮着。","options":[{"text":"看着灯笼微笑","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"五十天前你还是个等着被相看的姑娘，五十天后，你有了自己的股、自己的账、自己的姻缘。","source":"宋代街市夜景，见《东京梦华录》。"},{"text":"记今日最后一笔","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"你在账簿上写：「五十日，盈。」——这个盈字，说的不只是银子。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"七夕将近","flavor":true},{"id":"A-051","branch":"A","stage":3,"day":51,"shichen":"辰时","checkpoint":"七夕开棚","scene":"七月初七·七夕。乞巧棚辰时开棚，五色针囊悬如繁星，穿针处排起长队——汴京的姑娘们都来了。","options":[{"text":"开棚迎客","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"穿针、赠彩、系囊，流水般顺。巳时未至，针囊已去三成。","source":"宋代七夕乞巧之俗，见《东京梦华录》。"},{"text":"先焚香拜织女","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"拜过织女再开棚。娘道：「拜的是巧，求的是勤——都对。」","source":"同上。"}],"difficulty":1,"npc":["娘","杏儿"],"foreshadow":"七夕开棚","flavor":true},{"id":"A-051-未","branch":"A","stage":3,"day":51,"shichen":"未时","checkpoint":"七夕开棚·二","scene":"未时，棚前人潮最盛。樊楼订的五十只牵牛紫针囊一挂出，半个时辰抢空。有姑娘出三倍价求你袖上那只。","options":[{"text":"自戴的概不卖","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你笑道：「这一只是非卖品——是我自己的七夕。」众人羡慕哗然。","source":"宋代七夕佩囊之俗。"},{"text":"高价割爱","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"银子到手，心里空了一块。夜里你把那只的图样描下来，留了个念想。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"非卖品"},{"id":"A-051-戌","branch":"A","stage":3,"day":51,"shichen":"戌时","checkpoint":"七夕夜游","scene":"戌时，棚交伙计。你与孙公子并肩上州桥，腕上金钏，腰间香囊。桥上看两岸灯火、满河星月。","options":[{"text":"桥上立誓","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他道：「往后七夕，年年同看。」你道：「记账上了，赖不掉。」——心意账，最重一笔。","source":"宋代七夕盟誓之记，见话本。"},{"text":"默然并肩","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"什么都没说。桥下河水哗哗，替你们说了。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"州桥盟约","flavor":true},{"id":"A-052","branch":"A","stage":3,"day":52,"shichen":"辰时","checkpoint":"七夕盘账","scene":"七月初八。七夕盘账：三千针囊售空，联营再捷。你把两家分利算清，孙老爷看完只说四个字：「稳、准、公、清。」","options":[{"text":"利留三成滚本","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你提议利留三成作中秋香帕本金。两家照准。商户的钱，是会下崽的。","source":"宋代联营滚本之记，见宋代商书。"},{"text":"全数分掉","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"分是分了，中秋备货又得拆借。你把「滚本」二字记进了账簿扉页。","source":"同上。"}],"difficulty":2,"npc":["孙老爷"],"foreshadow":"中秋香帕"},{"id":"A-052-未","branch":"A","stage":3,"day":52,"shichen":"未时","checkpoint":"七夕盘账·二","scene":"未时，街谈巷议都在说州桥乞巧棚。有人不服，酸道：「不过是个要嫁人的，抛头露面。」","options":[{"text":"生意与嫁人都做","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你道：「嫁人是我的喜事，生意是我的本事——两桩都要，两桩都成。」","source":"宋代女子经商之记，见宋代笔记。"},{"text":"懒得理会","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"不理是对的。账簿一翻，流水替你把话都说完了。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"名声渐起"},{"id":"A-052-戌","branch":"A","stage":3,"day":52,"shichen":"戌时","checkpoint":"七夕盘账·三","scene":"戌时，孙公子递来一只小匣：「七夕的回礼。」打开——一方端砚，砚底刻着四个小字：「账房娘子」。","options":[{"text":"收下入日记","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你在日记写：「得砚一方。他懂我——送的不是钗环，是笔墨。」","source":"宋代文房定情之雅，见宋代笔记。"},{"text":"回赠笔一支","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你回了支紫毫：「砚配笔，账配人。」他郑重收进怀里。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"端砚定情","flavor":true},{"id":"A-053","branch":"A","stage":3,"day":53,"shichen":"辰时","checkpoint":"嫁衣试样","scene":"七月初九。嫁衣头样试身。妆花缎上身，袖口算盘珠与药草纹若隐若现。娘围着你转了三圈，眼圈红了。","options":[{"text":"问娘可好","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"娘道：「好。就是太好看了，娘舍不得。」","source":"宋代嫁衣试身之记，见婚俗记载。"},{"text":"转个圈给她看","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"转完，娘背过身去抹眼睛。杏儿道：「夫人这是欢喜的。」","source":"同上。"}],"difficulty":1,"npc":["娘","杏儿"],"foreshadow":"嫁衣将成","flavor":true},{"id":"A-053-未","branch":"A","stage":3,"day":53,"shichen":"未时","checkpoint":"嫁衣试样·二","scene":"未时，二嫂来送「添箱」——一匹缭绫。她看你试嫁衣，忽然低声道：「弟妹，我出嫁那年……婆家嫌我奁产薄，头三年没给我好脸。」","options":[{"text":"握她的手","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你道：「往后孙家的账，你我同管。谁的脸色都不用看。」二嫂的眼泪落下来。","source":"宋代妯娌相恤之记，见家训类书。"},{"text":"岔开话说衣裳","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"岔开了，但二嫂那句「往后多照应」你记下了。过门后第一件，就是拉她同看账。","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"妯娌同盟"},{"id":"A-053-戌","branch":"A","stage":3,"day":53,"shichen":"戌时","checkpoint":"嫁衣试样·三","scene":"戌时，爹把你叫到柜上，交给你一只旧木匣：「这是你外祖传下的『市易谱』——汴京各行当的老主顾名册。陪嫁给你。」","options":[{"text":"拜谢收下","correct":true,"tags":["家世","才华"],"dims":{"家世":2,"才华":1},"feedback":"一册名册，三代人的商誉。爹道：「箱笼是死的，主顾是活的。这才是嫁妆。」","source":"宋代商贾传谱之记，见宋代笔记。"},{"text":"推说给弟弟","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"爹道：「你弟弟那份另有。这份，是给会做账的人的。」","source":"同上。"}],"difficulty":2,"npc":["爹"],"foreshadow":"市易谱"},{"id":"A-054","branch":"A","stage":3,"day":54,"shichen":"辰时","checkpoint":"中秋香帕","scene":"七月初十。中秋香帕开工。这回你加了新花样：帕角绣小楷「团圆」二字，是请州桥的老书生题的。","options":[{"text":"题字款单定价","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"题字款比素帕贵三成，预订的帖子当日下午就来了十几张。","source":"宋代书画入货之例，见《东京梦华录》。"},{"text":"素帕题字同价","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"同价卖，题字的抢光素帕剩。你把价差记进账——「雅」也是本钱。","source":"同上。"}],"difficulty":2,"npc":["老书生"],"foreshadow":"团圆帕"},{"id":"A-054-未","branch":"A","stage":3,"day":54,"shichen":"未时","checkpoint":"中秋香帕·二","scene":"未时，官家的管家三顾茅庐，这回姿态极低：官家要在中秋宴上用你家的团圆帕，订二百条，现银。","options":[{"text":"生意照做人不做","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"你道：「货照市价、银要现付、契要过市吏——至于交情，没有。」管家讪讪立契。","source":"宋代市井交易之规，见《名公书判清明集》。"},{"text":"一口回绝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"拒得痛快。娘道：「也好。他那银子，挣着膈应。」","source":"同上。"}],"difficulty":3,"npc":["官家管家"],"foreshadow":"官家低头"},{"id":"A-054-戌","branch":"A","stage":3,"day":54,"shichen":"戌时","checkpoint":"中秋香帕·三","scene":"戌时，孙公子听说官家现银订货，赶来道：「你接了？」你道：「接了。」他松口气又皱眉：「也好也不好。」","options":[{"text":"银子干净就行","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你道：「契过官、银过秤、货出门——他的银子进了我的账，就是我的干净钱。」他叹服。","source":"宋代商贾自处之语，见话本。"},{"text":"逗他吃醋","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他果然急了：「他那是买帕吗？他那是买……」买半天说不出口，你笑出声。","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"官家觊觎未消"},{"id":"A-055","branch":"A","stage":3,"day":55,"shichen":"辰时","checkpoint":"铺股首红","scene":"七月十一。铺股头一回分红：你那两成干股，分了十二贯。爹把一贯一贯点给你，像在举行什么仪式。","options":[{"text":"入『我的账』","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"十二贯，入自己户头第一笔大额。你在扉页添了行小字：「靠自己，饿不着。」","source":"宋代女子私财之记，见《名公书判清明集》。"},{"text":"拿两贯孝敬娘","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"娘不收，你塞进她匣里：「这是分红，不是孝敬——娘也是铺里的老伙计。」","source":"同上。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"私户渐丰","flavor":true},{"id":"A-055-未","branch":"A","stage":3,"day":55,"shichen":"未时","checkpoint":"铺股首红·二","scene":"未时，你拿分红的银子，去书铺订了一部《岁时广记》——翻节令，找商机。书铺老板奇道：「姑娘看这书做什么？」","options":[{"text":"找一年的生意","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你道：「端午囊、七夕针、中秋帕——一年二十四节，节节都是买卖。」老板肃然起敬。","source":"宋代应节商卖之记，见《东京梦华录》。"},{"text":"消闲看看","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老板笑道：「消闲看《岁时广记》的，汴京就您一位。」","source":"同上。"}],"difficulty":2,"npc":["书铺老板"],"foreshadow":"节节商机"},{"id":"A-055-戌","branch":"A","stage":3,"day":55,"shichen":"戌时","checkpoint":"铺股首红·三","scene":"戌时，夜市收摊。你坐在柜前，左边是铺里的总账，右边是「我的账」，中间是蓝布账簿——三册并排放着。","options":[{"text":"三册都是底气","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一册是家，一册是我，一册是心。账房娘子的全副家当，都在案上了。","source":"宋代账册之记，见宋代笔记。"},{"text":"吹灯前又翻一遍","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"翻完心安。商户人家的女儿，睡前核账，梦里都踏实。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"三册底气","flavor":true},{"id":"A-056","branch":"A","stage":3,"day":56,"shichen":"辰时","checkpoint":"待嫁规矩","scene":"七月十二。孙夫人遣嬷嬷来教规矩：过门后的晨昏定省、祭祀次序、待客的站位。嬷嬷一条条念，你一条条记。","options":[{"text":"记成账册格式","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你把规矩编成「条目账」：何事、何时、何人、如何——嬷嬷看了直呼清楚。","source":"宋代新妇规矩之教，见家训类书。"},{"text":"凭记性背","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"背是背下了，乱。夜里你还是熬灯写成了册——账房娘子，离了纸笔不行。","source":"同上。"}],"difficulty":2,"npc":["嬷嬷"],"foreshadow":"规矩成册"},{"id":"A-056-未","branch":"A","stage":3,"day":56,"shichen":"未时","checkpoint":"待嫁规矩·二","scene":"未时，嬷嬷考你：「若婆母与嫂氏同日差你做事，你先应哪个？」","options":[{"text":"先问缓急再定","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你答：「急者先，重者先；若一般急，禀明婆母，请嫂氏宽限。」嬷嬷点头：「不死板。」","source":"宋代新妇应对之记，见家训类书。"},{"text":"先应婆母","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"嬷嬷道：「婆母要敬，嫂氏也不可慢。一味攀高，日子反而窄。」","source":"同上。"}],"difficulty":3,"npc":["嬷嬷"],"foreshadow":"妯娌之道"},{"id":"A-056-戌","branch":"A","stage":3,"day":56,"shichen":"戌时","checkpoint":"待嫁规矩·三","scene":"戌时，娘看你抄规矩抄到深夜，端来一碗羹：「规矩要学，可别把自己学没了。」","options":[{"text":"规矩为我所用","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你道：「娘放心，规矩是盾不是绳——我举着它走，不让它捆着我。」娘笑了。","source":"宋代女子自处之语，见闺阁记载。"},{"text":"心里自有数","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"羹喝了，册子合了。规矩记下了，人还是那个人。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"规矩与自我","flavor":true},{"id":"A-057","branch":"A","stage":3,"day":57,"shichen":"辰时","checkpoint":"奁产清点","scene":"七月十三。清点奁产：箱笼十二只、妆花缎嫁衣、金钏、铺股契、市易谱、端砚——你一件件验看入册。","options":[{"text":"立奁产总册","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"奁产总册一成，娘道：「别人嫁女抬箱笼，我家嫁女抬账本——底气都在纸上。」","source":"宋代奁产之制，见《名公书判清明集》。"},{"text":"请娘再验一遍","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"娘验完，在册尾按了手印：「娘的闺女，出门也是东家。」","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"奁产总册","flavor":true},{"id":"A-057-未","branch":"A","stage":3,"day":57,"shichen":"未时","checkpoint":"奁产清点·二","scene":"未时，杏儿一边装箱一边哭。你道：「哭什么？」她道：「姑娘嫁过去，我跟不跟？」","options":[{"text":"早把你写进单了","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你翻开陪嫁名录，头一行就是「杏儿」。她破涕为笑，又哭得更凶了。","source":"宋代陪嫁侍婢之俗，见《东京梦华录》。"},{"text":"问孙家去","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"孙公子回话：「你的人，就是你的。」杏儿听了，走路都带风。","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"杏儿随嫁"},{"id":"A-057-戌","branch":"A","stage":3,"day":57,"shichen":"戌时","checkpoint":"奁产清点·三","scene":"戌时，你把蓝布账簿放进箱笼最上层。忽然顿住——出嫁之后，「心意账」还记吗？","options":[{"text":"记到一百岁","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你在末页写：「此账无结清之日。」——有些账，就是要记一辈子的。","source":"宋代闺阁笺记之习。"},{"text":"换本新的继续","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"旧册收箱，新册封面已想好：「孙家账·我心册」。名字长了点，无所谓。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"心意账续记","flavor":true},{"id":"A-058","branch":"A","stage":3,"day":58,"shichen":"辰时","checkpoint":"中秋备货","scene":"七月十四。团圆帕出了八百条，樊楼、官家的订单都在赶。你巡库，发现绣「团圆」二字的丝线不够了。","options":[{"text":"急调苏杭丝线","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你翻市易谱，找到外祖的老主顾，快马调线，五日即达。老关系，救了急。","source":"宋代南北货殖之记，见《梦粱录》。"},{"text":"改用本地线","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"本地线色差明显，题字款的体面打了折。你咬牙还是调了苏线。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"市易谱显威"},{"id":"A-058-未","branch":"A","stage":3,"day":58,"shichen":"未时","checkpoint":"中秋备货·二","scene":"未时，孙夫人请你过府——不教你规矩，是请你核孙家的中秋账。她道：「生药铺的账，你先过过目。」","options":[{"text":"三日核出总册","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"三日后总册呈上，孙夫人看完沉默良久：「我掌家二十年，账目头一回这么亮。」","source":"宋代主妇掌账之记，见家训类书。"},{"text":"推说婚前避嫌","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"孙夫人道：「自家人避什么嫌？我这是把家底亮给你——信你。」你于是接了。","source":"同上。"}],"difficulty":3,"npc":["孙夫人"],"foreshadow":"孙家账目"},{"id":"A-058-戌","branch":"A","stage":3,"day":58,"shichen":"戌时","checkpoint":"中秋备货·三","scene":"戌时核孙家账，你发现生药铺有笔三年的陈账没收回来，挂了两百贯。","options":[{"text":"记下婚前不点破","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你只记在自册。过门后收账是立威，婚前点破是越界——分寸，也是账。","source":"宋代处世分寸之记，见宋代笔记。"},{"text":"当面问孙夫人","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"问了。孙夫人坦然：「那是我娘家的烂账，你过门后帮我想想法子。」也算交底。","source":"同上。"}],"difficulty":3,"npc":[],"foreshadow":"陈账两百贯"},{"id":"A-059","branch":"A","stage":3,"day":59,"shichen":"辰时","checkpoint":"添箱日","scene":"七月十五·中元。也是你家「添箱」的日子，亲眷都来送嫁礼。你一一唱名收礼、记账、回帖。","options":[{"text":"礼账两清","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"礼单、谢帖、回礼，一日理清。姨母叹：「这哪是嫁女，是开柜收账。」","source":"宋代添箱之俗，见《东京梦华录》记婚俗。"},{"text":"请娘分担","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"娘管收礼你管账，母女搭配，半日就齐。爹在旁直乐。","source":"同上。"}],"difficulty":1,"npc":["娘","亲眷"],"foreshadow":"添箱礼成","flavor":true},{"id":"A-059-未","branch":"A","stage":3,"day":59,"shichen":"未时","checkpoint":"添箱日·二","scene":"未时，姨母拉着你说体己话：「嫁了人，头三年最难。婆母、妯娌、下人，全是关卡。你预备怎么过？」","options":[{"text":"以诚待人以账立身","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你道：「真心换人心，账目换尊重。关卡再多，也挡不住明白人。」姨母抚掌。","source":"宋代新妇自处之记，见家训类书。"},{"text":"走一步看一步","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"姨母道：「你这孩子心里有谱，嘴上不说——也好，藏拙是福。」","source":"同上。"}],"difficulty":2,"npc":["姨母"],"foreshadow":"过门三关"},{"id":"A-059-戌","branch":"A","stage":3,"day":59,"shichen":"戌时","checkpoint":"添箱日·三","scene":"戌时，宾客散尽。娘把白日收的礼单又看了一遍，忽然道：「你外祖当年说，咱家出个大人物——原来应在你身上。」","options":[{"text":"女儿只是会算账","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"娘道：「会算账，就是把日子攥在自己手里。这比大人物强。」","source":"宋代商户家语，见宋代笔记。"},{"text":"靠在娘肩上","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"靠了一会儿。再过两个月，这肩膀就是「娘家」了。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"母女惜别","flavor":true},{"id":"A-060","branch":"A","stage":3,"day":60,"shichen":"辰时","checkpoint":"及笄双月","scene":"七月十六·及笄满双月。晨起核账：联营三月，两家流水都翻了番；你的私户，已攒下四十贯。","options":[{"text":"写双月总录","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你写：「双月，六十日。商户女的本事，不是嫁得好——是无论嫁不嫁，都立得住。」","source":"宋代女子自立之记，见宋代笔记。"},{"text":"合册去开工","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"账簿一合，又是开工的一天。婚期还有一个月，手上的活一寸不能松。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"婚期一月","flavor":true},{"id":"A-060-未","branch":"A","stage":3,"day":60,"shichen":"未时","checkpoint":"及笄双月·二","scene":"未时，孙公子来送中秋帕的药料配单，见你私户账上的四十贯，咋舌：「我攒十年也没这些。」","options":[{"text":"婚后各管各账","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":2,"情缘":1},"feedback":"你道：「你的钱你管，我的钱我管，家里的账一起管。」他大笑：「好！这才叫账房娘子。」","source":"宋代夫妻财分之记，见《名公书判清明集》。"},{"text":"笑他不上进","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他不恼：「往后我挣的，都交给你管。」你道：「想得美，自己的账自己算。」","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"婚后约法"},{"id":"A-060-戌","branch":"A","stage":3,"day":60,"shichen":"戌时","checkpoint":"及笄双月·三","scene":"戌时，夜市灯火里，对面生药铺的灯笼换了新的——「八月十六」四个字描了金。整条街都知道这桩婚事了。","options":[{"text":"灯下立了片刻","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"还有三十日。你忽然不怕嫁了——嫁的不是人家，是那个愿意把婚期挂上灯笼的人。","source":"宋代街市灯彩之俗，见《东京梦华录》。"},{"text":"把这一幕记下","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"心意账上添一笔：「七月十六，灯笼描金。离八月十六，三十日。」","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"婚期三十日","flavor":true},{"id":"A-061","branch":"A","stage":3,"day":61,"shichen":"辰时","checkpoint":"中秋将近","scene":"七月十七。团圆帕已出一千五百条。你巡市，见别家也仿了「题字帕」，只是字是描的，不是题的。","options":[{"text":"真迹立牌自明","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你在摊前立牌：「本店帕字，州桥张先生亲题，描仿者不同。」识货的自然来。","source":"宋代商贾辨伪之法，见《东京梦华录》。"},{"text":"降价争市","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"爹拦了：「跟人斗价，是把自家招牌往泥里踩。」你改立了辨真牌。","source":"宋代商谚。"}],"difficulty":2,"npc":["爹"],"foreshadow":"仿品出现"},{"id":"A-061-未","branch":"A","stage":3,"day":61,"shichen":"未时","checkpoint":"中秋将近·二","scene":"未时，官家的管家又来，这回送的是一张帖子：官家中秋夜宴，「请」你过府——「献帕」。","options":[{"text":"货可送人不赴宴","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你回帖：「货由伙计送至，银货两讫。小女待嫁，礼不出门。」滴水不漏。","source":"宋代待嫁女子避见之礼，见《东京梦华录》。"},{"text":"赴宴看他要怎样","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"帖子还没回，娘先急了：「待嫁的人赴外男夜宴？这是局！」你醒过神，改送货不赴宴。","source":"同上。"}],"difficulty":3,"npc":["官家管家","娘"],"foreshadow":"官家设局"},{"id":"A-061-戌","branch":"A","stage":3,"day":61,"shichen":"戌时","checkpoint":"中秋将近·三","scene":"戌时，孙公子听闻献帕帖，气得摔了药钵：「他这是逼你抛头露面！」","options":[{"text":"我没接这局","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"你把回帖给他看。他看完，默默把摔裂的药钵扫了：「是我沉不住气。」","source":"宋代青年男女相护之记，见话本。"},{"text":"笑他摔钵","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他道：「钵摔得起，你闪失不起。」这话糙，理不糙。","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"官家记恨加深"},{"id":"A-062","branch":"A","stage":3,"day":62,"shichen":"辰时","checkpoint":"婚前铺务","scene":"七月十八。爹召集伙计：「姑娘出阁后，铺子的联营账，还归她管。你们有半个月跟她学章程。」","options":[{"text":"立轮值学账制","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你立了轮值表：每人三日一轮，学看账、学盘库、学验货。伙计们叫苦，也服气。","source":"宋代商铺传艺之记，见宋代笔记。"},{"text":"全交给老账房","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老账房摆手：「我教出的徒弟，哪能再还给我？」还是你排了轮值。","source":"同上。"}],"difficulty":2,"npc":["爹","伙计们","老账房"],"foreshadow":"铺务移交"},{"id":"A-062-未","branch":"A","stage":3,"day":62,"shichen":"未时","checkpoint":"婚前铺务·二","scene":"未时，弟弟——你那十二岁的兄弟，抱着算筹来找你：「阿姊，你嫁走了，谁教我算账？」","options":[{"text":"姊嫁后月查你账","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你给他立了「学徒账」：「每月初一我回门查账，错一处，抄十遍。」他又怕又高兴。","source":"宋代家业承继之教，见家训类书。"},{"text":"让他自己悟","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他当场就蔫了。你补了句「每月初一查账」，他才重新有了主心骨。","source":"同上。"}],"difficulty":2,"npc":["弟弟"],"foreshadow":"弟弟学账"},{"id":"A-062-戌","branch":"A","stage":3,"day":62,"shichen":"戌时","checkpoint":"婚前铺务·三","scene":"戌时，你在日记里写：「白日移交铺务，夜里忽然不舍。这柜台我站了三个月，比闺房还亲。」","options":[{"text":"出嫁也常回来","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"爹说了：「铺股在你手里，这柜台就有你一半。嫁出去的女儿，泼出去的是水不是股。」","source":"宋代奁产之制，见《名公书判清明集》。"},{"text":"擦了擦柜台","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"擦得锃亮。柜台不会说话，但它记得每一笔记账的手。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"柜台情结","flavor":true},{"id":"A-063","branch":"A","stage":3,"day":63,"shichen":"辰时","checkpoint":"婚前风波","scene":"七月十九。汴京忽然传开一桩「新闻」：官家放话，说你家的联营契「来路不正」，要请官府验契。","options":[{"text":"请市吏公验","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你主动请市吏当众验契：契真、印真、保人真。围观者散去，官家的脸丢尽了。","source":"宋代验契之制，见《名公书判清明集》。"},{"text":"私下打点压下","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"打点花的银子比验契多十倍，风言风语还没断。你后悔没走明路。","source":"同上。"}],"difficulty":3,"npc":["市吏"],"foreshadow":"验契自明"},{"id":"A-063-未","branch":"A","stage":3,"day":63,"shichen":"未时","checkpoint":"婚前风波·二","scene":"未时，验契毕。孙老爷当街朗声：「我孙家的亲家，账目清白、契券清白、人更清白！」满街喝彩。","options":[{"text":"当街谢过","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":1,"情缘":1},"feedback":"你盈盈一拜。孙老爷扶住：「一家人不说两家话——他再敢嚼舌，先过我这一关。」","source":"宋代商户互保之风，见《东京梦华录》。"},{"text":"记在日记里","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你写：「今日孙老爷当街护我。这婆家，值得嫁。」","source":"同上。"}],"difficulty":1,"npc":["孙老爷"],"foreshadow":"两家一心","flavor":true},{"id":"A-063-戌","branch":"A","stage":3,"day":63,"shichen":"戌时","checkpoint":"婚前风波·三","scene":"戌时，官家的管家最后一次登门，留下一句话：「官人说了，山不转水转。」","options":[{"text":"水转也不转我这","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你回：「替我回禀官人：商户家的门槛不高，但迈进来要按规矩。」门关上了。","source":"宋代商户风骨之语，见宋代笔记。"},{"text":"不予理会","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"理都没理。有些账，不值得入册。","source":"同上。"}],"difficulty":1,"npc":["官家管家"],"foreshadow":"官家退场","flavor":true},{"id":"A-064","branch":"A","stage":3,"day":64,"shichen":"辰时","checkpoint":"中秋大卖","scene":"七月二十。离中秋二十六日，团圆帕预订已过两千条，官家的二百条也交货收讫——现银，一文不少。","options":[{"text":"收讫入账","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你在账上写：「官家单，银讫，事毕。」六个字，恩仇两清。","source":"宋代银货两讫之记。"},{"text":"多送两条","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"娘拦了：「一条不多，一条不少——跟那种人，两清最干净。」","source":"宋代商谚。"}],"difficulty":2,"npc":["娘"],"foreshadow":"官家事了"},{"id":"A-064-未","branch":"A","stage":3,"day":64,"shichen":"未时","checkpoint":"中秋大卖·二","scene":"未时，州桥老书生来报喜：他题的「团圆」二字随香帕传开后，有贵家请他题匾额——「都是托姑娘的福。」","options":[{"text":"贺他分文不取","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你道：「先生的字养我的帕，我的帕扬先生的名——两不相欠，两相成全。」","source":"宋代文商相济之记，见宋代笔记。"},{"text":"请他再题秋词","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"老书生欣然应下，还说要给你写婚联。这笔买卖，越算越值。","source":"同上。"}],"difficulty":2,"npc":["老书生"],"foreshadow":"婚联之约"},{"id":"A-064-戌","branch":"A","stage":3,"day":64,"shichen":"戌时","checkpoint":"中秋大卖·三","scene":"戌时，盘账毕。你与孙公子隔着街对账——他在对面核药账，你在这边核帕账，两盏灯，两个人。","options":[{"text":"隔街举起账册","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他也举了举账册。两本账，两盏灯，一条街——这就是商户人家的花前月下。","source":"宋代夜市之景，见《东京梦华录》。"},{"text":"先吹灯睡","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你先吹了灯。对面的灯过了一会儿才灭——他在等你先歇。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"灯下对账","flavor":true},{"id":"A-065","branch":"A","stage":3,"day":65,"shichen":"辰时","checkpoint":"嫁衣告成","scene":"七月廿一。嫁衣告成！妆花缎、算盘珠袖口、药草纹——娘把它挂起来，全家围着看，弟弟问：「阿姊穿上像不像神仙？」","options":[{"text":"像账房先生","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"全家笑倒。你道：「神仙不管人间账，我管。」","source":"宋代婚俗诙谐之记，见话本。"},{"text":"笑着谢他","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"弟弟道：「那姐夫娶的是神仙，得好好供着。」爹道：「这话中听。」","source":"同上。"}],"difficulty":1,"npc":["娘","弟弟","爹"],"foreshadow":"嫁衣告成","flavor":true},{"id":"A-065-未","branch":"A","stage":3,"day":65,"shichen":"未时","checkpoint":"嫁衣告成·二","scene":"未时，二嫂送来添妆——一对银梳。她拉你坐下，低声把孙家各房的人口、脾气、忌讳，细细交了一遍底。","options":[{"text":"逐条记下","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"你记成「孙家谱系册」。二嫂道：「我过门时没人教我，跌了三年的跤——不教你跌。」","source":"宋代妯娌相授之记，见家训类书。"},{"text":"心领神会","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你听了大半，忘了小半。夜里凭记忆补册，暗悔没当场落笔。","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"孙家谱系"},{"id":"A-065-戌","branch":"A","stage":3,"day":65,"shichen":"戌时","checkpoint":"嫁衣告成·三","scene":"戌时，娘把一把新钥匙挂在你嫁妆钥匙串上：「这是娘的小金库——不是给你钱的，是教你：女人手里，要有一把自己开的锁。」","options":[{"text":"记住了","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你握着钥匙串——铺股契、奁产册、小金库。娘给的哪里是钥匙，是半生的活法。","source":"宋代母教之记，见家训类书。"},{"text":"红了眼眶","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"娘道：「哭什么，又不是不回来了——初一月查账，你定的。」","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"钥匙之教","flavor":true},{"id":"A-066","branch":"A","stage":3,"day":66,"shichen":"辰时","checkpoint":"中秋夜宴","scene":"七月廿二。中秋月圆。你家设宴，孙家全家也来——这是婚前两家头一回同桌团圆。","options":[{"text":"席上分团圆帕","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"人各一条团圆帕。孙夫人举着帕道：「明年的中秋，就是一家人了。」","source":"宋代中秋团圆之俗，见《梦粱录》。"},{"text":"先拜月再入席","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"拜月礼成，月正圆。娘低声道：「月老看着呢。」","source":"宋代拜月之俗。"}],"difficulty":1,"npc":["孙夫人","娘"],"foreshadow":"两家团圆","flavor":true},{"id":"A-066-未","branch":"A","stage":3,"day":66,"shichen":"未时","checkpoint":"中秋夜宴·二","scene":"未时，宴间行酒令。轮到你，出的令是：「以账入诗。」满座愕然——这怎么行？","options":[{"text":"念「盈亏皆文章」","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你念：「一进一出皆是数，一盈一亏皆文章。」孙老爷拊掌：「商户诗，第一家！」","source":"宋代酒令之俗，见《东京梦华录》。"},{"text":"罚酒一盏","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"认罚一盏。二嫂笑道：「弟妹的令太刁，连自己都套住了。」","source":"同上。"}],"difficulty":2,"npc":["孙老爷","二嫂"],"foreshadow":"账诗雅令"},{"id":"A-066-戌","branch":"A","stage":3,"day":66,"shichen":"戌时","checkpoint":"中秋夜宴·三","scene":"戌时，宴散月圆。你与孙公子在廊下看月。他忽然道：「去年中秋我看账，今年中秋看你。」","options":[{"text":"明年中秋看账","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你道：「明年中秋，咱俩一起核联营的年账。」他笑道：「连赏月都要带着账——我娶对了。」","source":"宋代中秋赏月之俗，见《梦粱录》。"},{"text":"月光下无言","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"月亮很圆，话很少。有些话，要留到八月十六以后说。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"月下之约","flavor":true},{"id":"A-067","branch":"A","stage":3,"day":67,"shichen":"辰时","checkpoint":"中秋捷报","scene":"七月廿三。中秋盘账：团圆帕三千条售罄，题字款供不应求。联营三月，三家（算上绣档）俱盈。","options":[{"text":"三节三捷","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"端午囊、七夕针、中秋帕——三节三捷。汴京商圈已有名号：「州桥节令第一家」。","source":"宋代节令商卖之记，见《东京梦华录》。"},{"text":"不敢自满","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你在账簿写：「三节之捷，节在人前；来年之局，局在人后。」戒骄。","source":"宋代商谚。"}],"difficulty":1,"npc":[],"foreshadow":"州桥第一家","flavor":true},{"id":"A-067-未","branch":"A","stage":3,"day":67,"shichen":"未时","checkpoint":"中秋捷报·二","scene":"未时，有外地客商慕名来访，要把你的节令货贩到江南去，开口就要包销全年。","options":[{"text":"只签三节试销","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你道：「先签三节，路走通了再谈全年——货出远门，招牌更要走得稳。」客商敬服。","source":"宋代远程贩运之记，见《梦粱录》。"},{"text":"全年包销一口应","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"应得快，爹拦得更快：「婚前大事当前，分不得心。三节试销，年后再谈。」","source":"宋代商谚。"}],"difficulty":3,"npc":["外地客商","爹"],"foreshadow":"江南商路"},{"id":"A-067-戌","branch":"A","stage":3,"day":67,"shichen":"戌时","checkpoint":"中秋捷报·三","scene":"戌时，你在「我的账」里写：「江南商路，待来年。」写完忽然意识到——来年，我已是孙家的人了。","options":[{"text":"孙家人也能写","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"笔没停。商户家的账册不看出身看出息，姓什么不重要，账是谁的才重要。","source":"宋代女子立产之记，见《名公书判清明集》。"},{"text":"顿了一顿再写","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"顿的那一顿，是跟「闺女」二字道别。写完，翻篇。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"身份将易","flavor":true},{"id":"A-068","branch":"A","stage":3,"day":68,"shichen":"辰时","checkpoint":"催妆前","scene":"七月廿四。距婚期廿三日。孙家遣人送来「催妆礼」的先帖——婚前的最后一轮礼数，要开始了。","options":[{"text":"照礼单预备","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你把礼单、回单、时辰、人手列成总表。官媒婆看了道：「老婆子只管跑腿就行。」","source":"宋代催妆之礼，见《东京梦华录》记婚俗。"},{"text":"问娘旧例","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"娘翻出她当年的礼单，墨迹都黄了。母女对着两张单子，忽然都有点恍惚。","source":"同上。"}],"difficulty":1,"npc":["官媒婆","娘"],"foreshadow":"催妆将至"},{"id":"A-068-未","branch":"A","stage":3,"day":68,"shichen":"未时","checkpoint":"催妆前·二","scene":"未时，杏儿试穿随嫁的衣裙，转了三圈问你好不好看。你忽然想起，这丫头跟了你八年。","options":[{"text":"给她也添了钗","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你把一支银钗插在她头上：「陪嫁的不止箱笼，还有你——风光都要一人一半。」","source":"宋代主仆之情，见宋代笔记。"},{"text":"好看极了","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"杏儿美滋滋。她道：「到了孙家，我还给姑娘守账房。」","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"杏儿随嫁","flavor":true},{"id":"A-068-戌","branch":"A","stage":3,"day":68,"shichen":"戌时","checkpoint":"催妆前·三","scene":"戌时，爹独自在柜上坐着，面前摊着你这三个月记的账。你过去，他道：「再看一遍，往后就是回门才能看了。」","options":[{"text":"陪爹再看一遍","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"父女俩一页页翻。翻到「心意账」那页，爹咳嗽一声，翻过去了——他知道，也不说破。","source":"宋代父女之情，见宋代笔记。"},{"text":"给爹添茶","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"茶添了三回，谁都没说话。商户人家的话，都在账里。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"父女惜别","flavor":true},{"id":"A-069","branch":"A","stage":3,"day":69,"shichen":"辰时","checkpoint":"催妆礼","scene":"七月廿五·催妆日。孙家催妆礼到：花髻、脂粉、销金盖头，还有一杆小小的乌木算盘——孙夫人特意添的。","options":[{"text":"把算盘供在箱首","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"娘看了感慨：「别家催妆催的是打扮，孙家催的是本事——这亲家，没看走眼。」","source":"宋代催妆之礼，见《东京梦华录》。"},{"text":"当场打了一遍","correct":true,"tags":["才华","自主"],"dims":{"才华":1},"feedback":"噼啪一通，是「狮子滚绣球」。媒婆啧啧：「头一回见新娘子催妆打算盘的。」","source":"同上。"}],"difficulty":1,"npc":["官媒婆","娘"],"foreshadow":"乌木算盘","flavor":true},{"id":"A-069-未","branch":"A","stage":3,"day":69,"shichen":"未时","checkpoint":"催妆礼·二","scene":"未时，回催妆帖。你在回帖里夹了一张自己写的「婚后章程」：每月初一归宁查账、联营账仍归你管、私户自立。","options":[{"text":"章程随帖送去","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"孙夫人看完笑道：「这媳妇连过门都带章程。」当下照准，还添了句：「本该如此。」","source":"宋代新妇立约之记，见宋代笔记。"},{"text":"还是别夹了","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"收回来了。但章程序言你留着自己看：「婚是结两姓之好，不是交出自己的户头。」","source":"同上。"}],"difficulty":3,"npc":["孙夫人"],"foreshadow":"婚后章程"},{"id":"A-069-戌","branch":"A","stage":3,"day":69,"shichen":"戌时","checkpoint":"催妆礼·三","scene":"戌时，孙公子遣人送来一张纸——不是情诗，是一张他亲手誊的「生药铺总账目录」，扉页写：「请娘子过目。」","options":[{"text":"回他「三日后核」","correct":true,"tags":["情缘","才华","感情"],"dims":{"情缘":1,"才华":1},"feedback":"全城送花送钗，他送账目目录——这世上最懂你的聘礼，莫过于此。","source":"宋代文士赠卷之雅，见宋代笔记。"},{"text":"收进奁产总册","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你把它编进奁产册末页：「附：孙家账一卷——不是奁产，是信任。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"账目为聘","flavor":true},{"id":"A-070","branch":"A","stage":3,"day":70,"shichen":"辰时","checkpoint":"婚前十日","scene":"七月廿六。婚期进入倒计时。铺子里，弟弟开始独立看早账，错了两处，自己查出来改掉了。","options":[{"text":"夸他自查得好","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你道：「账错不怕，自查最贵。这铺子往后有你一半，你撑得起。」他挺起了胸。","source":"宋代家业承继之教，见家训类书。"},{"text":"再盯他三日","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"盯了三日，他战战兢兢反而错得多。你学会了一课：放手，也是交接。","source":"同上。"}],"difficulty":2,"npc":["弟弟"],"foreshadow":"弟弟接柜"},{"id":"A-070-未","branch":"A","stage":3,"day":70,"shichen":"未时","checkpoint":"婚前十日·二","scene":"未时，王嫂带绣娘们送来一份厚礼——二十八个绣娘合力绣的百子帐，帐角绣了一行小字：「州桥绣档敬贺」。","options":[{"text":"收下记恩情账","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你在心意账上写：「百子帐一顶，二十八人同心。这情分，记一辈子。」","source":"宋代贺婚之俗，见宋代笔记。"},{"text":"回赠每人针金","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"你回赠针金，绣娘们推让半天收了。王嫂道：「姑娘出阁，是咱绣档的体面。」","source":"同上。"}],"difficulty":1,"npc":["王嫂","绣娘们"],"foreshadow":"百子帐","flavor":true},{"id":"A-070-戌","branch":"A","stage":3,"day":70,"shichen":"戌时","checkpoint":"婚前十日·三","scene":"戌时，夜静。你翻出及笄那日的日记：「今日及笄，及笄意味着，要相看了。」九十天，恍如隔世。","options":[{"text":"续写今日一笔","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你写：「九十天前怕被挑中，九十天后我挑了日子、挑了人、挑了自己的活法。」","source":"宋代闺阁自省之记。"},{"text":"合上旧册","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"旧册将满，新册待开。婚前十日，落笔无悔。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"九十天回望","flavor":true},{"id":"A-071","branch":"A","stage":3,"day":71,"shichen":"辰时","checkpoint":"婚前十日·四","scene":"七月廿七。婚前九日。媒婆来核对亲迎当日的仪程：花轿几时到、鼓乐几时发、亲迎队伍走哪条街。","options":[{"text":"仪程列成时刻表","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你把仪程排成时辰表，精确到刻。媒婆道：「老婆子办过的婚礼，头一回有时刻账。」","source":"宋代亲迎仪程，见《东京梦华录》记婚俗。"},{"text":"全听媒婆安排","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"媒婆安排得妥帖，你还是拿笔记了一份——账房娘子，习惯了留底。","source":"同上。"}],"difficulty":2,"npc":["官媒婆"],"foreshadow":"亲迎仪程"},{"id":"A-071-未","branch":"A","stage":3,"day":71,"shichen":"未时","checkpoint":"婚前十日·五","scene":"未时，官家那边传来消息：他中秋宴上喝多了，扬言要在亲迎那日「拦轿验货」。街面上都听见了。","options":[{"text":"先知会坊正市吏","correct":true,"tags":["自主","家世"],"dims":{"自主":2,"家世":1},"feedback":"你请爹先知会坊正与市吏：亲迎日请人沿途照拂。先布好局，不怕他发酒疯。","source":"宋代街市治安之制，见《东京梦华录》。"},{"text":"他不敢真拦","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孙老爷听了却不放心，亲自去见了坊正。防患未然，总没错。","source":"同上。"}],"difficulty":3,"npc":["爹","孙老爷"],"foreshadow":"拦轿之忧"},{"id":"A-071-戌","branch":"A","stage":3,"day":71,"shichen":"戌时","checkpoint":"婚前十日·六","scene":"戌时，孙公子听闻拦轿之言，隔街喊你。你推窗。他道：「那日我走在轿前。谁敢拦，先拦我。」","options":[{"text":"不许你打架","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你道：「你的差事是把轿子接到家，不是打架——打架是坊正的活。」他咧嘴笑了。","source":"宋代亲迎之俗，见《东京梦华录》。"},{"text":"心里有底了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"关窗的时候，手是稳的。轿前有人，怕什么。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"轿前有人","flavor":true},{"id":"A-072","branch":"A","stage":3,"day":72,"shichen":"辰时","checkpoint":"婚前十日·七","scene":"七月廿八。婚前八日。你把联营的账做了一份「婚期托管册」：婚假三日，每日何人代班、何事可决、何事须候。","options":[{"text":"托管册两家各一","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"孙老爷看完道：「成亲三日，账目不乱——我家娶的不是媳妇，是总账房。」","source":"宋代商铺代管之记，见宋代笔记。"},{"text":"三日不管又如何","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"嘴上这么说，册子还是写了。三日不管账的滋味，你尝不了。","source":"同上。"}],"difficulty":2,"npc":["孙老爷"],"foreshadow":"托管册"},{"id":"A-072-未","branch":"A","stage":3,"day":72,"shichen":"未时","checkpoint":"婚前十日·八","scene":"未时，娘拉你坐下，做婚前最后一次「家底交底」：爹娘的积蓄、铺子的底账、家里的人情债——全摊给你看。","options":[{"text":"听完整整一个时辰","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"听完你才明白：爹娘这二十年，每一笔都是给你和弟弟攒的底气。","source":"宋代家产交底之记，见家训类书。"},{"text":"边听边记","correct":false,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"你记了一册「娘家总录」。娘道：「记它做什么？」你道：「娘家也是我的账。」","source":"同上。"}],"difficulty":2,"npc":["娘"],"foreshadow":"娘家总录"},{"id":"A-072-戌","branch":"A","stage":3,"day":72,"shichen":"戌时","checkpoint":"婚前十日·九","scene":"戌时，弟弟抱着他的学徒账来交作业。这个月，他只错了一处。","options":[{"text":"这月准他满分","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"他道：「阿姊放心嫁，铺子有我。」十二岁的人，说出了二十岁的口气。","source":"宋代家业承继之记，见家训类书。"},{"text":"请他吃蜜煎","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"姐弟俩分食一碟蜜煎。他忽然道：「阿姊，你嫁了我也会常去看你。」","source":"宋代果腹之记，见《东京梦华录》记蜜煎。"}],"difficulty":1,"npc":["弟弟"],"foreshadow":"弟弟长成","flavor":true},{"id":"A-073","branch":"A","stage":3,"day":73,"shichen":"辰时","checkpoint":"婚前七事","scene":"七月廿九。婚前七日。晨起你列「婚前七事」：试嫁衣、点奁产、核托管、见媒婆、写谢帖、理妆匣、睡好觉。","options":[{"text":"一日一件从容办","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"七日七事，一日一件。杏儿道：「别人家婚前鸡飞狗跳，咱家像打算盘——一是一二是二。」","source":"宋代婚前备办之记，见《东京梦华录》。"},{"text":"能赶的都赶完","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"赶了三日，人瘦了一圈。娘强令你一日只办一件：「新娘子要的是气色，不是速度。」","source":"同上。"}],"difficulty":1,"npc":["杏儿","娘"],"foreshadow":"婚前七事"},{"id":"A-073-未","branch":"A","stage":3,"day":73,"shichen":"未时","checkpoint":"婚前七事·二","scene":"未时，州桥的老书生送来写好的婚联。上联：「彩帛生药联佳偶」；下联：「账册同心记百年」。横批：「州桥第一家」。","options":[{"text":"好联厚谢","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":1,"情缘":1},"feedback":"你道：「先生这联，把两家的生意和我俩的日子都写进去了。」当场装裱。","source":"宋代婚联之雅，见宋代笔记。"},{"text":"横批要不要再想想","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"老书生道：「不改了——州桥第一家，说的是生意，也是这桩婚事。」","source":"同上。"}],"difficulty":1,"npc":["老书生"],"foreshadow":"婚联装裱","flavor":true},{"id":"A-073-戌","branch":"A","stage":3,"day":73,"shichen":"戌时","checkpoint":"婚前七事·三","scene":"戌时，你翻「心意账」，从第一页「相看」翻到最新一页「婚联」。三个月，这册子记满了。","options":[{"text":"这册带入洞房","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"箱笼再重，这册最轻也最重。它是你的及笄、你的心动、你的九十天。","source":"宋代闺阁笺记之习。"},{"text":"让杏儿收好","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"杏儿道：「姑娘，等你们金婚，拿出来念给孙少爷听。」你道：「五十年？记着的。」","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"心意账入嫁","flavor":true},{"id":"A-074","branch":"A","stage":3,"day":74,"shichen":"辰时","checkpoint":"亲迎前夜","scene":"八月初一。婚前最后一日。晨起见娘在你房门外站了很久——她一夜没睡好。","options":[{"text":"陪娘用早膳","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"一顿早膳吃了半个时辰。娘道：「明日你就是别人家的了。」你道：「明日我还是你的。」","source":"宋代嫁女之别，见闺阁记载。"},{"text":"给娘布菜","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"布了三筷子，娘的眼圈就红了。你赶紧讲了个铺里的笑话。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"亲迎在即","flavor":true},{"id":"A-074-未","branch":"A","stage":3,"day":74,"shichen":"未时","checkpoint":"亲迎前夜·二","scene":"未时，全家做最后点验：花轿、鼓乐、仪程、托管册、坊正回话——桩桩落实。爹道：「万事俱备。」","options":[{"text":"再谢全家一回","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"你郑重给爹娘福了一礼：「女儿这三个月，仗的是全家的底气。明日，女儿把体面带回来。」","source":"宋代婚前家礼之记，见家训类书。"},{"text":"谢字说不出口","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"说不出口，就写在账簿上：「八月初一，欠娘家恩情账一笔——此账用一生来还。」","source":"同上。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"万事俱备","flavor":true},{"id":"A-074-戌","branch":"A","stage":3,"day":74,"shichen":"戌时","checkpoint":"亲迎前夜·三","scene":"戌时，最后一夜。你坐在闺房里，对面生药铺的灯笼还亮着，「八月十六」四个字映进窗来。明日辰时，花轿到门。","options":[{"text":"写下待嫁最后一笔","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你写：「待嫁九十天。明日过门，带去的不是箱笼，是我这双手、这本账、这颗自己选的心。」","source":"宋代新妇前夜之记，见闺阁墨迹。"},{"text":"吹灯安睡","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"睡得很稳。账都清了，礼都备了，人都对了——明日的花轿，接的是一个准备好的新娘。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"花轿到门","flavor":true},{"id":"A-075","branch":"A","stage":3,"day":75,"shichen":"辰时","checkpoint":"亲迎日","scene":"八月初二·亲迎日（婚期提前半月，两家合意的吉时）。鼓乐到门，花轿落地。你凤冠霞帔，拜别爹娘。","options":[{"text":"三拜上轿","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"一拜天地，二拜高堂，三拜——转身。轿帘落下那一刻，你听见娘终于哭出了声。","source":"宋代亲迎之礼，见《东京梦华录》记婚俗。"},{"text":"回身抱了娘","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"礼数之外多抱了三息。媒婆没催——这三十年的媒，她懂。","source":"同上。"}],"difficulty":1,"npc":["爹","娘","官媒婆"],"foreshadow":"花轿起身","flavor":true},{"id":"A-075-未","branch":"A","stage":3,"day":75,"shichen":"未时","checkpoint":"亲迎日·二","scene":"未时，轿过州桥。那官家果然带了两个闲汉在桥头晃——坊正和市吏往那一站，他掂了掂，摇着扇子走了。","options":[{"text":"轿中微微一笑","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你在轿中听得明白。商户家的女儿出嫁，走的是明路，靠的是预备——他连拦的资格都没有。","source":"宋代街市婚仪之记，见《东京梦华录》。"},{"text":"揭帘看了一眼","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"轿帘掀起一线，你看见的是他退场的背影。这一页，翻篇了。","source":"同上。"}],"difficulty":1,"npc":["官家","坊正"],"foreshadow":"官家彻底退场","flavor":true},{"id":"A-075-戌","branch":"A","stage":3,"day":75,"shichen":"戌时","checkpoint":"洞房夜","scene":"戌时，洞房。盖头挑起，烛影里是他。他第一句不是吉祥话，是：「托管册我看过了，第三条写得不对——你婚假三日，我批五日。」","options":[{"text":"好，就五日","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"烛下两人都笑了。账房娘子的洞房第一课：原来这世上的账，往后都有人陪她一起算。","source":"宋代洞房之俗，见《东京梦华录》记婚俗。"},{"text":"五日照旧核账","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"他道：「行，我陪你核。」——这大概就是商户人家，最好的洞房花烛。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"洞房核账","flavor":true},{"id":"A-076","branch":"A","stage":4,"day":76,"shichen":"辰时","checkpoint":"新婚三日","scene":"八月初三。新婚第一日晨起，你陪孙夫人用早膳。她道：「新妇三日无大小，可我这有个规矩——新婚的，要核一回自家账。」","options":[{"text":"当场核起","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"一个时辰，孙家生药铺的月账核毕。孙夫人看完：「这媳妇，娶进了一尊活账神。」","source":"宋代新妇执事之记，见家训类书。"},{"text":"先问从何入手","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"孙夫人道：「从你最熟的入手。」你便从药材进出核起——正是联营摸过的路子。","source":"同上。"}],"difficulty":2,"npc":["孙夫人"],"foreshadow":"新妇核账"},{"id":"A-076-未","branch":"A","stage":4,"day":76,"shichen":"未时","checkpoint":"新婚三日·二","scene":"未时，核到账册深处，那笔挂了三年的陈账又撞进眼里——两百贯，欠款人：孙夫人的娘家侄儿。","options":[{"text":"暂不点破记自册","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你只在自己的小册上记了一笔。新婚三日就点婆家的烂账，不是立威，是结仇。","source":"宋代处世分寸之记，见宋代笔记。"},{"text":"当面问个明白","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"问了。孙夫人也不瞒：「我知道这笔账。我在等一个能收它的人。」——原来是考题。","source":"同上。"}],"difficulty":3,"npc":["孙夫人"],"foreshadow":"陈账考题"},{"id":"A-076-戌","branch":"A","stage":4,"day":76,"shichen":"戌时","checkpoint":"新婚三日·三","scene":"戌时，洞房安歇前，他递来一把钥匙：「咱屋里的箱柜，一人一把。你的箱，我不看；我的，你也别看——除了账。」","options":[{"text":"账一起管","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"你道：「箱柜各开各，账册同翻同。」他道：「成交。」——这就是你俩的婚约补充条款。","source":"宋代夫妻财分之记，见《名公书判清明集》。"},{"text":"钥匙串收好","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你的钥匙串又添一把。娘说的对：女人手里，要有自己开的锁。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"钥匙之约","flavor":true},{"id":"A-077","branch":"A","stage":4,"day":77,"shichen":"辰时","checkpoint":"回门","scene":"八月初四·回门日。新妇三朝回门。你携礼归宁，轿到自家铺前，弟弟率伙计们列队放炮。","options":[{"text":"先查他的账","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"炮还没放完你就坐到了柜前。三日账，弟弟记得清清楚楚——你只挑出一处错。","source":"宋代回门之俗，见《东京梦华录》。"},{"text":"先拜爹娘","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"拜完爹娘再查账。娘道：「嫁出去三日，回来头件事还是核账——是我闺女。」","source":"同上。"}],"difficulty":1,"npc":["弟弟","爹","娘"],"foreshadow":"回门查账","flavor":true},{"id":"A-077-未","branch":"A","stage":4,"day":77,"shichen":"未时","checkpoint":"回门·二","scene":"未时，娘家宴新婿。他陪爹喝酒，爹考他药材，他答得头头是道。爹醉了，拍着他肩膀说了三声「好」。","options":[{"text":"席间布菜斟茶","correct":true,"tags":["家世","情缘","感情"],"dims":{"家世":1,"情缘":1},"feedback":"娘在旁看着，忽然道：「你爹年轻时考校人从没这么松过——他是真满意。」","source":"宋代回门宴之俗。"},{"text":"听他们聊生意","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"翁婿俩从药材聊到江南商路，越聊越投机。你在旁边听得津津有味。","source":"同上。"}],"difficulty":1,"npc":["爹","孙公子","娘"],"foreshadow":"翁婿相得","flavor":true},{"id":"A-077-戌","branch":"A","stage":4,"day":77,"shichen":"戌时","checkpoint":"回门·三","scene":"戌时返家。轿过街市，你掀帘看自家铺子的灯，又看夫家铺子的灯——两盏灯之间，是你的一辈子。","options":[{"text":"记下回门账","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你在新册写：「八月初四，回门。娘家账清，婆家账明，我的账——两家人都在上面。」","source":"宋代归宁之记，见宋代笔记。"},{"text":"靠着他睡着了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"忙了三日，靠着他肩头就睡着了。他一路坐得笔直，没敢动。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"两家灯火","flavor":true},{"id":"A-078","branch":"A","stage":4,"day":78,"shichen":"辰时","checkpoint":"新婚掌事","scene":"八月初五。婚假毕，你正式在孙家生药铺理事。头一日，伙计们都在观望：这新少奶奶，是花瓶还是真账房？","options":[{"text":"先盘三月旧账","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"三日旧账半日盘清，还指出两处串户。老伙计们服了：「少奶奶这手，是州桥练出来的。」","source":"宋代商铺理事之记，见宋代笔记。"},{"text":"先认人再理事","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你花一日认全了人：姓名、年资、家中情形。第二日盘账，事半功倍。","source":"同上。"}],"difficulty":2,"npc":["伙计们"],"foreshadow":"新妇理事"},{"id":"A-078-未","branch":"A","stage":4,"day":78,"shichen":"未时","checkpoint":"新婚掌事·二","scene":"未时，二嫂来铺里，扭扭捏捏：「弟妹，我那陪嫁铺子，亏了两年了……能不能帮二嫂看看？」","options":[{"text":"三日帮她理账","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"理完账你找出症结：进货全凭掌柜一张嘴。你教她立「验货簿」。二嫂感激涕零。","source":"宋代妯娌相助之记，见家训类书。"},{"text":"荐老账房去教","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"老账房去了三日，回道：「二少奶奶的铺子，亏在人心不在账。」你记下，准备亲自去。","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"二嫂铺亏"},{"id":"A-078-戌","branch":"A","stage":4,"day":78,"shichen":"戌时","checkpoint":"新婚掌事·三","scene":"戌时，你在日记写：「过门三日，核了婆家的账、帮了二嫂的忙、回了娘家的门。原来『嫁进来』三个字，是这么忙的。」","options":[{"text":"忙并踏实","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"忙是真忙，踏实也是真踏实——这一家子的账目，从你手里过，就从你手里亮。","source":"宋代新妇自述之记，见闺阁墨迹。"},{"text":"他端来羹汤","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「账房娘子，歇手。」你道：「账房先生，添灯。」两人对着账，把羹分着喝了。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"新婚忙碌","flavor":true},{"id":"A-079","branch":"A","stage":4,"day":79,"shichen":"辰时","checkpoint":"联营升级","scene":"八月初六。两家合议：婚后联营升级——香囊、针囊、香帕之外，增开「药香帛巾」新线，秋冬应市。","options":[{"text":"新线章程我来立","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你立章程：帛巾用药香熏制、分三等定价、绣档供绣样。两家老爷只负责点头。","source":"宋代联营扩业之记，见宋代商书。"},{"text":"稳一季再说","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"孙老爷道：「节令不等人，秋冬就在眼前。」你被说服，章程连夜立了。","source":"宋代商谚。"}],"difficulty":2,"npc":["孙老爷","爹"],"foreshadow":"药香帛巾"},{"id":"A-079-未","branch":"A","stage":4,"day":79,"shichen":"未时","checkpoint":"联营升级·二","scene":"未时，你巡铺时撞见个生面孔——孙家三房的小叔子，支支吾吾在柜前转悠，想支银子去「做笔大买卖」。","options":[{"text":"无契不支一文","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你道：「柜上支银，要有老爷的押、夫人的准、契券的底。」他灰溜溜走了。规矩立住了。","source":"宋代商铺支银之规，见宋代笔记。"},{"text":"先支五贯试试","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"五贯支出去，当晚孙夫人就听说了。她没怪你，只说：「下回直接回他：柜上规矩大。」","source":"同上。"}],"difficulty":3,"npc":["小叔子"],"foreshadow":"三房隐患"},{"id":"A-079-戌","branch":"A","stage":4,"day":79,"shichen":"戌时","checkpoint":"联营升级·三","scene":"戌时，灯下核新线预算。他凑过来看你打算盘，忽然道：「白日你回绝三弟那一下，真利索。」","options":[{"text":"规矩就是规矩","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你道：「柜上的银子是大家的饭碗，不是谁的面子。」他道：「往后三房再缠，我替你挡。」","source":"宋代商铺规矩之记。"},{"text":"问他可会怪我","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他道：「怪你？我谢你还来不及。这个家就缺个敢说『不』的人。」","source":"同上。"}],"difficulty":2,"npc":["孙公子"],"foreshadow":"夫妻同心"},{"id":"A-080","branch":"A","stage":4,"day":80,"shichen":"辰时","checkpoint":"重阳备货","scene":"八月初七。翻《岁时广记》到重阳：登高、佩茱萸、饮菊酒——你眼睛一亮：茱萸香囊，不就是现成的买卖？","options":[{"text":"立重阳茱萸案","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你定案：茱萸囊、菊花帕、登高香巾，重阳三样齐上。孙老爷道：「这媳妇的脑子是个钱眼。」","source":"宋代重阳之俗与商卖，见《东京梦华录》。"},{"text":"只做茱萸一样","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"做一样太薄。你把「登高三样」凑齐，预售帖发出去，三日订了四百份。","source":"同上。"}],"difficulty":2,"npc":["孙老爷"],"foreshadow":"重阳三样"},{"id":"A-080-未","branch":"A","stage":4,"day":80,"shichen":"未时","checkpoint":"重阳备货·二","scene":"未时，娘家弟弟来送节礼，顺便交月账——他独立看柜一个月，流水还涨了一成。","options":[{"text":"夸他准他自主","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你道：「往后进货五贯以下，你自己拿主意。」他乐得蹦起来，又把账核了一遍才走。","source":"宋代家业承继之记，见家训类书。"},{"text":"细看每笔小账","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"细查了半日，只查出两处可省的小钱。你欣慰：这小子，出师了。","source":"同上。"}],"difficulty":2,"npc":["弟弟"],"foreshadow":"弟弟当家"},{"id":"A-080-戌","branch":"A","stage":4,"day":80,"shichen":"戌时","checkpoint":"重阳备货·三","scene":"戌时，孙夫人把你叫去，郑重交出一册钥匙：「这是库房和柜上的总钥匙。我掌了三十年——往后，你来。」","options":[{"text":"拜领总钥匙","correct":true,"tags":["家世","自主"],"dims":{"家世":2,"自主":1},"feedback":"你拜领。孙夫人道：「我不是老了，是放心了。」钥匙到手，你才真正是这家的当家人。","source":"宋代主妇传家之记，见家训类书。"},{"text":"推让不敢接","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"孙夫人把钥匙塞进你手里：「推什么？这家早晚是你的——晚给不如早给。」","source":"同上。"}],"difficulty":2,"npc":["孙夫人"],"foreshadow":"执掌中馈"},{"id":"A-081","branch":"A","stage":4,"day":81,"shichen":"辰时","checkpoint":"掌家首月","scene":"八月初八。执掌中馈第一日。你把孙家上下三十六口的月钱、衣料、节赏重新造册——旧册子十年没换过格式了。","options":[{"text":"四柱法重造新册","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"旧管、新收、开除、实在——一册在手，孙家一月的进出亮如白昼。下人们心服口服。","source":"宋代四柱清册之法，见宋代会计记载。"},{"text":"照旧册格式来","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"旧格式用了一旬，到底碍手。你还是换成了四柱法——好规矩不怕晚。","source":"同上。"}],"difficulty":2,"npc":["下人们"],"foreshadow":"掌家新册"},{"id":"A-081-未","branch":"A","stage":4,"day":81,"shichen":"未时","checkpoint":"掌家首月·二","scene":"未时，三房的小叔子又来了，这回绕开你直接找孙夫人，说要借钱贩马。孙夫人把他推到你面前：「问她。」","options":[{"text":"问明再做保人","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你问马源、问脚钱、问销路，问出三处破绽。他支吾半日走了。孙夫人道：「问得好。」","source":"宋代借贷之规，见《名公书判清明集》。"},{"text":"回绝不留余地","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"回是回了，话太硬。孙夫人教你：「回绝也要给他留台阶——一家里人，抬头不见低头见。」","source":"宋代家训之语。"}],"difficulty":3,"npc":["小叔子","孙夫人"],"foreshadow":"三房借贷"},{"id":"A-081-戌","branch":"A","stage":4,"day":81,"shichen":"戌时","checkpoint":"掌家首月·三","scene":"戌时，掌家头一日毕。他在灯下给你揉肩：「白日里看你问三弟那几条，我替他都捏汗。」","options":[{"text":"问清楚是护他","correct":true,"tags":["情缘","家世","感情"],"dims":{"情缘":1,"家世":1},"feedback":"你道：「真借给他贩马，才是害他。问明白，是护他口袋，也是护这家。」","source":"宋代家训之语。"},{"text":"笑他心疼弟弟","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他道：「我心疼的是账。」你道：「巧了，我也是。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"夫妻论家","flavor":true},{"id":"A-082","branch":"A","stage":4,"day":82,"shichen":"辰时","checkpoint":"重阳三样","scene":"八月初九·重阳。「登高三样」上市：茱萸囊、菊花帕、登高香巾，外加免费奉送的重阳糕签。州桥又排长队。","options":[{"text":"三样半日售罄","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"半日售罄。有老主顾道：「州桥家的节货，闭眼买都不错。」——招牌立住了。","source":"宋代重阳商卖之记，见《东京梦华录》。"},{"text":"加印一批应市","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"急加印一批，酉时赶到。这一日，联营的「州桥第一家」算是在汴京叫响了。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"四节四捷","flavor":true},{"id":"A-082-未","branch":"A","stage":4,"day":82,"shichen":"未时","checkpoint":"重阳三样·二","scene":"未时，全家登高。你与孙夫人并肩上高处，她忽然道：「我这辈子只登过三次高——出嫁前、生子时、今日。」","options":[{"text":"往后年年陪您登","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"孙夫人拍拍你的手：「我把家交给你，不是交担子，是交了个能陪我登高的人。」","source":"宋代重阳登高之俗，见《东京梦华录》。"},{"text":"静静陪着","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"高处风大，你替她拢了拢披风。她什么都没说，什么都没用说。","source":"同上。"}],"difficulty":1,"npc":["孙夫人"],"foreshadow":"婆媳知心","flavor":true},{"id":"A-082-戌","branch":"A","stage":4,"day":82,"shichen":"戌时","checkpoint":"重阳三样·三","scene":"戌时，重阳宴毕。你与他立在院中看月亮。他道：「成亲前我娘问我图你什么，我说——图她算账时眼睛里的光。」","options":[{"text":"那光还在吗","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"他看着你：「比那日还亮。」——这大约是你听过的，最不商户、也最动人的情话。","source":"宋代夫妻夜话之记，见话本。"},{"text":"低头笑","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"低头那一下，月光落在你发上。他在日记（对，他也被你带得记账了）里写：今日月好。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"眼中之光","flavor":true},{"id":"A-083","branch":"A","stage":4,"day":83,"shichen":"辰时","checkpoint":"江南商路","scene":"八月初十。那位江南客商再度登门——三节试销，他在江南卖疯了，这回带着真金白银来谈全年包销。","options":[{"text":"立全年契附三约","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你立契：货分四季、价随物议、次品包退。客商看完叹服：「与州桥家做买卖，睡得着觉。」","source":"宋代远程贩运契约之记，见《梦粱录》。"},{"text":"再加一成价","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"价加成了，客商也应了——但他在契后添了句「若滞销另议」。你记住：价到顶，余地就到头了。","source":"宋代商谚。"}],"difficulty":3,"npc":["江南客商"],"foreshadow":"江南契成"},{"id":"A-083-未","branch":"A","stage":4,"day":83,"shichen":"未时","checkpoint":"江南商路·二","scene":"未时，签契毕，客商随口一句：「夫人这般手段，可听说过杭州沈娘子？她一户女流，船队直通明州港。」","options":[{"text":"记下这个名字","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你在册页边写下「沈娘子·船队·明州」。原来这世道上，把生意做大的女子，不止你一个。","source":"宋代女商之记，见宋代笔记。"},{"text":"请客商细讲","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"听了半日。客商走后，你在日记写：「山外有山，账外有账。」","source":"同上。"}],"difficulty":2,"npc":["江南客商"],"foreshadow":"沈娘子传说"},{"id":"A-083-戌","branch":"A","stage":4,"day":83,"shichen":"戌时","checkpoint":"江南商路·三","scene":"戌时，两家设小宴庆江南契成。席间爹和孙老爷商量：要不要干脆合开一家「节令行」，由你总揽。","options":[{"text":"应下总揽之任","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"你道：「行可以开，章程我来立，两家股份对半，账目月月公验。」——总账房，升格了。","source":"宋代合伙开行之记，见宋代商书。"},{"text":"容我想三日","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"想了三日，你列了「开行十问」带去议事。孙老爷看完：「不用想了，就是你了。」","source":"同上。"}],"difficulty":3,"npc":["爹","孙老爷"],"foreshadow":"节令行议"},{"id":"A-084","branch":"A","stage":4,"day":84,"shichen":"辰时","checkpoint":"妯娌联手","scene":"八月十一。你帮二嫂理她陪嫁铺子的账理到深处——掌柜两年虚报了三百贯进货。人赃并获。","options":[{"text":"账对人退赃换人","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"你与二嫂唱红白脸：退赃、换人、立新规，一气呵成。二嫂道：「这间铺子，算是活过来了。」","source":"宋代查处虚账之记，见《名公书判清明集》。"},{"text":"送官究办","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"送官也成，但铺子名声就臭了。你改选「退赃私了」，既追了钱，又留了铺面体面。","source":"同上。"}],"difficulty":3,"npc":["二嫂","旧掌柜"],"foreshadow":"二嫂铺翻身"},{"id":"A-084-未","branch":"A","stage":4,"day":84,"shichen":"未时","checkpoint":"妯娌联手·二","scene":"未时，事了。二嫂拉着你：「弟妹，这铺子往后你说怎么管就怎么管——分你一成干股，不许推。」","options":[{"text":"股收下账照管","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"你道：「股我收，账我教你自己管——靠我一年，不如自己一世。」妯娌相视而笑。","source":"宋代妯娌相济之记，见家训类书。"},{"text":"谢她但不受","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"推了三回，二嫂急了：「你是不是嫌少？」你只好收了。情谊这东西，收也是给。","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"妯娌同心"},{"id":"A-084-戌","branch":"A","stage":4,"day":84,"shichen":"戌时","checkpoint":"妯娌联手·三","scene":"戌时，孙夫人听闻白日之事，把二嫂和你都叫到跟前：「你们妯娌能把日子过成相互搭把手，我老婆子就放心了。」","options":[{"text":"妯娌同谢婆母","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"孙夫人道：「家和不是没有账，是账账都有人认。」——这句话你记进了册子扉页。","source":"宋代家训之语。"},{"text":"请婆母放心","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"二嫂补了句：「往后谁欺负弟妹，先过我这关。」满堂大笑。","source":"同上。"}],"difficulty":1,"npc":["孙夫人","二嫂"],"foreshadow":"家和账明","flavor":true},{"id":"A-085","branch":"A","stage":4,"day":85,"shichen":"辰时","checkpoint":"成婚满月","scene":"八月十二。成婚满月。晨起对镜，杏儿为你梳的已是妇人发髻。她道：「姑娘……不，少奶奶，满月了。」","options":[{"text":"满月盘点","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你在新册写：「满月。掌家一册、联营一契、商路一条、妯娌一心。这媳妇，当得不亏。」","source":"宋代满月之记，见婚俗记载。"},{"text":"还是叫姑娘吧","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"杏儿笑道：「屋里叫姑娘，外头叫少奶奶。」就这么定了。","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"满月盘点","flavor":true},{"id":"A-085-未","branch":"A","stage":4,"day":85,"shichen":"未时","checkpoint":"成婚满月·二","scene":"未时，你回娘家送满月饼。弟弟拉着你报喜：铺子这月又涨了半成，他已经开始学看市易谱了。","options":[{"text":"娘家也日日新","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"爹道：「你嫁出去一个月，这铺子非但没散，还更精神了——你教出来的好弟弟。」","source":"宋代家业承继之记。"},{"text":"带他核一处错","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"核出一处小错，他记下来改了。姐弟对账的时辰，比什么满月礼都亲。","source":"同上。"}],"difficulty":1,"npc":["弟弟","爹"],"foreshadow":"娘家日新","flavor":true},{"id":"A-085-戌","branch":"A","stage":4,"day":85,"shichen":"戌时","checkpoint":"成婚满月·三","scene":"戌时，满月夜。他神神秘秘从袖里掏出一张纸——他把这一个月你俩的「心意账」整理成了对账联单。","options":[{"text":"联单钉进册中","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"上联你记，下联他续。从此这本账，两个人一起写——这就是日子。","source":"宋代夫妻笺记之雅，见宋代笔记。"},{"text":"笑他东施效颦","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「近朱者赤，近账房者——会算账。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"心意联单","flavor":true},{"id":"A-086","branch":"A","stage":4,"day":86,"shichen":"辰时","checkpoint":"节令行筹备","scene":"八月十三。「节令行」筹备开工：选址州桥南首，两间门面。你画铺面图——前店后坊，坊里容得下二十个绣娘。","options":[{"text":"前店后坊最顺手","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"前店迎客，后坊赶工，账房居中——你画的格局，两家老爷挑不出一处毛病。","source":"宋代商铺格局之记，见《东京梦华录》。"},{"text":"坊放城外省钱","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"省下的租钱不够贴脚钱。你算了笔账，还是自己说服了自己。","source":"同上。"}],"difficulty":2,"npc":["孙老爷","爹"],"foreshadow":"节令行铺面"},{"id":"A-086-未","branch":"A","stage":4,"day":86,"shichen":"未时","checkpoint":"节令行筹备·二","scene":"未时，给新行起名。爹要叫「孙李联行」，孙老爷要叫「州桥总行」，你执笔写下三个字。","options":[{"text":"就叫岁时行","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"「岁时行」——岁岁有时，节节有货。老书生抚掌：「好名字，不俗不滥，还压得住场。」","source":"宋代行铺命名之记，见《东京梦华录》。"},{"text":"两姓各取一字","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"「孙李行」念着拗口。孙老爷摆手：「听媳妇的，岁时行！」","source":"同上。"}],"difficulty":2,"npc":["爹","孙老爷","老书生"],"foreshadow":"岁时行"},{"id":"A-086-戌","branch":"A","stage":4,"day":86,"shichen":"戌时","checkpoint":"节令行筹备·三","scene":"戌时，你在账簿新开一册，封面写「岁时行·立」。第一页只有一行字：「开张之日，腊月之前。」","options":[{"text":"写下开张总纲","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"总纲三条：货精、账明、人稳。三条写完，你心里那间铺子，已经开张了。","source":"宋代开行总纲之记，见宋代商书。"},{"text":"合册睡个好觉","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"梦里有间大铺子，柜上坐着你自己。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"岁时行总纲","flavor":true},{"id":"A-087","branch":"A","stage":4,"day":87,"shichen":"辰时","checkpoint":"三房风波","scene":"八月十四。三房小叔子贩马的事发了——他借了印子钱，马没贩成，债滚到了八十贯，债主堵了孙家的门。","options":[{"text":"先验债契真伪","correct":true,"tags":["才华","家世"],"dims":{"才华":2,"家世":1},"feedback":"你验契：利息过了律条的红线。你请坊正作证，只还本与律内息——债主理亏，了事。","source":"宋代印子钱之禁，见《宋刑统》与《名公书判清明集》。"},{"text":"全还了买清净","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"钱是还了，全家看你的眼神都急了。孙夫人道：「妇道人家掌家，第一要会说不。」","source":"同上。"}],"difficulty":3,"npc":["小叔子","债主","坊正"],"foreshadow":"印子钱了结"},{"id":"A-087-未","branch":"A","stage":4,"day":87,"shichen":"未时","checkpoint":"三房风波·二","scene":"未时，事了。小叔子跪在厅上，孙老爷气得发抖。轮到你这当家的发落。","options":[{"text":"罚他柜上学徒","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"你道：「钱债还了，人债自己挣——明日起柜上学徒三年，月钱抵债。」孙老爷点头：「这比打一顿强。」","source":"宋代家规之记，见家训类书。"},{"text":"家法打二十","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"打了也解气，但人还是废的。你补了一句「学徒三年」，才算有了出路。","source":"同上。"}],"difficulty":3,"npc":["小叔子","孙老爷"],"foreshadow":"三房学徒"},{"id":"A-087-戌","branch":"A","stage":4,"day":87,"shichen":"戌时","checkpoint":"三房风波·三","scene":"戌时，他在灯下道：「今日全家都看着你怎么发落三弟——你没让我难做，也没让他没路走。」","options":[{"text":"当家不是当刀","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"你道：「掌家掌的是日子，不是威风。他走的是正路，这家才不散。」","source":"宋代家训之语。"},{"text":"其实手在抖","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他握住你的手：「抖着也把事办了，这才是当家人。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"当家立威","flavor":true},{"id":"A-088","branch":"A","stage":4,"day":88,"shichen":"辰时","checkpoint":"岁时行立号","scene":"八月十五·中秋。「岁时行」挂牌！匾额是老书生题的，联是「彩帛生药联佳偶，账册同心记百年」——州桥半城来贺。","options":[{"text":"开张三样谢客","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"茱萸囊、菊花帕、团圆巾三样谢客价，开张半日流水抵旧铺一月。","source":"宋代开市之俗，见《东京梦华录》。"},{"text":"先请坊正市吏","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"官面人物请到，契券过档——行开得正，路才走得长。","source":"同上。"}],"difficulty":1,"npc":["老书生","坊正"],"foreshadow":"岁时行开张","flavor":true},{"id":"A-088-未","branch":"A","stage":4,"day":88,"shichen":"未时","checkpoint":"岁时行立号·二","scene":"未时，贺客里有位不速之客——杭州沈娘子遣人送来贺礼：一面小旗，旗上绣「明州」二字，附帖：「江南道上，愿与岁时行互通有无。」","options":[{"text":"收旗回帖结盟","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你回帖：「汴京岁时，江南明州——货通南北，账信为先。」南北两位女当家，隔江握手。","source":"宋代南北商路之记，见《梦粱录》。"},{"text":"先查清底细","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"查了十日，底细干净。只是这十日里，别人家的货已走了一趟明州。","source":"同上。"}],"difficulty":2,"npc":["沈娘子信使"],"foreshadow":"南北结盟"},{"id":"A-088-戌","branch":"A","stage":4,"day":88,"shichen":"戌时","checkpoint":"岁时行立号·三","scene":"戌时，中秋夜。去年此夜你还隔着街看他的灯笼，今年此夜，你们并肩站在自家行的匾额下看月。","options":[{"text":"匾额下立愿","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"你道：「这行是你我成亲后立的头一份家业——愿岁岁有今日。」他道：「账为凭，月为证。」","source":"宋代中秋赏月之俗，见《梦粱录》。"},{"text":"把这一刻记下","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"联单上添一笔：「中秋，岁时行立。月满，人满，账满。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"岁时立愿","flavor":true},{"id":"A-089","branch":"A","stage":4,"day":89,"shichen":"辰时","checkpoint":"行务上轨","scene":"八月十六。岁时行开张次日，你排定行务：绣档归王嫂、药香归孙家师傅、账房归你、外联归——他想了想，归他。","options":[{"text":"各司其职立岗","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"岗位一贴，人人有名有责。王嫂道：「跟着姑娘……不，行主，有奔头。」","source":"宋代行铺分工之记，见《东京梦华录》。"},{"text":"都先听你调遣","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"调了三日，你累得嗓子哑。他心疼：「把岗分出去，你只管账。」你听了他的。","source":"同上。"}],"difficulty":2,"npc":["王嫂","孙公子"],"foreshadow":"行务定岗"},{"id":"A-089-未","branch":"A","stage":4,"day":89,"shichen":"未时","checkpoint":"行务上轨·二","scene":"未时，二嫂把她的铺子也并进来入了股——「我那铺子空着也是空着，给岁时行当西厢分号。」","options":[{"text":"立契入股分号","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"契一立，岁时行有了分号。二嫂道：「我这股，是跟着弟妹挣前程。」","source":"宋代入伙分号之记，见宋代商书。"},{"text":"劝她再想想","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"二嫂道：「想清楚了——跟着会算账的人，错不了。」契还是立了。","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"西厢分号"},{"id":"A-089-戌","branch":"A","stage":4,"day":89,"shichen":"戌时","checkpoint":"行务上轨·三","scene":"戌时，你核行务首日报表，看到最后一行笑了——他在「外联」栏下添了一行小字：「兼管给账房娘子添灯。」","options":[{"text":"批了「准」字","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"报表上朱笔一批：准。这大概是岁时行头一份你批得最痛快的文书。","source":"宋代夫妻谐趣之记，见话本。"},{"text":"也添一行","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你添：「账房娘子兼管给外联先生留门。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"报表情话","flavor":true},{"id":"A-090","branch":"A","stage":4,"day":90,"shichen":"辰时","checkpoint":"重阳后盘账","scene":"八月十七。岁时行首旬盘账：流水超两家旧铺总和。你把数字报给两家老爷，厅上静了三息，然后笑声掀了屋顶。","options":[{"text":"利分四股章程","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你定章程：本金、分红、滚存、义仓四股分立。孙老爷道：「义仓这股——你比我们想得远。」","source":"宋代商号分利之记，见宋代商书。"},{"text":"全数分红利","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"分得痛快，但爹提了一句「年成有丰歉」，你把滚存和义仓补进了章程。","source":"同上。"}],"difficulty":2,"npc":["爹","孙老爷"],"foreshadow":"四股章程"},{"id":"A-090-未","branch":"A","stage":4,"day":90,"shichen":"未时","checkpoint":"重阳后盘账·二","scene":"未时，你用义仓的头一笔钱，给绣娘和伙计们加了冬衣钱。消息传开，州桥的手艺人都在打听岁时行还收不收人。","options":[{"text":"立招工规矩","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"你立规：手艺分档、工钱公道、年节有赏。三日内，好手艺人来了一半州桥。","source":"宋代雇工之规，见《东京梦华录》。"},{"text":"人手够了不收","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"不收也可惜。你留了本「候用名录」——人才这东西，宁可备而不用。","source":"同上。"}],"difficulty":2,"npc":["绣娘们","伙计们"],"foreshadow":"候用名录"},{"id":"A-090-戌","branch":"A","stage":4,"day":90,"shichen":"戌时","checkpoint":"重阳后盘账·三","scene":"戌时，夜深人静。你翻着三册账——娘家总录、岁时行总册、心意联单。成婚一个月，你把两家人写成了一家人。","options":[{"text":"写下满月行务","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你写：「行主满月。商户女到孙家妇，我没丢一样东西——账、股、名字、还有他。」","source":"宋代闺阁自省之记。"},{"text":"合册吹灯","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"吹灯前他替你收好账册：「明日还长。」是啊，来日方长。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"行主满月","flavor":true},{"id":"A-091","branch":"A","stage":4,"day":91,"shichen":"辰时","checkpoint":"南北首航","scene":"八月十八。岁时行首批南货发船：重阳余货加冬令新品，发往明州，走沈娘子的水路。装船那日，你亲自押单到码头。","options":[{"text":"单货三验再放行","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"货单、货色、货数三验。押船的伙计道：「有夫人这关，船翻不了。」","source":"宋代漕运发货之记，见《梦粱录》。"},{"text":"信沈娘子那边","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"信归信，验归验。你还是验了——盟是盟，账是账。","source":"宋代商谚。"}],"difficulty":2,"npc":["押船伙计"],"foreshadow":"南货首航"},{"id":"A-091-未","branch":"A","stage":4,"day":91,"shichen":"未时","checkpoint":"南北首航·二","scene":"未时回行，撞见三房小叔子在柜上打算盘——学徒十日，指法居然有模有样。他见你，手一抖。","options":[{"text":"看他打的账","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"一页日账，错了一处，自己用红笔圈了。你道：「会自查了。照这样，三年出师有望。」","source":"宋代学徒之记，见宋代笔记。"},{"text":"不动声色走过","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你走过去了，他反而更慌。晚上你让师傅带句话：「打得不赖。」","source":"同上。"}],"difficulty":2,"npc":["小叔子"],"foreshadow":"三房改过"},{"id":"A-091-戌","branch":"A","stage":4,"day":91,"shichen":"戌时","checkpoint":"南北首航·三","scene":"戌时，他核完外联账回来，给你带了码头买的江蟹：「南货下了水，北蟹上了桌——今日双喜。」","options":[{"text":"对蟹分账","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"蟹八只，一人四只，谁也不许多吃——连分蟹都要对账的两口子，全汴京也就这一家。","source":"宋代食蟹之俗，见《东京梦华录》。"},{"text":"让他多吃一只","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他把蟹黄都拨给你：「外联的跑码头，账房的费眼睛——你补。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"码头之喜","flavor":true},{"id":"A-092","branch":"A","stage":4,"day":92,"shichen":"辰时","checkpoint":"冬令备货","scene":"八月十九。翻《岁时广记》到冬令：立冬补冬、冬至亚岁——你定冬令三样：补冬香膏、消寒帕、九九消寒图。","options":[{"text":"消寒图请书生画","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"九九八十一瓣梅，日染一瓣过冬寒。老书生画稿一出，预订帖雪片般来。","source":"宋代九九消寒之俗，见《东京梦华录》。"},{"text":"只做香膏省事","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"单做一样利润薄。你还是把三样凑齐——岁时行的规矩，过节就成套。","source":"同上。"}],"difficulty":2,"npc":["老书生"],"foreshadow":"冬令三样"},{"id":"A-092-未","branch":"A","stage":4,"day":92,"shichen":"未时","checkpoint":"冬令备货·二","scene":"未时，娘家传来喜讯：弟弟独立谈成了第一笔外埠生意——洛阳的帛商主动找上门。","options":[{"text":"写信贺他","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你回信只八个字：「契要过官，价要让一。」——做生意的贺词，就是这么朴实。","source":"宋代家书信札之记。"},{"text":"请他来行里学","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他回：「阿姊的行是阿姊的，我的铺是我的。」这小子，翅膀硬得让人欣慰。","source":"同上。"}],"difficulty":2,"npc":["弟弟"],"foreshadow":"洛阳商路"},{"id":"A-092-戌","branch":"A","stage":4,"day":92,"shichen":"戌时","checkpoint":"冬令备货·三","scene":"戌时，孙夫人把你叫到上房，交给你一只描金小匣：「这是我当年的体己，如今给你——不为别的，为你让这家越来越像样。」","options":[{"text":"拜领入私册","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"匣中是一支老凤钗。孙夫人道：「戴不戴随你——它是『这个家认你』的意思。」","source":"宋代传家赠钗之记，见宋代笔记。"},{"text":"请婆母留着","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"孙夫人把匣一合：「给你的就是你的。推来让去，是外道。」","source":"同上。"}],"difficulty":2,"npc":["孙夫人"],"foreshadow":"老凤钗"},{"id":"A-093","branch":"A","stage":4,"day":93,"shichen":"辰时","checkpoint":"行会刁难","scene":"八月二十。帛行会忽然递话：岁时行「未入行会、不得挂行字号」。又是那套行规压人的把戏。","options":[{"text":"持契对簿行会","correct":true,"tags":["自主","才华"],"dims":{"自主":2,"才华":1},"feedback":"你请市吏作中，当面验明：岁时行是「联号」非「窜行」，契券齐全。行会讨个没脸。","source":"宋代行会之制与讼争，见《名公书判清明集》。"},{"text":"入行会交份子","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"份子交了，气咽不下。他道：「这口气咱不受——明日我陪你去市吏那说清楚。」","source":"同上。"}],"difficulty":3,"npc":["行会执事","市吏"],"foreshadow":"行会积怨"},{"id":"A-093-未","branch":"A","stage":4,"day":93,"shichen":"未时","checkpoint":"行会刁难·二","scene":"未时，对簿回来，二嫂气得直骂。你却坐下来翻行会的旧档——查它这几年收了谁的份子、办过什么事。","options":[{"text":"记下它的软肋","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"三日查清：行会份子十之七八进了执事私囊。这账先记着——不是不报，时候未到。","source":"宋代行会积弊之记，见宋代笔记。"},{"text":"暂且记下这口气","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"气记下了，档也查了。你学的：商户的武器不是拳头，是账本。","source":"同上。"}],"difficulty":3,"npc":["二嫂"],"foreshadow":"行会黑账"},{"id":"A-093-戌","branch":"A","stage":4,"day":93,"shichen":"戌时","checkpoint":"行会刁难·三","scene":"戌时，他见你翻旧档翻到深夜，默默给你换了盏亮灯：「查账伤眼，骂街省力——可惜咱家只会前者。」","options":[{"text":"骂街赢不了账","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"你道：「行会欺行霸市靠人多，咱靠的是纸上有字。」他点头：「我给你研墨。」","source":"宋代商户自处之语，见宋代笔记。"},{"text":"笑他油嘴","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"笑归笑，墨研得极好。这一夜，账查明了三条，墨用完了两锭。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"灯下查档","flavor":true},{"id":"A-094","branch":"A","stage":4,"day":94,"shichen":"辰时","checkpoint":"南货回信","scene":"八月廿一。明州回信到了——沈娘子亲笔：首航南货三日售罄，加价三成还供不应求，问下一批何时发。","options":[{"text":"即排二批发船","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"你回书附下一季货单。信末添一句：「江南若过汴京，州桥岁时行扫榻。」","source":"宋代南北商路之记，见《梦粱录》。"},{"text":"提价再发","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"价提了一成，信里你写明缘由。沈娘子回一字：「直。」——南北两个账房，对上脾气了。","source":"同上。"}],"difficulty":2,"npc":["沈娘子"],"foreshadow":"南北神交"},{"id":"A-094-未","branch":"A","stage":4,"day":94,"shichen":"未时","checkpoint":"南货回信·二","scene":"未时，杏儿兴冲冲进来：「少奶奶，街上都在传，岁时行是『汴京媳妇开的行』，说您及笄五个月就当上行主了！」","options":[{"text":"传言听一半","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你道：「传的只是热闹，账上的数才是真的。」——但你还是让杏儿把传言学了三遍。","source":"宋代市井口碑之记，见宋代笔记。"},{"text":"纠正「是两家」","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"你正色：「是两家的行，一城的福气。」话传出去，州桥人更敬你三分。","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"行主之名","flavor":true},{"id":"A-094-戌","branch":"A","stage":4,"day":94,"shichen":"戌时","checkpoint":"南货回信·三","scene":"戌时，你在联单上写今日事。他凑过来看，在你那句「南北两个账房对上脾气」旁边添了句：「东边这个账房，吃味了。」","options":[{"text":"批「不许」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"朱笔一批：「不许。」他道：「准了添灯，不准吃味——这家的章程，向着你。」","source":"宋代夫妻谐趣之记，见话本。"},{"text":"画了个小醋坛","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"账簿上的画技依旧拙劣，但他看懂了，笑了半宿。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"联单笑谈","flavor":true},{"id":"A-095","branch":"A","stage":4,"day":95,"shichen":"辰时","checkpoint":"寒衣节","scene":"八月廿二。晨起核账，你注意到行里两个老伙计家中清寒。你翻章程——义仓股，正是为这个时候设的。","options":[{"text":"义仓支寒衣钱","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"寒衣钱按例发放，不多不少，不声不张。老伙计们红了眼眶：「这行，是家。」","source":"宋代商号恤下之记，见宋代笔记。"},{"text":"私下补贴","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"私补暖心，却坏规矩。你改走义仓——恩出公账，暖得长久。","source":"同上。"}],"difficulty":2,"npc":["老伙计们"],"foreshadow":"义仓初用"},{"id":"A-095-未","branch":"A","stage":4,"day":95,"shichen":"未时","checkpoint":"寒衣节·二","scene":"未时，孙夫人偶感风寒。你停了半日账，亲自煎药侍奉——药是你亲手验的，火候是你亲手看的。","options":[{"text":"亲奉汤药三日","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"孙夫人病中拉着你道：「儿媳做到这份上，是孙家修来的。」你道：「娘待我，本是亲的。」","source":"宋代孝养之记，见家训类书。"},{"text":"请郎中细心看","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"郎中看了，药也请了，你还是夜夜自己验一遍药渣——专业这东西，用在孝心上也顺手。","source":"同上。"}],"difficulty":2,"npc":["孙夫人"],"foreshadow":"婆媳至亲"},{"id":"A-095-戌","branch":"A","stage":4,"day":95,"shichen":"戌时","checkpoint":"寒衣节·三","scene":"戌时，婆母睡下。你回房，他已把行里的日报核完，还留了字条：「娘有你，我有你，这家两头都稳。」","options":[{"text":"添一句回他","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你添：「稳是因为你也在。」——纸条压在砚台下，明日他研墨时会看见。","source":"宋代夫妻书笺之雅。"},{"text":"把字条收进册","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"字条入册，编了号。心意账第七十三笔：他的。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"纸条入册","flavor":true},{"id":"A-096","branch":"A","stage":4,"day":96,"shichen":"辰时","checkpoint":"冬至亚岁","scene":"冬至前一日。汴京最重冬至，谓之亚岁。岁时行「冬令三样」开卖：补冬香膏、消寒帕、九九消寒图，铺前排出长队。","options":[{"text":"三样成套卖","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"成套、单买、预定三档并挂，半日破千件。州桥人道：过节就等岁时行。","source":"宋代冬至亚岁之俗，见《东京梦华录》。"},{"text":"拆开零卖","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"零卖也俏，成套的招牌却弱了。你当晚改回——节货卖的是「全乎」。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"冬令三样大卖"},{"id":"A-096-未","branch":"A","stage":4,"day":96,"shichen":"未时","checkpoint":"冬至亚岁·二","scene":"未时，邻行连夜仿了消寒图低价抛售。伙计们急了，请你拿主意。","options":[{"text":"加染金梅不降价","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"你出「金蕊消寒图」附染梅签。仿品三日滞销——仿得来形，仿不来心。","source":"宋代市集竞卖之记，见宋代笔记。"},{"text":"降价跟着打","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"价一降，老主顾反倒疑心货色。你急回原价，贴了句「岁时行不欺人」。","source":"同上。"}],"difficulty":3,"npc":["伙计们"],"foreshadow":"仿品来犯"},{"id":"A-096-戌","branch":"A","stage":4,"day":96,"shichen":"戌时","checkpoint":"冬至亚岁·三","scene":"戌时盘账，冬令三样一日流水抵旧年一季。他在报表角上画了一枝梅：「明日染第一瓣。」","options":[{"text":"研梅同染","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"九九第一瓣，你们一人染一半。消寒图挂进账房，寒天也暖。","source":"宋代九九消寒之俗，见宋代笔记。"},{"text":"记一笔梅开","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"联单添笔：「冬至前夜，梅始染，账始肥。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"染梅之约","flavor":true},{"id":"A-097","branch":"A","stage":4,"day":97,"shichen":"辰时","checkpoint":"亚岁贺冬","scene":"冬至日·亚岁。汴京人家更易新衣、备办饮食、享祀先祖，一如年节。你率全家拜贺。","options":[{"text":"拜冬如拜年","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"孙夫人受拜时眼圈红了：「往年冬至冷冷清清，今年像个年了。」","source":"宋代冬至亚岁之记，见《东京梦华录》。"},{"text":"先去铺里看看","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"铺子去了，拜也拜了，只是迟了一刻。孙夫人笑道：「家里也有账。」","source":"同上。"}],"difficulty":1,"npc":["孙夫人","孙老爷"],"foreshadow":"亚岁如年"},{"id":"A-097-未","branch":"A","stage":4,"day":97,"shichen":"未时","checkpoint":"亚岁贺冬·二","scene":"未时，伙计绣娘们来贺冬。你按义仓章程，给每人发「亚岁节赏」，外加一日假。","options":[{"text":"节赏加假一日","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"王嫂道：「外头行铺过年才歇，咱行冬至就歇——跟对人了。」","source":"宋代节假之制，见《东京梦华录》。"},{"text":"赏钱不给假","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"钱赏了，人没歇成，热闹淡了一半。你记下：明年赏假并给。","source":"同上。"}],"difficulty":2,"npc":["王嫂","伙计们"],"foreshadow":"亚岁节赏"},{"id":"A-097-戌","branch":"A","stage":4,"day":97,"shichen":"戌时","checkpoint":"亚岁贺冬·三","scene":"戌时，全家围炉吃馄饨——汴京冬至食馄饨。他给你舀的那碗，底下埋着颗蜜饯。","options":[{"text":"蜜饯分他一半","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一人一半。孙夫人看着直笑：「这俩孩子，吃馄饨都要对半分。」","source":"宋代冬至食馄饨之俗，见宋代笔记。"},{"text":"把碗推给他","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他不吃，又推回来。一碗馄饨推了三回，凉了也甜。","source":"同上。"}],"difficulty":1,"npc":["孙夫人","孙公子"],"foreshadow":"馄饨蜜饯","flavor":true},{"id":"A-098","branch":"A","stage":4,"day":98,"shichen":"辰时","checkpoint":"备腊","scene":"冬至过，腊月近。你翻《岁时广记》：腊八、腊祭、年货——岁时行一年最重的一仗要来了。","options":[{"text":"立腊月三案","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你定三案：腊八粥料包、腊味香囊、年货成套。帖发出去，各行铺还没醒过神。","source":"宋代腊俗之记，见《东京梦华录》。"},{"text":"等别家先动","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"等了三日，别家都在看岁时行。你懂了：如今你是风向标，得先出牌。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"腊月三案"},{"id":"A-098-未","branch":"A","stage":4,"day":98,"shichen":"未时","checkpoint":"备腊·二","scene":"未时，沈娘子来信：江南腊货——福橘、冬笋、糖霜——可赶腊八前到汴京，问你要多少。","options":[{"text":"照单全收加倍","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"南北头一回合办腊八。你回信：照单全收，再加一倍——这单成了，联盟就实了。","source":"宋代南北货殖之记，见《梦粱录》。"},{"text":"先要一半试水","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"一半也订了。信末你添了句「若俏，腊中再补」——留了活口。","source":"同上。"}],"difficulty":2,"npc":["沈娘子"],"foreshadow":"南北合腊"},{"id":"A-098-戌","branch":"A","stage":4,"day":98,"shichen":"戌时","checkpoint":"备腊·三","scene":"戌时，你把腊货预算给他看。他看完只说：「这一仗打完，岁时行就不是州桥的岁时行了。」","options":[{"text":"是南北的","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你道：「不，是南北的。」他点头：「那我是南北账房的家眷。」","source":"宋代商路之记，见宋代笔记。"},{"text":"还没敢想那远","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"他道：「我想了。你只管算账，远处的灯，我替你挂。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"南北之志","flavor":true},{"id":"A-099","branch":"A","stage":4,"day":99,"shichen":"辰时","checkpoint":"腊八日","scene":"腊月初八。岁时行门前支锅施腊八粥——义仓出的米，绣娘们烧的火，排队的半条街。","options":[{"text":"施粥兼卖料包","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"喝粥的念好，买料包的回家自熬。一善一利，两不相妨——这是你定的章程。","source":"宋代腊八施粥之俗，见《梦粱录》。"},{"text":"只施不卖","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"纯施一日，米去不少。他提醒：料包照卖，施粥才施得长久。你听进去了。","source":"同上。"}],"difficulty":2,"npc":["绣娘们"],"foreshadow":"腊八施粥"},{"id":"A-099-未","branch":"A","stage":4,"day":99,"shichen":"未时","checkpoint":"腊八日·二","scene":"未时，沈娘子的腊货船到了。福橘入施粥锅，糖霜入料包——南北合办的腊八，全城独一份。","options":[{"text":"南货入粥更香","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"加了福橘的腊八粥香了一条街。有老人道：「七十岁，头回喝江南味的腊八。」","source":"宋代腊八粥之记，见《梦粱录》。"},{"text":"南货另柜卖","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"另柜也俏，只是可惜了那锅粥。你记下：明年南北合熬。","source":"同上。"}],"difficulty":2,"npc":["沈娘子信使"],"foreshadow":"福橘入粥"},{"id":"A-099-戌","branch":"A","stage":4,"day":99,"shichen":"戌时","checkpoint":"腊八日·三","scene":"戌时施粥收锅，你和他最后喝的两碗是锅底刮的。孙夫人遣人送来姜汤：「两个傻子，忙一天喝锅底。」","options":[{"text":"锅底的最浓","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你道：「腊八粥，锅底最浓。」他道：「日子也是。」","source":"宋代腊八粥之记，见宋代笔记。"},{"text":"喝姜汤暖胃","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"姜汤是孙夫人亲手煨的。这家的暖，从婆母灶台一路传到你碗里。","source":"同上。"}],"difficulty":1,"npc":["孙公子","孙夫人"],"foreshadow":"锅底之甜","flavor":true},{"id":"A-100","branch":"A","stage":4,"day":100,"shichen":"辰时","checkpoint":"年货大战","scene":"腊月十五，年货大战开打。行会旗下三大行联手压价，要把岁时行挤出年货市。","options":[{"text":"不打价战打样战","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你挂出「年货全套三十六样」——别家拼价，你拼全乎。价钱没动，客流来了。","source":"宋代岁终商卖之记，见《东京梦华录》。"},{"text":"跟着降价迎战","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"降了一日，利薄如纸。你急收：岁时行的底气是货，不是贱。","source":"同上。"}],"difficulty":3,"npc":["行会执事"],"foreshadow":"大战开幕"},{"id":"A-100-未","branch":"A","stage":4,"day":100,"shichen":"未时","checkpoint":"年货大战·二","scene":"未时，三大行买通脚夫，岁时行的年货运不进州桥。你看着堵在巷口的车队。","options":[{"text":"雇船队绕水路","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你走水路！沈娘子教的航道派上用场。脚夫堵着空巷口，货已从码头进了行。","source":"宋代漕运之便，见《梦粱录》。"},{"text":"报官请市吏断","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"市吏来了，脚夫散了，半日耽误了。你记住：官可请，路要自己多备一条。","source":"同上。"}],"difficulty":3,"npc":["脚夫","市吏"],"foreshadow":"水路破局"},{"id":"A-100-戌","branch":"A","stage":4,"day":100,"shichen":"戌时","checkpoint":"年货大战·三","scene":"戌时，你盘大战首日账，累趴在案上。他给你盖斗篷，顺手把账核完了——错的只有两处。","options":[{"text":"两处他标好了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"醒来见账上朱笔两圈，旁注：「娘子辛苦，为夫代劳。」","source":"宋代夫妻相得之记，见话本。"},{"text":"他学得真快","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一年前他连算盘都认不全，如今能替你核年货账。这徒弟，是你自己教的。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"代劳之账","flavor":true},{"id":"A-101","branch":"A","stage":4,"day":101,"shichen":"辰时","checkpoint":"年货决胜","scene":"腊月十六。三大行压价压到亏本，开始以次充好。有主顾拿着别家劣货来问：岁时行怎么也这样？","options":[{"text":"当众验货辨伪","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"你在铺前当众验：岁时行的货有暗记、有单号。劣货现形，三大行招牌砸了一半。","source":"宋代货殖诚信之记，见宋代笔记。"},{"text":"贴告示澄清","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"告示不如当众验货有力。你补了一场「验货会」，才算洗干净。","source":"同上。"}],"difficulty":3,"npc":["老主顾"],"foreshadow":"验货辨伪"},{"id":"A-101-未","branch":"A","stage":4,"day":101,"shichen":"未时","checkpoint":"年货决胜·二","scene":"未时，大战定局：岁时行流水占州桥年货市四成。三大行派人来递话求和。","options":[{"text":"和可以账照记","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你道：「和，可以；市价各归各，下作手段的账，记着。」行会那边坐不住了。","source":"宋代商争和息之记，见《名公书判清明集》。"},{"text":"乘胜再压一城","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"孙老爷劝你：穷寇莫追，生意场留一线。你想了一夜，听了。","source":"宋代商谚。"}],"difficulty":3,"npc":["三大行使者","孙老爷"],"foreshadow":"求和之门"},{"id":"A-101-戌","branch":"A","stage":4,"day":101,"shichen":"戌时","checkpoint":"年货决胜·三","scene":"戌时，大战初胜。他温了酒：「去年这时候，你还是个及笄后学认秤的姑娘。」","options":[{"text":"认秤手握一城","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你举杯：「认秤的手，如今握一城年货。」他道：「我敬这双手。」","source":"宋代岁终宴饮之俗，见宋代笔记。"},{"text":"多亏你在","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他摇头：「我在，是添灯的。仗是你打的。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"敬这双手","flavor":true},{"id":"A-102","branch":"A","stage":4,"day":102,"shichen":"辰时","checkpoint":"黑账上门","scene":"腊月十七。行会执事亲自登门，皮笑肉不笑：「岁时行年货占道、施粥聚众——按行规，该罚。」","options":[{"text":"请他验契验档","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你请出市吏过档的契券、坊正的施粥批文：「罚之前，先验哪条真犯。」执事噎住。","source":"宋代行户争讼之记，见《名公书判清明集》。"},{"text":"破财消灾认罚","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"罚银交了，他气笑：「今日怎么软了？」你道：「先看看他敢收多少。」——也是一探。","source":"同上。"}],"difficulty":3,"npc":["行会执事"],"foreshadow":"执事登门"},{"id":"A-102-未","branch":"A","stage":4,"day":102,"shichen":"未时","checkpoint":"黑账上门·二","scene":"未时，你取出那册记了四个月的行会黑账：份子十之七八入私囊，笔笔有日有数有证人。","options":[{"text":"复核到无懈","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你请二嫂和老账房分头复核，笔笔坐实。这账不拿去害人——拿去过堂，一笔就够。","source":"宋代账证之制，见《名公书判清明集》。"},{"text":"直接捅到市吏","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"急了点。你压下性子先复核——打蛇打七寸，账本要无懈可击。","source":"同上。"}],"difficulty":3,"npc":["二嫂","老账房"],"foreshadow":"黑账复核"},{"id":"A-102-戌","branch":"A","stage":4,"day":102,"shichen":"戌时","checkpoint":"黑账上门·三","scene":"戌时，孙夫人见你灯下核黑账，叹道：「我掌家三十年，行会的气也受了三十年。你要动它？」","options":[{"text":"不是动是算清","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你道：「娘，我不动它，我让它把自己的账算清。」孙夫人默然良久：「去，孙家兜底。」","source":"宋代家训之语。"},{"text":"媳妇有分寸","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"孙夫人拍拍你：「我信你。这家交你手里，连仇都报得体面。」","source":"同上。"}],"difficulty":2,"npc":["孙夫人"],"foreshadow":"婆母允战","flavor":true},{"id":"A-103","branch":"A","stage":4,"day":103,"shichen":"辰时","checkpoint":"黑账了断","scene":"腊月十八。你请市吏、坊正、各行行首齐聚帛行会公所——不当众撕，只当众「对账」。","options":[{"text":"对账不对人","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你摊开两册：行会收支册、黑账册。「诸位对一对，差在哪。」满座哑然，执事面如死灰。","source":"宋代公对簿书之记，见《名公书判清明集》。"},{"text":"直指执事私囊","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"指名道姓太狠，反惹得各行自危。你收住口，只让账说话——账比话狠。","source":"同上。"}],"difficulty":3,"npc":["行会执事","市吏","坊正"],"foreshadow":"公所对账"},{"id":"A-103-未","branch":"A","stage":4,"day":103,"shichen":"未时","checkpoint":"黑账了断·二","scene":"未时，对账毕：份子亏空三百余贯，笔笔清楚。各行公议：执事退赃去位，行会改选，份子新规公示。","options":[{"text":"留一线不送官","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"市吏问究不究，你道：「赃退了，位让了，规矩立了——够了。」满座行首朝你长揖。","source":"宋代和息之判，见《名公书判清明集》。"},{"text":"坚持送官究办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"送官也成，但各行从此怕你防你。孙老爷道：「你留的这一线，是给岁时行留的路。」","source":"同上。"}],"difficulty":3,"npc":["市吏","各行行首"],"foreshadow":"了断留线"},{"id":"A-103-戌","branch":"A","stage":4,"day":103,"shichen":"戌时","checkpoint":"黑账了断·三","scene":"戌时，事了回家。他在门口等你，手里提着灯：「黑账娘子，凯旋了？」","options":[{"text":"账赢人不伤","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你道：「账赢的，人没伤。」他点头：「这就是你比他们都强的地方。」","source":"宋代处世之语，见宋代笔记。"},{"text":"往后没人敢欺","correct":true,"tags":["名声"],"dims":{"名声":1},"feedback":"他道：「不是不敢，是不忍——你给人留体面，人给你留敬。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"凯旋之灯","flavor":true},{"id":"A-104","branch":"A","stage":4,"day":104,"shichen":"辰时","checkpoint":"岁末盘账","scene":"腊月十九。岁末大盘账：岁时行四股清册——本金、分红、滚存、义仓，一年进出，笔笔见底。","options":[{"text":"四柱法岁结","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"旧管新收开除实在，四册合一。爹看完说了句：「我闺女这账，能进书。」","source":"宋代四柱清册岁结之记，见宋代会计记载。"},{"text":"请老账房复核","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"复核三日，只挑出一处笔误。老账房服气：「少奶奶的账，复核是走过场。」","source":"同上。"}],"difficulty":2,"npc":["爹","老账房"],"foreshadow":"四股岁结"},{"id":"A-104-未","branch":"A","stage":4,"day":104,"shichen":"未时","checkpoint":"岁末盘账·二","scene":"未时，分红。伙计绣娘按股领红，义仓留足，滚存加厚。弟弟的铺子红单也送到了。","options":[{"text":"红利按章程分","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"章程早立，分得干净。没人争没人怨——规矩先行的好处，岁末最见真章。","source":"宋代商号分红之记，见宋代商书。"},{"text":"多分伙计一些","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"多分了，人心暖了，章程乱了。你补了句「下不为例」，回头修订赏格。","source":"同上。"}],"difficulty":2,"npc":["伙计们","绣娘们"],"foreshadow":"岁末分红"},{"id":"A-104-戌","branch":"A","stage":4,"day":104,"shichen":"戌时","checkpoint":"岁末盘账·三","scene":"戌时，两家人同吃岁终宴。爹和孙老爷喝到微醺，争着说是自己先相中的你。","options":[{"text":"我相中这日子","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"满桌静了一瞬，笑声掀了屋顶。他接话：「是我先挂的灯笼。」","source":"宋代岁宴之俗，见宋代笔记。"},{"text":"两家都有眼光","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"一句话敬了四位老人。娘在旁抹眼泪：「值了。」","source":"同上。"}],"difficulty":1,"npc":["爹","孙老爷","孙公子"],"foreshadow":"岁宴相争","flavor":true},{"id":"A-105","branch":"A","stage":4,"day":105,"shichen":"辰时","checkpoint":"岁末回望","scene":"腊月二十。你在总册写岁末盘点：岁时行立号数月，南北商路一条，黑账了断一桩，家人平安。","options":[{"text":"四笔写成一页","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"一页写完，你停笔——及笄至今百余日，商户女到行主，路是账铺出来的。","source":"宋代岁首自省之记，见宋代笔记。"},{"text":"翻回第一页看","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"第一页是及笄那日的三钱银子。如今看，像看别人的事。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"岁末一页"},{"id":"A-105-未","branch":"A","stage":4,"day":105,"shichen":"未时","checkpoint":"岁末回望·二","scene":"未时，杏儿来报：街上说书的已在讲「州桥女行主」的话段，把你讲成了传奇。","options":[{"text":"传奇不如账真","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"你去听了一回，讲得玄乎。回来在日记写：「他们讲传奇，我过日子。」","source":"宋代说话之俗，见宋代笔记。"},{"text":"让他也去听听","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"他听完回来学给你听，添油加醋，两人笑作一团。","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"说书传奇"},{"id":"A-105-戌","branch":"A","stage":4,"day":105,"shichen":"戌时","checkpoint":"岁末回望·三","scene":"戌时，一年的账都合上了。他忽然道：「算起来，再过一个来月，就是咱们成婚整一年了。」你笔一顿。","options":[{"text":"册上圈了那日","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你圈出来日，旁注：「一年为期，心意账要盘总账了。」他凑过来看，笑了。","source":"宋代夫妇周见之记，见宋代笔记。"},{"text":"问他想要什么","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「想要你把这一年的账，念给我听一遍。」——这算什么礼？这是他的礼。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"周年将至","flavor":true},{"id":"A-106","branch":"A","stage":5,"day":106,"shichen":"辰时","checkpoint":"新正开市","scene":"正月初一。新正首日，岁时行按俗「开正」：贴新历、发利市、挂新匾联——「岁岁常欢愉，账账皆明白」。","options":[{"text":"开正三事齐行","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"利市发下，伙计们齐声贺：「行主新正大吉！」汴京新年头一笔彩头，是岁时行的。","source":"宋代正旦开市之俗，见《东京梦华录》。"},{"text":"先放假三日","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"假放了，开正礼也没落。你明白：礼数这东西，是人心不是排场。","source":"同上。"}],"difficulty":1,"npc":["伙计们"],"foreshadow":"新正开正"},{"id":"A-106-未","branch":"A","stage":5,"day":106,"shichen":"未时","checkpoint":"新正开市·二","scene":"未时，各行行首登门拜正——去年还刁难你的行会，如今新执事带头来贺。","options":[{"text":"以礼还礼","correct":true,"tags":["名声"],"dims":{"名声":2},"feedback":"你备回礼：每家一份「新正三样」。恩怨翻篇，生意常新。","source":"宋代拜正之俗，见《梦粱录》。"},{"text":"提去年旧事","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你只笑不答。二嫂事后道：「不答，才是最狠的回敬。」","source":"同上。"}],"difficulty":2,"npc":["行会新执事","二嫂"],"foreshadow":"拜正翻篇"},{"id":"A-106-戌","branch":"A","stage":5,"day":106,"shichen":"戌时","checkpoint":"新正开市·三","scene":"戌时，新年第一夜。你们在院中守岁火，他把旧年最后一页联单揭下，新册翻开。","options":[{"text":"新册第一笔","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你写：「新册启，旧人在。」他补：「旧人新账，岁岁相续。」","source":"宋代守岁之俗，见《东京梦华录》。"},{"text":"共写一个吉字","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一个字两人写，他扶着你的手。开年第一笔，歪一点也吉利。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"新册启封","flavor":true},{"id":"A-107","branch":"A","stage":5,"day":107,"shichen":"辰时","checkpoint":"新正归宁","scene":"正月初二，归宁日。你携他回娘家拜正，娘的铺子新正也开了市——弟弟一个人支应得滴水不漏。","options":[{"text":"姐弟对新年账","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"新正三日账一笔不差。你合账：「往后不查了。」弟弟急了：「查是看得起我！」","source":"宋代归宁之俗，见宋代笔记。"},{"text":"先吃娘的羹","correct":false,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"娘煨了一夜的羹，你喝了两碗。家的规矩：先暖胃，再暖账。","source":"同上。"}],"difficulty":1,"npc":["弟弟","娘"],"foreshadow":"归宁核账"},{"id":"A-107-未","branch":"A","stage":5,"day":107,"shichen":"未时","checkpoint":"新正归宁·二","scene":"未时，爹娘拉着你俩看宅后的园子——爹说想把园子修一修，开春两家人一处踏青。","options":[{"text":"园子两家同修","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你道：「园子修大些，够两家人逛。」孙老爷听说，也要出一半料钱。","source":"宋代宅园之记，见宋代笔记。"},{"text":"出全资孝敬","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"爹不收全资：「两家人的园子，一家出钱算什么。」你改了主意。","source":"同上。"}],"difficulty":2,"npc":["爹","娘","孙老爷"],"foreshadow":"两家修园"},{"id":"A-107-戌","branch":"A","stage":5,"day":107,"shichen":"戌时","checkpoint":"新正归宁·三","scene":"戌时返家，街上新正灯影未散。他道：「初二归宁都这么热闹，等周年那日，不知要怎样。」","options":[{"text":"周年点两家灯","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你道：「周年那日，把两家的灯笼都点起来。」他记下：「此话为凭。」","source":"宋代灯夕之俗，见宋代笔记。"},{"text":"先贺新正","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「有你，日日是新年。」——这情话，越来越不害臊了。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"灯影归途","flavor":true},{"id":"A-108","branch":"A","stage":5,"day":108,"shichen":"辰时","checkpoint":"上元备灯","scene":"正月初十，上元将近。汴京灯山开搭，岁时行备「上元三样」：灯彩帕、灯谜签、走马灯。","options":[{"text":"灯谜藏商号","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你的谜面是账房切口，谜底是岁时行字号，猜中送灯——灯谜成了活招牌。","source":"宋代上元灯市之记，见《东京梦华录》。"},{"text":"只卖灯就好","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"灯卖得好，谜签却让别家抢了风头。你记下：明年补上。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"上元三样"},{"id":"A-108-未","branch":"A","stage":5,"day":108,"shichen":"未时","checkpoint":"上元备灯·二","scene":"未时，沈娘子来信：江南灯船北上，上元夜泊州桥码头——「南北同灯，共贺上元」。","options":[{"text":"码头设南北灯","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"你回信定下灯位：汴灯南灯并挂一桥。这一夜，州桥要看南北合璧。","source":"宋代灯船之记，见《梦粱录》。"},{"text":"请她行家作客","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"信请了，灯位也留了，你还加派了最好的客房。","source":"同上。"}],"difficulty":2,"npc":["沈娘子"],"foreshadow":"南北同灯"},{"id":"A-108-戌","branch":"A","stage":5,"day":108,"shichen":"戌时","checkpoint":"上元备灯·三","scene":"戌时，他抱回一盏小灯：「还记得吗？那年你的灯笼上挂着婚期——如今我年年给你挂。」","options":[{"text":"婚期灯年年挂","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你道：「往后每年上元，婚期都挂上灯。」这盏灯，从提亲挂到白头。","source":"宋代上元张灯之俗，见《东京梦华录》。"},{"text":"灯上添一笔","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你在灯上写：「宣和初年，嫁与挂灯人。」他说这是收到的最好的字。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"婚期灯","flavor":true},{"id":"A-109","branch":"A","stage":5,"day":109,"shichen":"辰时","checkpoint":"上元灯市","scene":"正月十五·上元。州桥灯如白昼，南北灯并挂，岁时行的「上元三样」半个时辰售罄。","options":[{"text":"灯市大卖","correct":true,"tags":["名声","才华"],"dims":{"名声":1,"才华":1},"feedback":"灯彩帕断货三回。童谣当街唱：「过元宵，三件事——看灯、猜谜、岁时行。」","source":"宋代元宵灯市之盛，见《东京梦华录》。"},{"text":"留灯送孤寡","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"义仓出的灯送进孤老院。满城灯火，一盏也没落下孤老的窗台。","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"南北灯市","flavor":true},{"id":"A-109-未","branch":"A","stage":5,"day":109,"shichen":"未时","checkpoint":"上元灯市·二","scene":"未时，沈娘子登岸——南北两位女当家，在灯下头一回见面，执手看了半晌。","options":[{"text":"灯下互验账本","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"她道：「信里见字如面，今日见账如见心。」你道：「南北两册账，对上了。」","source":"宋代商盟之记，见宋代笔记。"},{"text":"先敬她三杯","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"酒敬三杯，话谈半夜。她说：「汴京有你，江南有我——成了。」","source":"同上。"}],"difficulty":2,"npc":["沈娘子"],"foreshadow":"双姝初见"},{"id":"A-109-戌","branch":"A","stage":5,"day":109,"shichen":"戌时","checkpoint":"上元灯市·三","scene":"戌时，人潮里他牵住你：「去年灯市你还在桥那头看摊，今年的灯市，是你办的。」","options":[{"text":"走到桥这头","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":1,"自主":1},"feedback":"你道：「桥那头到桥这头，走了一百多天。」他道：「每一步我都陪着。」","source":"宋代元夕游观之俗，见宋代笔记。"},{"text":"看灯不说话","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"灯影里站了许久。千言万语，不如并肩。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"灯市并肩","flavor":true},{"id":"A-110","branch":"A","stage":5,"day":110,"shichen":"辰时","checkpoint":"岁时行周岁","scene":"正月十六。灯市收了，你翻岁时行总册——自立号至今，流水翻了三倍，行里上下五十二人。","options":[{"text":"立周岁总册","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"你为行立「周岁册」：货路、人路、钱路、心路四目——行的第一份年谱。","source":"宋代商号岁计之记，见宋代商书。"},{"text":"请众人合议","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"合议半日，人人道不易。你把众人的话，也记进了册。","source":"同上。"}],"difficulty":2,"npc":[],"foreshadow":"周岁总册"},{"id":"A-110-未","branch":"A","stage":5,"day":110,"shichen":"未时","checkpoint":"岁时行周岁·二","scene":"未时，你盘点行里的「人」：王嫂管绣档、二嫂管分号、三房小叔子学徒将满、弟弟独当一面。","options":[{"text":"人比账值钱","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"你在册末写：「岁时行最厚的一笔资产，不在架上，在人上。」","source":"宋代家训之语。"},{"text":"给众人画前程","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你挨个谈话：谁出师、谁掌档、谁学新艺。画完前程，人心更定。","source":"同上。"}],"difficulty":2,"npc":["王嫂","二嫂"],"foreshadow":"人上一笔"},{"id":"A-110-戌","branch":"A","stage":5,"day":110,"shichen":"戌时","checkpoint":"岁时行周岁·三","scene":"戌时，他问你周岁册最重哪一笔。你翻到中秋立号那夜给他看——「月满，人满，账满」。","options":[{"text":"是这一笔","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「那夜我记的是：匾额下，她立愿，我立志。」两册一对，同一个月亮。","source":"宋代夫妇笺记之雅，见宋代笔记。"},{"text":"笔笔都是日子","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"你道：「账无轻重，笔笔是日子。」他道：「那本联单也是。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"最重一笔","flavor":true},{"id":"A-111","branch":"A","stage":5,"day":111,"shichen":"辰时","checkpoint":"沈娘子入京","scene":"正月十七。沈娘子正式登门岁时行，带的礼是一只船模：「南北航路，往后月月有船。」","options":[{"text":"船模供正堂","correct":true,"tags":["名声","自主"],"dims":{"名声":1,"自主":1},"feedback":"船模供在正堂，下书「货通南北，信立朝夕」。来客都要看上一眼。","source":"宋代海舶之记，见《梦粱录》。"},{"text":"回赠商路图","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你回赠手绘汴京商路图。她收起道：「这是比金子贵的礼。」","source":"同上。"}],"difficulty":2,"npc":["沈娘子"],"foreshadow":"船模之礼"},{"id":"A-111-未","branch":"A","stage":5,"day":111,"shichen":"未时","checkpoint":"沈娘子入京·二","scene":"未时，两位女当家对坐深谈：不再只是互通有无，要共设「南北岁时联号」。","options":[{"text":"联号共立规矩","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你立三条：货互检、账互验、人互信。沈娘子添第四条：「姐妹互助，不设防。」","source":"宋代合伙盟约之记，见宋代商书。"},{"text":"先试一年再定","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"沈娘子笑：「谨慎是对的。一年为期，今日先签草约。」","source":"同上。"}],"difficulty":3,"npc":["沈娘子"],"foreshadow":"联号之议"},{"id":"A-111-戌","branch":"A","stage":5,"day":111,"shichen":"戌时","checkpoint":"沈娘子入京·三","scene":"戌时，家宴待沈娘子。她席间问你：「外头都道女子掌行难，你难吗？」你看了一眼添灯的他。","options":[{"text":"难但有人添灯","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"你道：「难。但我的灯，夜夜有人添。」沈娘子默然，举杯敬你们俩。","source":"宋代女商自述之记，见宋代笔记。"},{"text":"账不难人心难","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"她深有同感：「账目清爽，人心难算。」你道：「所以要把人心也算进账。」","source":"同上。"}],"difficulty":1,"npc":["沈娘子","孙公子"],"foreshadow":"添灯之答","flavor":true},{"id":"A-112","branch":"A","stage":5,"day":112,"shichen":"辰时","checkpoint":"南北联单","scene":"正月十八。南北联号立契，市吏过档。汴京岁时行、明州沈氏船行，一纸契约连成一线。","options":[{"text":"契成南北一线","correct":true,"tags":["才华","名声"],"dims":{"才华":1,"名声":1},"feedback":"契成之日，州桥商户都来道贺。新执事道：「夫人这一笔，写进了汴京商史。」","source":"宋代商契过档之制，见《名公书判清明集》。"},{"text":"设宴广邀同行","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"宴开三十席。沈娘子道：「北方的场面，比我们江南还热。」","source":"同上。"}],"difficulty":2,"npc":["沈娘子","市吏"],"foreshadow":"联号立契"},{"id":"A-112-未","branch":"A","stage":5,"day":112,"shichen":"未时","checkpoint":"南北联单·二","scene":"未时，联号第一单定案：春令三样南北同发——汴京出香药绣件，明州出海货糖霜。","options":[{"text":"春令南北同发","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"你排定船期车期，南北同月上市。这一单成了，联号就立住了。","source":"宋代南北货殖之记，见《梦粱录》。"},{"text":"先小单试水","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"试水也稳。沈娘子欣赏你的稳：「我们这种人，胆大心细。」","source":"同上。"}],"difficulty":2,"npc":["沈娘子"],"foreshadow":"联号首单"},{"id":"A-112-戌","branch":"A","stage":5,"day":112,"shichen":"戌时","checkpoint":"南北联单·三","scene":"戌时，联号账册新启。你在首页写两行，他过来看：上联「汴京岁时行」，下联「明州沈氏船」。","options":[{"text":"横批一个信字","correct":true,"tags":["名声","情缘","感情"],"dims":{"名声":1,"情缘":1},"feedback":"你落横批：信。他道：「南北三千里，就靠这一个字。」","source":"宋代商信之记，见宋代笔记。"},{"text":"请他题横批","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他提笔写「同心」。南北联的是你和他的，也是天下的。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"联单横批","flavor":true},{"id":"A-113","branch":"A","stage":5,"day":113,"shichen":"辰时","checkpoint":"郊园团圆","scene":"正月十九。两家合修的园子落成。开春第一日，两家人齐入园——爹和孙老爷钓鱼，娘和孙夫人赏花。","options":[{"text":"园中设团圆宴","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"宴设水榭。四位老人、弟弟、二嫂、小叔子——一张大桌，坐满了一家人。","source":"宋代园林宴集之记，见宋代笔记。"},{"text":"先给园子立账","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"他笑你团圆日还想着账。你道：「园子的账立了，团圆才长久。」","source":"同上。"}],"difficulty":1,"npc":["爹","孙老爷","孙夫人","娘"],"foreshadow":"水榭团圆"},{"id":"A-113-未","branch":"A","stage":5,"day":113,"shichen":"未时","checkpoint":"郊园团圆·二","scene":"未时，园中猜枚行令。弟弟和小叔子比算盘，绣娘学徒们比针脚，满园笑声。","options":[{"text":"你来当评判","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"算盘弟弟快半子，针脚学徒胜一线。彩头是岁时行新样——自家人的体面。","source":"宋代宴集游戏之记，见宋代笔记。"},{"text":"陪娘说说话","correct":false,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"娘拉着你的手：「看你如今，娘梦里都笑醒。」","source":"同上。"}],"difficulty":1,"npc":["弟弟","小叔子","娘"],"foreshadow":"园中赛艺"},{"id":"A-113-戌","branch":"A","stage":5,"day":113,"shichen":"戌时","checkpoint":"郊园团圆·三","scene":"戌时，园灯初上，两家人不散，围炉夜话。爹说起你小时候偷学算盘的事，满座大笑。","options":[{"text":"那算盘还在","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你道：「那把小算盘我带到了夫家——它是我的嫁妆头一件。」","source":"宋代家训之语。"},{"text":"敬爹一杯","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"爹一饮而尽：「这辈子最得意的一笔买卖，是养了个会算账的闺女。」","source":"同上。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"偷学算盘","flavor":true},{"id":"A-114","branch":"A","stage":5,"day":114,"shichen":"辰时","checkpoint":"团圆夜话","scene":"正月二十。团圆次日，孙夫人与娘在园中散步成了惯例——两亲家如今好得像老姐妹。","options":[{"text":"两家亲如一家","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"孙夫人道：「从前怕娶媳妇多个外人，如今是多了半个闺女外加一门亲。」","source":"宋代亲家往还之记，见宋代笔记。"},{"text":"给二位立茶约","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"二位老人自定了「逢五茶会」。你乐见其成。","source":"同上。"}],"difficulty":1,"npc":["孙夫人","娘"],"foreshadow":"亲家茶会"},{"id":"A-114-未","branch":"A","stage":5,"day":114,"shichen":"未时","checkpoint":"团圆夜话·二","scene":"未时，二嫂拉你密谈：她想把分号的章程学全，往后自己也能带学徒。","options":[{"text":"倾囊相授","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"你道：「妯娌之间无秘方。」章程、账式、验货簿，三日教全。二嫂红了眼眶。","source":"宋代妯娌相授之记，见家训类书。"},{"text":"让她先管一月","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"管了一月，她自己找上门：「弟妹，还是教我吧，靠自己腰杆硬。」","source":"同上。"}],"difficulty":2,"npc":["二嫂"],"foreshadow":"妯娌授业"},{"id":"A-114-戌","branch":"A","stage":5,"day":114,"shichen":"戌时","checkpoint":"团圆夜话·三","scene":"戌时，园灯熄了，两家人各自归家。他道：「看出来了吗？今日娘和咱娘，穿的是你做的同色褙子。」","options":[{"text":"一样料一样心","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你道：「一样料，一样工，一样心——两位娘，不分彼此。」","source":"宋代孝养之记，见家训类书。"},{"text":"难怪都那么美","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「你也美。」——灯都熄了，这话黑着说，格外大胆。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"同色褙子","flavor":true},{"id":"A-115","branch":"A","stage":5,"day":115,"shichen":"辰时","checkpoint":"学徒出师","scene":"正月廿一。岁时行绣档首批学徒期满出师。你设出师试：绣样、定价、待客三关。","options":[{"text":"三关严考放行","correct":true,"tags":["才华"],"dims":{"才华":2},"feedback":"十二人考，过九人。出师帖你亲笔写：「艺成于岁时，德行于天下。」","source":"宋代师徒之制，见宋代笔记。"},{"text":"全部放行","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"全放了，倒显得门槛浅。你补了复试，三人留级——规矩护的是含金量。","source":"同上。"}],"difficulty":2,"npc":["学徒们"],"foreshadow":"出师三关"},{"id":"A-115-未","branch":"A","stage":5,"day":115,"shichen":"未时","checkpoint":"学徒出师·二","scene":"未时，出师宴上，王嫂哭成泪人：「这些丫头进来是生手，出去是师傅——行主，功德无量。」","options":[{"text":"功在她们自己","correct":true,"tags":["名声","家世"],"dims":{"名声":1,"家世":1},"feedback":"你举杯：「手艺是她们熬出来的，岁时行只是点了灯。」——和你家那盏灯，一个道理。","source":"宋代师道之记，见宋代笔记。"},{"text":"收下心意匾","correct":false,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"学徒们凑钱打了面小匾「授业恩人」。你挂在账房，天天看得见。","source":"同上。"}],"difficulty":2,"npc":["王嫂","学徒们"],"foreshadow":"授业恩人"},{"id":"A-115-戌","branch":"A","stage":5,"day":115,"shichen":"戌时","checkpoint":"学徒出师·三","scene":"戌时，出师宴散。他道：「今日看你署名『岁时行主』，忽然觉得你站在那儿，像一棵树。」","options":[{"text":"树是你栽的","correct":true,"tags":["自主","情缘","感情"],"dims":{"自主":1,"情缘":1},"feedback":"他摇头：「不，是你自己长的，我浇过水而已。」","source":"宋代夫妇相敬之记，见话本。"},{"text":"树下有你","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"树要成林，林中有他。这话没说出口，他懂了。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"行主如树","flavor":true},{"id":"A-116","branch":"A","stage":5,"day":116,"shichen":"辰时","checkpoint":"弟弟立号","scene":"正月廿二。弟弟的铺子正式立号分铺——洛阳商路走通了，他要开第二间，来请阿姊验章程。","options":[{"text":"逐条验他章程","correct":true,"tags":["才华","家世"],"dims":{"才华":1,"家世":1},"feedback":"你验了半日，只改两处。弟弟道：「阿姊改的这两处，值一间铺。」","source":"宋代立铺章程之记，见宋代商书。"},{"text":"全信他不验","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"信归信，你还是验了——姐姐的爱，是最后一道把关。","source":"同上。"}],"difficulty":2,"npc":["弟弟"],"foreshadow":"洛阳分铺"},{"id":"A-116-未","branch":"A","stage":5,"day":116,"shichen":"未时","checkpoint":"弟弟立号·二","scene":"未时，弟弟忽然红了脸：洛阳帛商家有位小娘子，彼此有意，想请阿姊拿个主意。","options":[{"text":"先验人品家底","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你道：「你的章程我验，你的亲事更要验。」弟弟笑：「就知道阿姊这么说。」","source":"宋代议亲之记，见宋代笔记。"},{"text":"你喜欢就好","correct":false,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"弟弟道：「喜欢归喜欢，阿姊的眼我要借。」——这小子，学你学了个十足。","source":"同上。"}],"difficulty":2,"npc":["弟弟"],"foreshadow":"弟弟议亲"},{"id":"A-116-戌","branch":"A","stage":5,"day":116,"shichen":"戌时","checkpoint":"弟弟立号·三","scene":"戌时，你跟他说弟弟的亲事。他听完问：「当年你验我的时候，也这么严吗？」","options":[{"text":"你验得更严","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你道：「验你的卷子，我出了三道。」他道：「幸好我满分。」","source":"宋代议亲之雅，见宋代笔记。"},{"text":"你是免验的","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你道：「把婚期挂上灯笼的人，不用验。」他愣了半晌，眼圈红了。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"免验之人","flavor":true},{"id":"A-117","branch":"A","stage":5,"day":117,"shichen":"辰时","checkpoint":"三房自立","scene":"正月廿三。三房小叔子学徒期满，交来自立呈：想领一笔本钱，走洛阳—汴京的脚商路。","options":[{"text":"准呈附三约","correct":true,"tags":["家世","自主"],"dims":{"家世":1,"自主":1},"feedback":"你准了，附三约：账月报、本保息、不走偏门。他双手接过：「嫂子，不再让你失望。」","source":"宋代学徒自立之记，见家训类书。"},{"text":"留在行里当差","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"他却道：「我想出去闯。闯出来，是岁时行的脸面。」你准了。","source":"同上。"}],"difficulty":2,"npc":["小叔子"],"foreshadow":"自立三约"},{"id":"A-117-未","branch":"A","stage":5,"day":117,"shichen":"未时","checkpoint":"三房自立·二","scene":"未时，他来辞行，一揖到地：「当年我堵门支银，嫂子没给一文——那一文不值的教训，救了我。」","options":[{"text":"扶他起来","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"你扶他：「一家人不说谢。你站稳了，就是还了。」孙老爷在旁，老泪纵横。","source":"宋代家族敦睦之记，见家训类书。"},{"text":"赠他新算盘","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你赠他一把新算盘：「带上它，走哪算哪，算清楚就不吃亏。」","source":"同上。"}],"difficulty":2,"npc":["小叔子","孙老爷"],"foreshadow":"辞行一揖"},{"id":"A-117-戌","branch":"A","stage":5,"day":117,"shichen":"戌时","checkpoint":"三房自立·三","scene":"戌时，孙老爷亲自来你房中道谢：「三房那小子，从前是我的心病。你来了，病好了。」","options":[{"text":"是他自己好的","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你道：「药是我开的，病是他自己治的。」孙老爷道：「开药的也是功。」","source":"宋代家训之语。"},{"text":"公公言重了","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"孙老爷道：「不重。这个家有你，是孙家三代修来的。」","source":"同上。"}],"difficulty":1,"npc":["孙老爷"],"foreshadow":"心病已愈","flavor":true},{"id":"A-118","branch":"A","stage":5,"day":118,"shichen":"辰时","checkpoint":"心意总账","scene":"正月廿四。周年将近，你取出「心意联单」盘点——从新婚夜那把钥匙记到如今，整整一百一十八笔。","options":[{"text":"一笔一笔重读","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"添灯、留门、分蟹、画醋坛……一百多笔读下来，笑了又哭，哭了又笑。","source":"宋代夫妇笺记之雅，见宋代笔记。"},{"text":"请他一起读","correct":false,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"两人挤在灯下读了一晚。读到某笔，他说：「那天的蟹黄，其实都给你了。」","source":"同上。"}],"difficulty":1,"npc":[],"foreshadow":"联单一百笔"},{"id":"A-118-未","branch":"A","stage":5,"day":118,"shichen":"未时","checkpoint":"心意总账·二","scene":"未时，你提笔盘「总账」：这一年，他为你记了六十笔，你为他记了五十八笔。","options":[{"text":"他多了两笔","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你「不服」，当场补记：「今日他研墨一锭」「今日他添灯一盏」。平了。","source":"宋代夫妻谐趣之记，见话本。"},{"text":"账平心更平","correct":false,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"谁多谁少不重要。联单的意义不在平衡，在于——都记着。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"心意盘平"},{"id":"A-118-戌","branch":"A","stage":5,"day":118,"shichen":"戌时","checkpoint":"心意总账·三","scene":"戌时，联单盘点毕。你把它装进孙夫人给的那只描金小匣——匣里凤钗压着联单。","options":[{"text":"钗账同匣","correct":true,"tags":["情缘","家世","感情"],"dims":{"情缘":1,"家世":1},"feedback":"凤钗是「家认你」，联单是「他认你」。一匣两样，是这年最重的家当。","source":"宋代奁匣之记，见宋代笔记。"},{"text":"合上再打开","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「看了三遍了。」你道：「好东西，经得起盘账。」","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"钗账同匣","flavor":true},{"id":"A-119","branch":"A","stage":5,"day":119,"shichen":"辰时","checkpoint":"周年前夜","scene":"正月廿五。明日就是成婚周年。你照常开柜理事——行里人都知道，没人敢提，都在憋着。","options":[{"text":"装作不知道","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你核你的账。只是笔尖，总往明日的日期上飘。","source":"宋代闺中情趣之记，见宋代笔记。"},{"text":"偷偷备了菜","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你让杏儿把房里收拾了，又亲自验了一遍明晚的菜。","source":"同上。"}],"difficulty":1,"npc":["杏儿","伙计们"],"foreshadow":"憋着不说"},{"id":"A-119-未","branch":"A","stage":5,"day":119,"shichen":"未时","checkpoint":"周年前夜·二","scene":"未时，两家人都「恰好」来了：娘送点心，孙夫人送果子，弟弟送对联——都说是顺路。","options":[{"text":"心领不点破","correct":true,"tags":["家世","感情"],"dims":{"家世":2},"feedback":"你收下所有的「顺路」。这辈子的顺路，都是爱你的人绕的道。","source":"宋代亲族往还之记，见宋代笔记。"},{"text":"一一谢过","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"谢了一圈，娘笑你：「自家人，谢什么。」——是啊，自家人。","source":"同上。"}],"difficulty":1,"npc":["娘","孙夫人","弟弟"],"foreshadow":"顺路之礼"},{"id":"A-119-戌","branch":"A","stage":5,"day":119,"shichen":"戌时","checkpoint":"周年前夜·三","scene":"戌时，前夜。他在灯下写东西，避着你。你也不问——你也在备：一册整理好的联单，明日给他。","options":[{"text":"灯下各自备礼","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"灯下两个影子，各写各的。这一年最后的夜，安静得像新婚那夜。","source":"宋代夫妇赠答之雅，见宋代笔记。"},{"text":"早点安歇","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"他道：「明日要早起。」你道：「嗯，大日子。」——谁都没睡踏实。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"前夜灯下","flavor":true},{"id":"A-120","branch":"A","stage":5,"day":120,"shichen":"辰时","checkpoint":"成婚周年","scene":"正月廿六·成婚周年。晨起，杏儿为你梳的还是妇人髻——只是今日她在髻边插了支新簪，笑而不语。","options":[{"text":"簪是他备的","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"镜中一看就懂了：簪头刻着一把小算盘——全汴京独一份的情话。","source":"宋代赠簪之记，见宋代笔记。"},{"text":"对镜整妆","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"一年前的今日，对镜是新娘；今日对镜，是行主，是妻，是自己。","source":"同上。"}],"difficulty":1,"npc":["杏儿"],"foreshadow":"算盘簪","flavor":true},{"id":"A-120-未","branch":"A","stage":5,"day":120,"shichen":"未时","checkpoint":"成婚周年·二","scene":"未时，园中周年宴。两家人齐聚，沈娘子也赶到了。爹和孙老爷合力揭开一块新匾——「岁时百年」。","options":[{"text":"匾下谢众人","correct":true,"tags":["名声","家世","感情"],"dims":{"名声":1,"家世":1},"feedback":"沈娘子举杯：「敬汴京的账房娘子。」孙夫人补：「敬我们家的行主。」","source":"宋代宴集之记，见宋代笔记。"},{"text":"拉住他的手","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"满座喧哗里，你悄悄握住他的手。一年了，这双手还是最先找到你。","source":"同上。"}],"difficulty":1,"npc":["沈娘子","孙夫人","爹","孙老爷"],"foreshadow":"岁时百年","flavor":true},{"id":"A-120-戌","branch":"A","stage":5,"day":120,"shichen":"戌时","checkpoint":"成婚周年·三","scene":"戌时，宴散人归。你们并肩站在门口，他点起一盏灯——灯上端端正正挂着今日日期：成婚周年。一如当年提亲那盏。","options":[{"text":"嫁的是挂灯人","correct":true,"tags":["情缘","自主","感情"],"dims":{"情缘":2,"自主":1},"feedback":"「会出嫁吗」的答案：嫁的是把婚期挂上灯笼的人，立的是自己这双算账的手。","source":"宋代灯彩婚俗之记，见《东京梦华录》。"},{"text":"账和人都在","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"一百二十日，账立住了，人守住了。汴京灯火万里，你这一盏，是自己点的。","source":"同上。"}],"difficulty":1,"npc":["孙公子"],"foreshadow":"挂灯之人","finale":true}];
